window.HSG_CONTENT = {"1":"\u003ch2\u003eCHUYÊN ĐỀ 1: KỸ THUẬT TRỒNG TRỌT \u0026 CANH TÁC BỀN VỮNG\u003c/h2\u003e\u003cp\u003e\u003cem\u003eT\u0026#224;i liệu Bồi dưỡng Học sinh giỏi THCS m\u0026#244;n C\u0026#244;ng nghệ (Chương tr\u0026#236;nh GDPT 2018)\u003c/em\u003e\u003c/p\u003e\u003ch3\u003eI. MỤC TIÊU ÔN LUYỆN CHUYÊN ĐỀ\u003c/h3\u003e\u003ch2\u003eChuyên đề 1 giúp học sinh giỏi đạt được các mục tiêu trọng tâm sau:\u003c/h2\u003e\u003cp\u003e\u003cstrong\u003eVề kiến thức nền:\u003c/strong\u003e Nắm vững to\u0026#224;n bộ quy tr\u0026#236;nh kỹ thuật trồng trọt (l\u0026#224;m đất, gieo trồng, chăm s\u0026#243;c, ph\u0026#242;ng trừ s\u0026#226;u bệnh, thu hoạch, bảo quản) v\u0026#224; c\u0026#225;c phương ph\u0026#225;p nh\u0026#226;n giống v\u0026#244; t\u0026#237;nh c\u0026#226;y trồng.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eVề bản chất khoa học:\u003c/strong\u003e Giải th\u0026#237;ch được cơ sở sinh học v\u0026#224; nguy\u0026#234;n l\u0026#253; kỹ thuật của từng kh\u0026#226;u canh t\u0026#225;c; hiểu r\u0026#245; bản chất nguy\u0026#234;n tắc \u0026#39;Ph\u0026#242;ng l\u0026#224; ch\u0026#237;nh\u0026#39; trong bảo vệ thực vật v\u0026#224; cơ chế sinh l\u0026#253; của c\u0026#226;y trồng.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eVề kiến thức mở rộng:\u003c/strong\u003e Cập nhật xu hướng n\u0026#244;ng nghiệp c\u0026#244;ng nghệ cao (thủy canh, kh\u0026#237; canh, nh\u0026#224; m\u0026#224;ng), ti\u0026#234;u chuẩn VietGAP v\u0026#224; nguy\u0026#234;n l\u0026#253; canh t\u0026#225;c sinh th\u0026#225;i n\u0026#244;ng nghiệp bền vững.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eVề năng lực HSG:\u003c/strong\u003e R\u0026#232;n luyện kỹ năng ph\u0026#226;n t\u0026#237;ch, so s\u0026#225;nh, giải th\u0026#237;ch hiện tượng thực tiễn, đề xuất giải ph\u0026#225;p kỹ thuật th\u0026#226;n thiện m\u0026#244;i trường v\u0026#224; lập kế hoạch, t\u0026#237;nh to\u0026#225;n chi ph\u0026#237; dự \u0026#225;n trồng trọt.\u003c/p\u003e\u003ch3\u003eII. KIẾN THỨC NỀN CẦN NHỚ\u003c/h3\u003e\u003ch3\u003e1. Quy trình kỹ thuật trồng trọt và mục đích từng bước\u003c/h3\u003e\u003cp\u003eQuy tr\u0026#236;nh trồng trọt chuẩn gồm 4 bước nối tiếp bắt buộc:\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eBước 1: Chuẩn bị đất trồng (L\u0026#224;m đất \u0026amp; B\u0026#243;n ph\u0026#226;n l\u0026#243;t): \u003c/strong\u003eGồm c\u0026#224;y đất (l\u0026#224;m x\u0026#225;o trộn lớp đất mặt từ 20-30 cm, l\u0026#224;m tăng bề d\u0026#224;y lớp đất trồng, ch\u0026#244;n v\u0026#249;i cỏ dại, l\u0026#224;m đất tơi xốp), bừa/đập đất (l\u0026#224;m nhỏ đất, thu gom cỏ dại, trộn đều ph\u0026#226;n b\u0026#243;n) v\u0026#224; l\u0026#234;n luống (chống ngập \u0026#250;ng, tạo tầng đất d\u0026#224;y, dễ chăm s\u0026#243;c). B\u0026#243;n ph\u0026#226;n l\u0026#243;t l\u0026#224; b\u0026#243;n ph\u0026#226;n v\u0026#224;o đất trước khi gieo trồng nhằm chuẩn bị sẵn thức ăn cho c\u0026#226;y hấp thụ ngay khi rễ ph\u0026#225;t triển.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eBước 2: Gieo trồng: \u003c/strong\u003eGồm gieo hạt (\u0026#225;p dụng cho c\u0026#226;y ngắn ng\u0026#224;y như l\u0026#250;a, ng\u0026#244;, đỗ, rau) v\u0026#224; trồng c\u0026#226;y con (\u0026#225;p dụng cho cả c\u0026#226;y ngắn ng\u0026#224;y v\u0026#224; d\u0026#224;i ng\u0026#224;y). Y\u0026#234;u cầu kỹ thuật bắt buộc: Đ\u0026#250;ng thời vụ, đ\u0026#250;ng khoảng c\u0026#225;ch, mật độ v\u0026#224; độ s\u0026#226;u gieo trồng.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eBước 3: Chăm s\u0026#243;c c\u0026#226;y trồng: \u003c/strong\u003eGồm tỉa/dặm c\u0026#226;y (đảm bảo khoảng c\u0026#225;ch, mật độ hợp l\u0026#253;); l\u0026#224;m cỏ, vun xới (giảm cạnh tranh dinh dưỡng, hạn chế nơi tr\u0026#250; ẩn của s\u0026#226;u bệnh, giữ c\u0026#226;y đứng vững); tưới/ti\u0026#234;u nước (đảm bảo đủ ẩm, tr\u0026#225;nh h\u0026#233;o hoặc \u0026#250;ng rễ); b\u0026#243;n ph\u0026#226;n th\u0026#250;c (cung cấp bổ sung dinh dưỡng kịp thời theo từng thời kỳ sinh trưởng).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eBước 4: Thu hoạch \u0026amp; Bảo quản: \u003c/strong\u003eThu hoạch đ\u0026#250;ng thời điểm, nhanh gọn, cẩn thận để giảm tối đa hao hụt lượng v\u0026#224; chất lượng. Bảo quản bằng c\u0026#225;c phương ph\u0026#225;p: bảo quản thường (kho), bảo quản lạnh, bảo quản k\u0026#237;n hoặc h\u0026#250;t ch\u0026#226;n kh\u0026#244;ng.\u003c/p\u003e\u003ch3\u003e2. Phân bón lót và Phân bón thúc trong trồng trọt\u003c/h3\u003e\u003cp\u003ePh\u0026#226;n biệt r\u0026#245; mục đ\u0026#237;ch v\u0026#224; loại ph\u0026#226;n b\u0026#243;n sử dụng cho hai thời kỳ b\u0026#243;n ph\u0026#226;n ch\u0026#237;nh:\u003cbr\u003e\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eTi\u0026#234;u ch\u0026#237;\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eB\u0026#243;n ph\u0026#226;n l\u0026#243;t\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eB\u0026#243;n ph\u0026#226;n th\u0026#250;c\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eMục đ\u0026#237;ch\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eCung cấp dinh dưỡng dự trữ cho đất, chuẩn bị \u0026#39;thức ăn\u0026#39; sẵn cho c\u0026#226;y khi mới ra rễ.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eCung cấp dinh dưỡng bổ sung kịp thời cho từng giai đoạn sinh trưởng mạnh (ra l\u0026#225;, đẻ nh\u0026#225;nh, ra hoa, tạo quả).\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eThời điểm\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eTrước khi gieo hạt hoặc trồng c\u0026#226;y con (khi l\u0026#224;m đất).\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eTrong qu\u0026#225; tr\u0026#236;nh sinh trưởng v\u0026#224; ph\u0026#225;t triển của c\u0026#226;y.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eLoại ph\u0026#226;n\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003ePh\u0026#226;n hữu cơ hoai mục, ph\u0026#226;n vi sinh, ph\u0026#226;n l\u0026#226;n (chậm tan, t\u0026#225;c dụng k\u0026#233;o d\u0026#224;i).\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003ePh\u0026#226;n h\u0026#243;a học dễ tan (đạm, kali, NPK), ph\u0026#226;n hữu cơ vi sinh tan nhanh.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003ch3\u003e3. Khái niệm và các phương pháp nhân giống vô tính\u003c/h3\u003e\u003cp\u003eNh\u0026#226;n giống v\u0026#244; t\u0026#237;nh l\u0026#224; h\u0026#236;nh thức tạo ra c\u0026#226;y giống trực tiếp từ c\u0026#225;c bộ phận sinh dưỡng (l\u0026#225;, th\u0026#226;n, rễ) của c\u0026#226;y mẹ. C\u0026#226;y con giữ nguy\u0026#234;n c\u0026#225;c đặc t\u0026#237;nh di truyền của c\u0026#226;y mẹ.\u003cbr\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eGi\u0026#226;m c\u0026#224;nh:\u003c/strong\u003e Cắt một đoạn c\u0026#224;nh b\u0026#225;nh tẻ (kh\u0026#244;ng qu\u0026#225; non hoặc qu\u0026#225; gi\u0026#224;, c\u0026#243; đủ mắt), xử l\u0026#253; chất k\u0026#237;ch th\u0026#237;ch ra rễ rồi cắm xuống đất ẩm để c\u0026#224;nh ra rễ v\u0026#224; ph\u0026#225;t triển th\u0026#224;nh c\u0026#226;y mới. \u0026#193;p dụng: rau ng\u0026#243;t, khoai lang, hoa hồng, r\u0026#226;m bụt.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eChiết c\u0026#224;nh:\u003c/strong\u003e Chọn c\u0026#224;nh khỏe tr\u0026#234;n c\u0026#226;y mẹ, b\u0026#243;c một đoạn vỏ, bọc hỗn hợp đất ẩm/gi\u0026#225; thể quanh vết b\u0026#243;c. Khi đoạn c\u0026#224;nh mọc rễ th\u0026#236; cắt rời đem trồng. \u0026#193;p dụng: c\u0026#226;y ăn quả (cam, bưởi, nh\u0026#227;n, vải).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eGh\u0026#233;p:\u003c/strong\u003e D\u0026#249;ng một bộ phận sinh dưỡng của một c\u0026#226;y (mắt gh\u0026#233;p, chồi gh\u0026#233;p, c\u0026#224;nh gh\u0026#233;p) gắn v\u0026#224;o một c\u0026#226;y kh\u0026#225;c (gốc gh\u0026#233;p) rồi buộc chặt để ch\u0026#250;ng liền xương v\u0026#224; ph\u0026#225;t triển c\u0026#249;ng nhau. \u0026#193;p dụng: xo\u0026#224;i, t\u0026#225;o, hồng xi\u0026#234;m, c\u0026#226;y cảnh.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eNu\u0026#244;i cấy m\u0026#244; tế b\u0026#224;o:\u003c/strong\u003e Phương ph\u0026#225;p nh\u0026#226;n giống hiện đại trong ph\u0026#242;ng th\u0026#237; nghiệm, tạo ra số lượng rất lớn c\u0026#226;y giống đồng đều, sạch bệnh từ tế b\u0026#224;o/m\u0026#244; ph\u0026#226;n sinh.\u003c/p\u003e\u003ch3\u003eIII. KIẾN THỨC CẦN HIỂU SÂU BẢN CHẤT\u003c/h3\u003e\u003ch3\u003e1. Bản chất sinh học và kỹ thuật của khâu Làm đất\u003c/h3\u003e\u003cp\u003eL\u0026#224;m đất kh\u0026#244;ng đơn thuần l\u0026#224; hoạt động cơ học m\u0026#224; l\u0026#224; t\u0026#225;c động trực tiếp l\u0026#234;n hệ sinh th\u0026#225;i đất:\u003cbr\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eCơ chế tho\u0026#225;ng kh\u0026#237;: \u003c/strong\u003eĐất tơi xốp l\u0026#224;m tăng thể t\u0026#237;ch khe hở kh\u0026#244;ng kh\u0026#237; trong đất, gi\u0026#250;p rễ c\u0026#226;y hấp thụ O2 dễ d\u0026#224;ng cho qu\u0026#225; tr\u0026#236;nh h\u0026#244; hấp tế b\u0026#224;o rễ, giải ph\u0026#243;ng năng lượng để chủ động h\u0026#250;t nước v\u0026#224; kho\u0026#225;ng chất.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eCơ chế vi sinh vật: \u003c/strong\u003eTăng cường hoạt động của vi sinh vật hiếu kh\u0026#237; (vi sinh vật cố định đạm, ph\u0026#226;n giải l\u0026#226;n, ph\u0026#226;n giải chất hữu cơ), biến c\u0026#225;c chất dinh dưỡng kh\u0026#243; tan th\u0026#224;nh dạng ion dễ tan (NH4+, NO3-, H2PO4-) cho c\u0026#226;y.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eDiệt mầm bệnh: \u003c/strong\u003eC\u0026#224;y lật đất phơi ải gi\u0026#250;p \u0026#225;nh nắng mặt trời v\u0026#224; tia cực t\u0026#237;m ti\u0026#234;u diệt trứng s\u0026#226;u, vi khuẩn, nấm bệnh tồn dư trong đất từ vụ trước.\u003c/p\u003e\u003ch3\u003e2. Bản chất nguyên tắc \u0027Phòng là chính\u0027 trong Bảo vệ thực vật\u003c/h3\u003e\u003cp\u003eTrong trồng trọt, lu\u0026#244;n phải tu\u0026#226;n thủ nguy\u0026#234;n tắc \u0026#39;Ph\u0026#242;ng l\u0026#224; ch\u0026#237;nh\u0026#39; v\u0026#236; c\u0026#225;c l\u0026#253; do bản chất sau:\u003cbr\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eChi ph\u0026#237; kinh tế:\u003c/strong\u003e Chi ph\u0026#237; ph\u0026#242;ng bệnh (vệ sinh đồng ruộng, d\u0026#249;ng giống chống chịu, lu\u0026#226;n canh) lu\u0026#244;n thấp hơn rất nhiều so với chi ph\u0026#237; mua thuốc h\u0026#243;a học v\u0026#224; khắc phục hậu quả khi dịch b\u0026#249;ng ph\u0026#225;t.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eBảo vệ năng suất v\u0026#224; chất lượng:\u003c/strong\u003e Khi dịch bệnh đ\u0026#227; ph\u0026#225;t sinh, dịch b\u0026#224;o v\u0026#224; m\u0026#244; c\u0026#226;y đ\u0026#227; bị tổn thương, c\u0026#226;y bị mất diện t\u0026#237;ch quang hợp, d\u0026#249; chữa khỏi th\u0026#236; năng suất v\u0026#224; chất lượng sản phẩm vẫn bị sụt giảm nặng nề.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eAn to\u0026#224;n sinh th\u0026#225;i \u0026amp; sức khỏe:\u003c/strong\u003e Sử dụng thuốc bảo vệ thực vật h\u0026#243;a học để trừ s\u0026#226;u bệnh g\u0026#226;y \u0026#244; nhiễm m\u0026#244;i trường đất, nước, ti\u0026#234;u diệt thi\u0026#234;n địch c\u0026#243; \u0026#237;ch, dễ để lại dư lượng h\u0026#243;a chất độc hại trong n\u0026#244;ng sản g\u0026#226;y mất an to\u0026#224;n thực phẩm.\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eĐIỂM NHẤN BẢN CHẤT: \u003c/strong\u003eNội dung \u0026#39;Biện ph\u0026#225;p canh t\u0026#225;c v\u0026#224; giống chống chịu\u0026#39; l\u0026#224; nền tảng của nguy\u0026#234;n tắc Ph\u0026#242;ng l\u0026#224; ch\u0026#237;nh. Sử dụng giống chống chịu gi\u0026#250;p c\u0026#226;y ngăn chặn sự x\u0026#226;m nhập của mầm bệnh ngay từ đầu m\u0026#224; kh\u0026#244;ng cần can thiệp h\u0026#243;a chất.\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003ch3\u003eIV. KIẾN THỨC MỞ RỘNG \u0026 ĐÀO SÂU HSG\u003c/h3\u003e\u003ch3\u003e1. Trồng trọt công nghệ cao (High-tech Agriculture)\u003c/h3\u003e\u003cp\u003eTrồng trọt c\u0026#244;ng nghệ cao l\u0026#224; việc ứng dụng c\u0026#225;c c\u0026#244;ng nghệ hiện đại (tự động h\u0026#243;a, CNTT, c\u0026#244;ng nghệ sinh học, vật liệu mới) nhằm tối ưu h\u0026#243;a điều kiện sinh trưởng của c\u0026#226;y trồng:\u003cbr\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eM\u0026#244; h\u0026#236;nh Nh\u0026#224; m\u0026#224;ng / Nh\u0026#224; k\u0026#237;nh th\u0026#244;ng minh:\u003c/strong\u003e Kiểm so\u0026#225;t ho\u0026#224;n to\u0026#224;n nhiệt độ, độ ẩm, \u0026#225;nh s\u0026#225;ng, nồng độ CO2. Gi\u0026#250;p trồng rau, hoa quanh năm, kh\u0026#244;ng phụ thuộc thời tiết, ngăn ngừa triệt để c\u0026#244;n tr\u0026#249;ng x\u0026#226;m nhập.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eHệ thống Thủy canh (Hydroponics):\u003c/strong\u003e Trồng c\u0026#226;y ho\u0026#224;n to\u0026#224;n kh\u0026#244;ng d\u0026#249;ng đất, rễ c\u0026#226;y ng\u0026#226;m trực tiếp hoặc tiếp x\u0026#250;c với dung dịch dinh dưỡng được chuẩn bị ch\u0026#237;nh x\u0026#225;c theo nhu cầu từng loại c\u0026#226;y.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eHệ thống Kh\u0026#237; canh (Aeroponics):\u003c/strong\u003e Rễ c\u0026#226;y treo trong kh\u0026#244;ng kh\u0026#237; v\u0026#224; được phun dinh dưỡng dạng sương mịn theo chu kỳ tự động. Gi\u0026#250;p tiết kiệm 95% nước v\u0026#224; 90% ph\u0026#226;n b\u0026#243;n so với canh t\u0026#225;c đất.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#244;ng nghệ tưới nhỏ giọt (Drip Irrigation):\u003c/strong\u003e Cung cấp nước v\u0026#224; ph\u0026#226;n b\u0026#243;n h\u0026#242;a tan trực tiếp đến từng gốc c\u0026#226;y với liều lượng ch\u0026#237;nh x\u0026#225;c, tr\u0026#225;nh l\u0026#227;ng ph\u0026#237; nước v\u0026#224; ngăn nấm bệnh ph\u0026#225;t triển do ướt l\u0026#225;.\u003c/p\u003e\u003ch3\u003e2. Quy trình và tiêu chuẩn VietGAP trong nông nghiệp sạch\u003c/h3\u003e\u003cp\u003eVietGAP (Vietnamese Good Agricultural Practices) l\u0026#224; quy tr\u0026#236;nh thực h\u0026#224;nh sản xuất n\u0026#244;ng nghiệp tốt tại Việt Nam, bao gồm 4 ti\u0026#234;u ch\u0026#237; cốt l\u0026#245;i:\u003cbr\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e1. An to\u0026#224;n thực phẩm:\u003c/strong\u003e Kh\u0026#244;ng để n\u0026#244;ng sản bị nhiễm h\u0026#243;a chất, vi sinh vật g\u0026#226;y hại hoặc kim loại nặng qu\u0026#225; ngưỡng cho ph\u0026#233;p.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e2. An to\u0026#224;n m\u0026#244;i trường:\u003c/strong\u003e Kh\u0026#244;ng l\u0026#224;m \u0026#244; nhiễm nguồn nước, đất đai v\u0026#224; hệ sinh th\u0026#225;i xung quanh khu vực canh t\u0026#225;c.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e3. Sức khỏe v\u0026#224; an to\u0026#224;n lao động:\u003c/strong\u003e Bảo vệ sức khỏe người sản xuất, trang bị đầy đủ bảo hộ lao động khi sử dụng vật tư n\u0026#244;ng nghiệp.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e4. Truy xuất nguồn gốc sản phẩm:\u003c/strong\u003e Ghi ch\u0026#233;p nhật k\u0026#253; canh t\u0026#225;c đầy đủ để phục vụ kiểm tra v\u0026#224; minh bạch nguồn gốc n\u0026#244;ng sản.\u003c/p\u003e\u003ch3\u003e3. Canh tác sinh thái \u0026 Nông nghiệp bền vững\u003c/h3\u003e\u003cp\u003eN\u0026#244;ng nghiệp bền vững hướng tới sự c\u0026#226;n bằng giữa hiệu quả kinh tế, c\u0026#244;ng bằng x\u0026#227; hội v\u0026#224; bảo vệ m\u0026#244;i trường sinh th\u0026#225;i. C\u0026#225;c giải ph\u0026#225;p kỹ thuật cốt l\u0026#245;i gồm:\u003cbr\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eXen canh (Intercropping):\u003c/strong\u003e Trồng hai hay nhiều loại c\u0026#226;y tr\u0026#234;n c\u0026#249;ng một diện t\u0026#237;ch v\u0026#224;o c\u0026#249;ng một thời gian. V\u0026#237; dụ: Xen c\u0026#226;y họ Đậu v\u0026#224;o vườn ng\u0026#244;/c\u0026#226;y ăn quả để vi khuẩn nốt rễ Rhizobium cố định đạm tự nhi\u0026#234;n, cải tạo đất v\u0026#224; tăng dung t\u0026#237;ch sử dụng kh\u0026#244;ng gian/\u0026#225;nh s\u0026#225;ng.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eLu\u0026#226;n canh (Crop Rotation):\u003c/strong\u003e Trồng lu\u0026#226;n phi\u0026#234;n c\u0026#225;c loại c\u0026#226;y trồng kh\u0026#225;c họ tr\u0026#234;n c\u0026#249;ng một diện t\u0026#237;ch qua c\u0026#225;c vụ kh\u0026#225;c nhau. Cơ chế: Cắt đứt chu kỳ sống v\u0026#224; nguồn thức ăn của s\u0026#226;u bệnh chuy\u0026#234;n khoa; điều h\u0026#242;a khả năng h\u0026#250;t dinh dưỡng ở c\u0026#225;c tầng đất kh\u0026#225;c nhau.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eTăng cường Thi\u0026#234;n địch (Biological Control):\u003c/strong\u003e Bảo vệ v\u0026#224; nh\u0026#226;n nu\u0026#244;i c\u0026#225;c lo\u0026#224;i sinh vật c\u0026#243; \u0026#237;ch (bọ r\u0026#249;a, ong mắt đỏ, nhện ăn thịt, ếch nh\u0026#225;i) để khống chế mật độ s\u0026#226;u hại tự nhi\u0026#234;n m\u0026#224; kh\u0026#244;ng cần d\u0026#249;ng thuốc h\u0026#243;a học.\u003c/p\u003e\u003ch3\u003eV. MỐI LIÊN HỆ GIỮA CÁC KIẾN THỨC \u0026 SƠ ĐỒ HỆ THỐNG HÓA\u003c/h3\u003e\u003ch3\u003e1. Mối quan hệ tương hỗ trong hệ thống Kỹ thuật Trồng trọt\u003c/h3\u003e\u003cp\u003eC\u0026#225;c yếu tố kỹ thuật trong trồng trọt kh\u0026#244;ng hoạt động ri\u0026#234;ng rẽ m\u0026#224; tạo th\u0026#224;nh một chuỗi mắt x\u0026#237;ch hữu cơ kh\u0026#233;p k\u0026#237;n:\u003cbr\u003e• Đất trồng tơi xốp → Gi\u0026#250;p hệ rễ ph\u0026#225;t triển mạnh → Tăng khả năng hấp thụ Ph\u0026#226;n b\u0026#243;n → C\u0026#226;y khỏe mạnh → Tăng sức đề kh\u0026#225;ng tự nhi\u0026#234;n với S\u0026#226;u bệnh hại → N\u0026#226;ng cao Năng suất \u0026amp; Chất lượng thu hoạch.\u003cbr\u003e• Nếu bỏ qua một kh\u0026#226;u (v\u0026#237; dụ: đất bị n\u0026#233;n chặt hoặc thiếu nước), d\u0026#249; sử dụng giống tốt v\u0026#224; ph\u0026#226;n b\u0026#243;n đắt tiền th\u0026#236; c\u0026#226;y vẫn kh\u0026#244;ng thể đạt năng suất tối đa.\u003c/p\u003e\u003ch3\u003e2. Bảng so sánh tổng hợp các phương pháp Nhân giống vô tính\u003c/h3\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eTi\u0026#234;u ch\u0026#237;\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eGi\u0026#226;m c\u0026#224;nh\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eChiết c\u0026#224;nh\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eGh\u0026#233;p\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eĐối tượng \u0026#225;p dụng\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eC\u0026#226;y th\u0026#226;n thảo, c\u0026#226;y bụi, c\u0026#224;nh dễ ra rễ (rau ng\u0026#243;t, hoa hồng, khoai lang).\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eC\u0026#226;y ăn quả th\u0026#226;n gỗ kh\u0026#243; ra rễ bằng gi\u0026#226;m c\u0026#224;nh (cam, bưởi, nh\u0026#227;n, vải).\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eC\u0026#226;y ăn quả, c\u0026#226;y cảnh muốn kết hợp ưu thế gốc gh\u0026#233;p v\u0026#224; c\u0026#224;nh gh\u0026#233;p.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eƯu điểm\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eĐơn giản, dễ l\u0026#224;m, hệ số nh\u0026#226;n giống nhanh, chi ph\u0026#237; thấp.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eC\u0026#226;y con sớm ra hoa tạo quả, giữ nguy\u0026#234;n đặc t\u0026#237;nh tốt của c\u0026#226;y mẹ.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eKết hợp được đặc t\u0026#237;nh chống chịu của gốc gh\u0026#233;p v\u0026#224; chất lượng tốt của mắt gh\u0026#233;p.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eNhược điểm\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eY\u0026#234;u cầu c\u0026#224;nh gi\u0026#226;m c\u0026#243; khả năng ra rễ phụ tốt.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eHệ số nh\u0026#226;n giống thấp, l\u0026#224;m ảnh hưởng/tổn thương c\u0026#226;y mẹ.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eKỹ thuật phức tạp, đ\u0026#242;i hỏi thao t\u0026#225;c kh\u0026#233;o l\u0026#233;o v\u0026#224; tỉ lệ sống phụ thuộc tay nghề.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003ch3\u003e3. Bảng so sánh các Biện pháp Phòng trừ sâu, bệnh hại cây trồng\u003c/h3\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eBiện ph\u0026#225;p\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eCơ sở / C\u0026#225;ch thực hiện\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eƯu điểm\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eNhược điểm\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eCanh t\u0026#225;c \u0026amp; Giống\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eL\u0026#224;m đất, vệ sinh đồng ruộng, lu\u0026#226;n canh, d\u0026#249;ng giống chống chịu.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eAn to\u0026#224;n, chi ph\u0026#237; thấp, bền vững, ngăn ngừa bệnh từ gốc.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eT\u0026#225;c dụng chậm, đ\u0026#242;i hỏi t\u0026#237;nh đồng bộ tr\u0026#234;n diện rộng.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eThủ c\u0026#244;ng\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eBắt s\u0026#226;u, ngắt l\u0026#225; bệnh, d\u0026#249;ng bẫy đ\u0026#232;n, vợt.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eĐơn giản, dễ l\u0026#224;m, kh\u0026#244;ng \u0026#244; nhiễm m\u0026#244;i trường.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eTốn c\u0026#244;ng lao động, hiệu quả thấp khi s\u0026#226;u bệnh b\u0026#249;ng ph\u0026#225;t mạnh.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eH\u0026#243;a học\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003ePhun/rắc thuốc bảo vệ thực vật h\u0026#243;a học.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eDiệt s\u0026#226;u bệnh cực nhanh, dập dịch kịp thời.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eG\u0026#226;y \u0026#244; nhiễm m\u0026#244;i trường, độc hại, dễ g\u0026#226;y b\u0026#249;ng ph\u0026#225;t dịch thứ cấp.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eSinh học\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eD\u0026#249;ng thi\u0026#234;n địch (ong mắt đỏ, bọ r\u0026#249;a), chế phẩm vi sinh.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eHiệu quả cao, an to\u0026#224;n sinh th\u0026#225;i, kh\u0026#244;ng g\u0026#226;y độc hại.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eM\u0026#244;i trường bảo quản chế phẩm khắt khe, t\u0026#225;c dụng chậm hơn h\u0026#243;a học.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003ch3\u003eVI. NHỮNG ĐIỂM DỄ NHẦM LẪN VÀ LỖI THƯỜNG GẶP\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003e1. Nhầm lẫn giữa Lu\u0026#226;n canh v\u0026#224; Xen canh:\u003c/strong\u003e\u003cbr\u003e• Lu\u0026#226;n canh l\u0026#224; lu\u0026#226;n phi\u0026#234;n c\u0026#225;c loại c\u0026#226;y trồng kh\u0026#225;c nhau TR\u0026#202;N C\u0026#217;NG MỘT THỬA ĐẤT QUA C\u0026#193;C THỜI GIAN/VỤ HỌC KH\u0026#193;C NHAU (yếu tố thời gian).\u003cbr\u003e• Xen canh l\u0026#224; trồng c\u0026#249;ng l\u0026#250;c hai hay nhiều loại c\u0026#226;y TR\u0026#202;N C\u0026#217;NG MỘT DIỆN T\u0026#205;CH V\u0026#192; C\u0026#217;NG MỘT THỜI GIAN (yếu tố kh\u0026#244;ng gian).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e2. Nhầm lẫn giữa Ph\u0026#226;n b\u0026#243;n l\u0026#243;t v\u0026#224; Ph\u0026#226;n b\u0026#243;n th\u0026#250;c:\u003c/strong\u003e\u003cbr\u003e• B\u0026#243;n l\u0026#243;t d\u0026#249;ng ph\u0026#226;n chậm tan (hữu cơ hoai mục, l\u0026#226;n) b\u0026#243;n TRƯỚC KHI TRỒNG.\u003cbr\u003e• B\u0026#243;n th\u0026#250;c d\u0026#249;ng ph\u0026#226;n dễ tan (đạm, kali) b\u0026#243;n TRONG QU\u0026#193; TR\u0026#204;NH C\u0026#194;Y ĐANG CẦN DINH DƯỠNG S\u0026#205;NH TRƯỞNG.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e3. Sai lầm khi Phun thuốc bảo vệ thực vật h\u0026#243;a học:\u003c/strong\u003e\u003cbr\u003e• Phun thuốc ngược chiều gi\u0026#243; hoặc phun l\u0026#250;c trời mưa/nắng gắt (l\u0026#224;m thuốc bị rửa tr\u0026#244;i hoặc bay hơi).\u003cbr\u003e• Tăng nồng độ thuốc qu\u0026#225; quy định (g\u0026#226;y ch\u0026#225;y l\u0026#225; c\u0026#226;y, g\u0026#226;y kh\u0026#225;ng thuốc ở s\u0026#226;u bệnh).\u003cbr\u003e• Kh\u0026#244;ng đảm bảo thời gian c\u0026#225;ch ly (vẫn thu hoạch b\u0026#225;n khi thuốc chưa ph\u0026#226;n hủy hết g\u0026#226;y ngộ độc cho người d\u0026#249;ng).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e4. Lỗi chọn c\u0026#224;nh Gi\u0026#226;m v\u0026#224; c\u0026#224;nh Chiết:\u003c/strong\u003e\u003cbr\u003e• C\u0026#224;nh gi\u0026#226;m phải chọn c\u0026#224;nh b\u0026#225;nh tẻ (kh\u0026#244;ng qu\u0026#225; non v\u0026#236; dễ rữa, kh\u0026#244;ng qu\u0026#225; gi\u0026#224; v\u0026#236; kh\u0026#243; ra rễ).\u003cbr\u003e• B\u0026#243;c vỏ chiết c\u0026#224;nh phải cạo sạch lớp m\u0026#244; ph\u0026#226;n sinh gỗ để tr\u0026#225;nh liền vỏ lại.\u003c/p\u003e\u003ch3\u003eVII. CÁC DẠNG CÂU HỎI HSG \u0026 PHƯƠNG PHÁP TƯ DUY - GIẢI BÀI\u003c/h3\u003e\u003ch3\u003eDạng 1: Phân tích quy trình kỹ thuật và Giải thích cơ sở khoa học\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003ePhương ph\u0026#225;p tư duy: \u003c/strong\u003eKhi đề b\u0026#224;i y\u0026#234;u cầu \u0026#39;Tr\u0026#236;nh b\u0026#224;y quy tr\u0026#236;nh v\u0026#224; ph\u0026#226;n t\u0026#237;ch mục đ\u0026#237;ch...\u0026#39;, học sinh cần thực hiện 2 bước:\u003cbr\u003e• Bước 1: Liệt k\u0026#234; đầy đủ, ch\u0026#237;nh x\u0026#225;c t\u0026#234;n c\u0026#225;c bước theo đ\u0026#250;ng thứ tự logic.\u003cbr\u003e• Bước 2: Với mỗi bước, n\u0026#234;u r\u0026#245; t\u0026#225;c động kỹ thuật l\u0026#224;m thay đổi đặc t\u0026#237;nh đất/c\u0026#226;y v\u0026#224; gi\u0026#225; trị sinh học mang lại (tại sao phải l\u0026#224;m vậy, nếu kh\u0026#244;ng l\u0026#224;m th\u0026#236; hậu quả g\u0026#236;).\u003c/p\u003e\u003ch3\u003eDạng 2: So sánh, Phân tích ưu/nhược điểm và Lựa chọn giải pháp\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003ePhương ph\u0026#225;p tư duy: \u003c/strong\u003eLập bảng so s\u0026#225;nh theo c\u0026#225;c ti\u0026#234;u ch\u0026#237; r\u0026#245; r\u0026#224;ng (Cơ sở, Hiệu quả, Chi ph\u0026#237;, M\u0026#244;i trường). Khi đề xuất giải ph\u0026#225;p, lu\u0026#244;n phải đứng tr\u0026#234;n quan điểm n\u0026#244;ng nghiệp bền vững (ưu ti\u0026#234;n biện ph\u0026#225;p sinh học, canh t\u0026#225;c xanh, giảm thiểu h\u0026#243;a chất).\u003c/p\u003e\u003ch3\u003eDạng 3: Bài tập Tình huống thực tiễn và Lập kế hoạch chi phí\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003ePhương ph\u0026#225;p tư duy: \u003c/strong\u003eXử l\u0026#253; b\u0026#224;i tập lập kế hoạch theo 4 nội dung chuẩn:\u003cbr\u003e1. X\u0026#225;c định r\u0026#245; đối tượng c\u0026#226;y trồng, quy m\u0026#244; v\u0026#224; phương thức trồng.\u003cbr\u003e2. Tự thiết kế bảng dự tr\u0026#249; vật tư gồm: C\u0026#226;y/hạt giống, Đất/Gi\u0026#225; thể, Khay/Chậu, Ph\u0026#226;n b\u0026#243;n, Dụng cụ.\u003cbr\u003e3. \u0026#193;p dụng c\u0026#244;ng thức: Th\u0026#224;nh tiền = Số lượng \u0026#215; Đơn gi\u0026#225;; Tổng chi ph\u0026#237; = ∑ Th\u0026#224;nh tiền.\u003cbr\u003e4. Đề xuất c\u0026#225;c giải ph\u0026#225;p tiết kiệm chi ph\u0026#237; thực tế (tận dụng th\u0026#249;ng xốp, tự ủ ph\u0026#226;n hữu cơ).\u003c/p\u003e\u003ch3\u003eVIII. NGÂN HÀNG BÀI TẬP HỌC SINH GIỎI CHUYÊN ĐỀ 1\u003c/h3\u003e\u003ch3\u003e1. Mức độ Nhận biết - Thông hiểu (3,0 điểm)\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 1 (3,0 điểm): \u003c/strong\u003eTr\u0026#236;nh b\u0026#224;y đầy đủ quy tr\u0026#236;nh kỹ thuật trồng trọt một loại c\u0026#226;y trồng phổ biến ở địa phương em (l\u0026#250;a, rau hoặc c\u0026#226;y ăn quả) v\u0026#224; ph\u0026#226;n t\u0026#237;ch vai tr\u0026#242; kỹ thuật của từng bước trong quy tr\u0026#236;nh đ\u0026#243;.\u003c/p\u003e\u003ch3\u003e2. Mức độ Vận dụng (3,0 điểm)\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 2 (3,0 điểm): \u003c/strong\u003eTại sao trong c\u0026#244;ng t\u0026#225;c ph\u0026#242;ng trừ s\u0026#226;u, bệnh hại c\u0026#226;y trồng, người ta lại lấy nguy\u0026#234;n tắc \u0026#39;Ph\u0026#242;ng l\u0026#224; ch\u0026#237;nh\u0026#39; l\u0026#224;m chủ đạo? H\u0026#227;y ph\u0026#226;n t\u0026#237;ch c\u0026#225;c ưu điểm của việc ứng dụng c\u0026#225;c biện ph\u0026#225;p canh t\u0026#225;c (lu\u0026#226;n canh, xen canh, cải tạo đất) kết hạn chế tối đa việc sử dụng thuốc bảo vệ thực vật h\u0026#243;a học.\u003c/p\u003e\u003ch3\u003e3. Mức độ Vận dụng cao \u0026 Phân hóa (3,0 điểm)\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 3 (3,0 điểm): \u003c/strong\u003eMột n\u0026#244;ng d\u0026#226;n nhận thấy vườn cam nh\u0026#224; m\u0026#236;nh bị s\u0026#226;u bệnh ph\u0026#225; hại nặng. \u0026#212;ng định mua thuốc h\u0026#243;a học nồng độ cao về phun li\u0026#234;n tục 3 ng\u0026#224;y/lần v\u0026#224; thu hoạch cam ngay sau khi phun 2 ng\u0026#224;y để kịp b\u0026#225;n được gi\u0026#225;. Em h\u0026#227;y d\u0026#249;ng kiến thức m\u0026#244;n C\u0026#244;ng nghệ để ph\u0026#226;n t\u0026#237;ch 3 t\u0026#225;c hại nguy hiểm từ việc l\u0026#224;m của b\u0026#225;c n\u0026#244;ng d\u0026#226;n. Từ đ\u0026#243;, đề xuất quy tr\u0026#236;nh quản l\u0026#253; dịch hại tổng hợp (IPM) gi\u0026#250;p b\u0026#225;c n\u0026#244;ng d\u0026#226;n vừa bảo vệ được vườn cam vừa đảm bảo an to\u0026#224;n thực phẩm.\u003c/p\u003e\u003ch3\u003e4. Bài tập Tình huống thực tiễn \u0026 Lập kế hoạch chi phí (3,0 điểm)\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 4 (3,0 điểm): \u003c/strong\u003eTrường em ph\u0026#225;t động dự \u0026#225;n \u0026#39;Vườn rau an to\u0026#224;n trong nh\u0026#224; trường\u0026#39; tr\u0026#234;n diện t\u0026#237;ch 20 m2. Em h\u0026#227;y:\u003cbr\u003ea) Lập bảng dự tr\u0026#249; nguy\u0026#234;n vật liệu v\u0026#224; t\u0026#237;nh to\u0026#225;n tổng chi ph\u0026#237; để triển khai trồng rau cải xanh theo quy chuẩn an to\u0026#224;n.\u003cbr\u003eb) Tr\u0026#236;nh b\u0026#224;y c\u0026#225;c bước trong quy tr\u0026#236;nh gieo trồng v\u0026#224; chăm s\u0026#243;c rau cải xanh từ khi l\u0026#224;m đất đến khi thu hoạch.\u003cbr\u003ec) Đề xuất 2 biện ph\u0026#225;p kỹ thuật gi\u0026#250;p giảm chi ph\u0026#237; đầu tư ban đầu m\u0026#224; vẫn đảm bảo ti\u0026#234;u chuẩn rau an to\u0026#224;n.\u003c/p\u003e\u003ch3\u003eIX. ĐÁP ÁN VÀ HƯỚNG DẪN CHẤM CHI TIẾT\u003c/h3\u003e\u003cp\u003e\u003cem\u003eCăn cứ chuẩn Đ\u0026#225;p \u0026#225;n Đề thi HSG Vĩnh Long (Thang điểm 20.0 cho b\u0026#224;i thi tổng hợp)\u003c/em\u003e\u003c/p\u003e\u003ch3\u003eĐáp án Câu 1 (3,0 điểm)\u003c/h3\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eNội dung cần đạt\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eĐiểm\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003ea) Tr\u0026#236;nh b\u0026#224;y đ\u0026#250;ng 4 bước trong quy tr\u0026#236;nh trồng trọt:\u003cbr\u003e- Bước 1: Chuẩn bị đất trồng (l\u0026#224;m đất, b\u0026#243;n ph\u0026#226;n l\u0026#243;t).\u003cbr\u003e- Bước 2: Gieo trồng (gieo hạt hoặc trồng c\u0026#226;y con).\u003cbr\u003e- Bước 3: Chăm s\u0026#243;c c\u0026#226;y trồng.\u003cbr\u003e- Bước 4: Thu hoạch sản phẩm.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e1,0đ\u003cbr\u003e(0,25đ/bước)\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eb) Ph\u0026#226;n t\u0026#237;ch đ\u0026#250;ng vai tr\u0026#242; kỹ thuật của từng bước:\u003cbr\u003e- Chuẩn bị đất: L\u0026#224;m đất tơi xốp, đủ dinh dưỡng, loại bỏ cỏ dại, mầm s\u0026#226;u bệnh hại; b\u0026#243;n l\u0026#243;t chuẩn bị thức ăn cho rễ mới ph\u0026#225;t triển.\u003cbr\u003e- Gieo trồng: Đ\u0026#250;ng thời vụ, đ\u0026#250;ng kỹ thuật gi\u0026#250;p c\u0026#226;y ph\u0026#225;t triển thuận lợi, đạt mật độ tối ưu, cho năng suất cao.\u003cbr\u003e- Chăm s\u0026#243;c: Nu\u0026#244;i dưỡng, bảo vệ, kịp thời cung cấp nước/dinh dưỡng v\u0026#224; ph\u0026#242;ng trừ yếu tố g\u0026#226;y hại cho c\u0026#226;y.\u003cbr\u003e- Thu hoạch: Đảm bảo thu được số lượng v\u0026#224; chất lượng sản phẩm tối đa, đạt ti\u0026#234;u chuẩn thị trường.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e2,0đ\u003cbr\u003e(0,5đ/\u0026#253;)\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003ch3\u003eĐáp án Câu 2 (3,0 điểm)\u003c/h3\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eNội dung cần đạt\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eĐiểm\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003ea) Giải th\u0026#237;ch l\u0026#253; do lấy nguy\u0026#234;n tắc \u0026#39;Ph\u0026#242;ng l\u0026#224; ch\u0026#237;nh\u0026#39; l\u0026#224;m chủ đạo:\u003cbr\u003e- Chi ph\u0026#237; ph\u0026#242;ng bệnh thấp hơn rất nhiều so với chi ph\u0026#237; mua thuốc dập dịch.\u003cbr\u003e- Bảo vệ c\u0026#226;y kh\u0026#244;ng bị tổn thương m\u0026#244;/diện t\u0026#237;ch quang hợp, giữ vững năng suất v\u0026#224; chất lượng.\u003cbr\u003e- Tr\u0026#225;nh được việc sử dụng h\u0026#243;a chất độc hại g\u0026#226;y \u0026#244; nhiễm m\u0026#244;i trường v\u0026#224; mất an to\u0026#224;n thực phẩm.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e1,0đ\u003cbr\u003e(0,33đ/\u0026#253;)\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eb) Ph\u0026#226;n t\u0026#237;ch ưu điểm của biện ph\u0026#225;p canh t\u0026#225;c v\u0026#224; hạn chế thuốc h\u0026#243;a học:\u003cbr\u003e- Cải tạo đất, tăng độ tơi xốp v\u0026#224; diệt mầm bệnh s\u0026#226;u bệnh tồn dư trong đất.\u003cbr\u003e- Cắt đứt chu kỳ sống của s\u0026#226;u bệnh (lu\u0026#226;n canh) v\u0026#224; tăng cường quần thể thi\u0026#234;n địch c\u0026#243; \u0026#237;ch (xen canh).\u003cbr\u003e- Hạn chế h\u0026#243;a chất gi\u0026#250;p bảo vệ m\u0026#244;i trường đất/nước, bảo vệ sức khỏe người ti\u0026#234;u d\u0026#249;ng.\u003cbr\u003e- Đảm bảo c\u0026#226;n bằng hệ sinh th\u0026#225;i đồng ruộng v\u0026#224; tiết kiệm chi ph\u0026#237; mua vật tư h\u0026#243;a học.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e2,0đ\u003cbr\u003e(0,5đ/\u0026#253;)\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003ch3\u003eĐáp án Câu 3 (3,0 điểm)\u003c/h3\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eNội dung cần đạt\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eĐiểm\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003ea) Ph\u0026#226;n t\u0026#237;ch 3 t\u0026#225;c hại từ việc l\u0026#224;m của b\u0026#225;c n\u0026#244;ng d\u0026#226;n:\u003cbr\u003e1. Phun thuốc nồng độ qu\u0026#225; cao \u0026amp; li\u0026#234;n tục: G\u0026#226;y ch\u0026#225;y l\u0026#225; cam, l\u0026#224;m ti\u0026#234;u diệt to\u0026#224;n bộ thi\u0026#234;n địch c\u0026#243; \u0026#237;ch, dẫn đến s\u0026#226;u hại b\u0026#249;ng ph\u0026#225;t mạnh hơn do kh\u0026#225;ng thuốc.\u003cbr\u003e2. \u0026#212; nhiễm m\u0026#244;i trường \u0026amp; đất đai: Thuốc h\u0026#243;a học ngấm xuống đất v\u0026#224; nguồn nước ngầm, l\u0026#224;m suy tho\u0026#225;i đất v\u0026#224; độc hại m\u0026#244;i trường xung quanh.\u003cbr\u003e3. Vi phạm thời gian c\u0026#225;ch ly (thu hoạch sau 2 ng\u0026#224;y): Dư lượng thuốc bảo vệ thực vật độc hại chưa kịp ph\u0026#226;n hủy sẽ tồn dư trong quả cam, g\u0026#226;y ngộ độc cấp t\u0026#237;nh hoặc m\u0026#227;n t\u0026#237;nh cho người ti\u0026#234;u d\u0026#249;ng.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e1,5đ\u003cbr\u003e(0,5đ/t\u0026#225;c hại)\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eb) Đề xuất quy tr\u0026#236;nh Quản l\u0026#253; dịch hại tổng hợp (IPM):\u003cbr\u003e- Ưu ti\u0026#234;n sử dụng giống cam khỏe, b\u0026#243;n ph\u0026#226;n hữu cơ c\u0026#226;n đối để tăng sức đề kh\u0026#225;ng.\u003cbr\u003e- Thường xuy\u0026#234;n vệ sinh vườn, cắt tỉa c\u0026#224;nh s\u0026#226;u bệnh để tạo độ th\u0026#244;ng tho\u0026#225;ng.\u003cbr\u003e- Bật bẫy đ\u0026#232;n, bẫy d\u0026#237;nh hoặc nh\u0026#226;n nu\u0026#244;i thi\u0026#234;n địch (nhện ăn thịt, ong mắt đỏ) để diệt s\u0026#226;u.\u003cbr\u003e- Chỉ phun thuốc h\u0026#243;a học khi dịch b\u0026#249;ng ph\u0026#225;t vượt ngưỡng g\u0026#226;y hại kinh tế; phải chọn thuốc sinh học, phun đ\u0026#250;ng nồng độ v\u0026#224; tu\u0026#226;n thủ nghi\u0026#234;m ngặt thời gian c\u0026#225;ch ly.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e1,5đ\u003cbr\u003e(0,375đ/\u0026#253;)\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003ch3\u003eĐáp án Câu 4 (3,0 điểm)\u003c/h3\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eNội dung cần đạt\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eĐiểm\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003ea) Lập bảng kế hoạch chi ph\u0026#237; dự tr\u0026#249; cho 20 m2 rau cải xanh:\u003cbr\u003e- Hạt giống cải xanh: 0.1 kg x 150.000 đ/kg = 15.000 đ.\u003cbr\u003e- Ph\u0026#226;n hữu cơ vi sinh: 20 kg x 10.000 đ/kg = 200.000 đ.\u003cbr\u003e- Đất vi sinh/xơ dừa bổ sung: 4 bao x 50.000 đ/bao = 200.000 đ.\u003cbr\u003e- Dụng cụ tưới \u0026amp; v\u0026#244;i bột xử l\u0026#253; đất: 85.000 đ.\u003cbr\u003e=\u0026gt; TỔNG CHI PH\u0026#205; DỰ TR\u0026#217;: 500.000 đồng.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e1,0đ\u003cbr\u003e(C\u0026#243; bảng + t\u0026#237;nh to\u0026#225;n đ\u0026#250;ng)\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eb) Quy tr\u0026#236;nh kỹ thuật gieo trồng v\u0026#224; chăm s\u0026#243;c:\u003cbr\u003e- L\u0026#224;m đất: Cuốc đất, đập nhỏ, b\u0026#243;n l\u0026#243;t ph\u0026#226;n hữu cơ vi sinh, rắc v\u0026#244;i phơi ải 3-5 ng\u0026#224;y, l\u0026#234;n luống cao 15-20cm.\u003cbr\u003e- Gieo hạt: Gieo hạt đều tr\u0026#234;n mặt luống, phủ lớp rơm rạ hoặc gi\u0026#225; thể mỏng, tưới ẩm.\u003cbr\u003e- Chăm s\u0026#243;c: Tưới nước 2 lần/ng\u0026#224;y (s\u0026#225;ng sớm, chiều m\u0026#225;t); tỉa dặm đảm bảo khoảng c\u0026#225;ch 10-15cm/c\u0026#226;y; bắt s\u0026#226;u thủ c\u0026#244;ng.\u003cbr\u003e- Thu hoạch: Thu hoạch sau 25-30 ng\u0026#224;y, d\u0026#249;ng dao cắt s\u0026#225;t gốc nhẹ nh\u0026#224;ng.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e1,0đ\u003cbr\u003e(0,25đ/bước)\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003ec) 2 biện ph\u0026#225;p giảm chi ph\u0026#237; m\u0026#224; vẫn đảm bảo rau an to\u0026#224;n:\u003cbr\u003e- Biện ph\u0026#225;p 1: Tận dụng nguồn phế phụ phẩm n\u0026#244;ng nghiệp (vỏ trứng, m\u0026#249;n cưa, rau thừa) để tự ủ ph\u0026#226;n hữu cơ vi sinh tại trường.\u003cbr\u003e- Biện ph\u0026#225;p 2: Tự l\u0026#224;m chế phẩm sinh học bảo vệ thực vật từ gừng, tỏi, ớt ng\u0026#226;m rượu để xịt ph\u0026#242;ng s\u0026#226;u bệnh thay v\u0026#236; mua thuốc.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e1,0đ\u003cbr\u003e(0,5đ/biện ph\u0026#225;p)\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003ch3\u003eX. PHẦN GHI NHỚ NHANH \u003c/h3\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eT\u0026#211;M TẮT CỐT L\u0026#213;I (KHI MỜI CỞI KHỞI ĐẦU B\u0026#192;I THI): \u003c/strong\u003e1. QUY TR\u0026#204;NH TRỒNG TRỌT: L\u0026#224;m đất \u0026amp; B\u0026#243;n l\u0026#243;t → Gieo trồng → Chăm s\u0026#243;c → Thu hoạch \u0026amp; Bảo quản.\u003cbr\u003e2. B\u0026#211;N PH\u0026#194;N: B\u0026#243;n l\u0026#243;t (Trước khi trồng - Ph\u0026#226;n chậm tan) | B\u0026#243;n th\u0026#250;c (Khi c\u0026#226;y sinh trưởng - Ph\u0026#226;n dễ tan).\u003cbr\u003e3. L\u0026#192;M ĐẤT: C\u0026#224;y (X\u0026#225;o trộn 20-30cm, tăng bề d\u0026#224;y) | Bừa (L\u0026#224;m nhỏ đất) | L\u0026#234;n luống (Chống ngập \u0026#250;ng).\u003cbr\u003e4. NH\u0026#194;N GIỐNG V\u0026#212; T\u0026#205;NH: Gi\u0026#226;m c\u0026#224;nh (Rau ng\u0026#243;t, hoa hồng) | Chiết c\u0026#224;nh (C\u0026#226;y ăn quả cam, bưởi) | Gh\u0026#233;p (Mắt/c\u0026#224;nh gh\u0026#233;p + Gốc gh\u0026#233;p).\u003cbr\u003e5. BẢO VỆ THỰC VẬT: Nguy\u0026#234;n tắc \u0026#39;PH\u0026#210;NG L\u0026#192; CH\u0026#205;NH\u0026#39; | Lu\u0026#226;n canh (C\u0026#249;ng đất - Kh\u0026#225;c thời gian) | Xen canh (C\u0026#249;ng đất - C\u0026#249;ng thời gian).\u003cbr\u003e6. N\u0026#212;NG NGHIỆP C\u0026#212;NG NGHỆ CAO: Thủy canh (Kh\u0026#244;ng d\u0026#249;ng đất) | Kh\u0026#237; canh (Phun sương dinh dưỡng) | VietGAP (4 ti\u0026#234;u ch\u0026#237;: An to\u0026#224;n TP, M\u0026#244;i trường, Lao động, Truy xuất).\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e","2":"\u003ch2\u003eCHUYÊN ĐỀ 2: NUÔI DƯỠNG, CHĂM SÓC VÀ PHÒNG, TRỊ BỆNH CHO VẬT NUÔI\u003c/h2\u003e\u003cp\u003e\u003cem\u003eCăn cứ C\u0026#244;ng văn 730/SGDĐT-GDPT Vĩnh Long \u0026amp; Bộ SGK/SGV/SBT C\u0026#244;ng nghệ 7 (KNTT)\u003c/em\u003e\u003cem\u003e\u003cbr\u003eCấu tr\u0026#250;c thi HSG: Tự luận 100% - Thời gian l\u0026#224;m b\u0026#224;i: 150 ph\u0026#250;t - Thang điểm: 20\u003c/em\u003e\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003e📌 ĐỊNH HƯỚNG TRỌNG T\u0026#194;M CỦA C\u0026#212;NG VĂN 730 VỀ MẠCH NỘI DUNG CHĂN NU\u0026#212;I\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e1. Nu\u0026#244;i dưỡng, chăm s\u0026#243;c vật nu\u0026#244;i: Ph\u0026#226;n t\u0026#237;ch bản chất sinh l\u0026#253; c\u0026#225;c giai đoạn ph\u0026#225;t triển (vật nu\u0026#244;i non, đực giống, c\u0026#225;i sinh sản, g\u0026#224; thịt) v\u0026#224; mục đ\u0026#237;ch kỹ thuật của từng kh\u0026#226;u chăm s\u0026#243;c.\u003c/p\u003e\u003cp\u003e2. Ph\u0026#242;ng v\u0026#224; trị bệnh vật nu\u0026#244;i: Nguy\u0026#234;n tắc \u0026#39;Ph\u0026#242;ng bệnh hơn chữa bệnh\u0026#39;, cơ chế t\u0026#225;c dụng của vắc xin, so s\u0026#225;nh hiệu quả kinh tế v\u0026#224; sức khỏe vật nu\u0026#244;i khi thực hiện tốt vs kh\u0026#244;ng tốt c\u0026#244;ng t\u0026#225;c ph\u0026#242;ng bệnh.\u003c/p\u003e\u003cp\u003e3. An to\u0026#224;n dịch bệnh \u0026amp; Bảo vệ m\u0026#244;i trường: Giải ph\u0026#225;p an to\u0026#224;n sinh học, xử l\u0026#253; chất thải chăn nu\u0026#244;i (Biogas, ủ ph\u0026#226;n hữu cơ) v\u0026#224; đảm bảo ph\u0026#250;c lợi động vật theo quy định hiện h\u0026#224;nh.\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003ch2\u003ePHẦN I: HỆ THỐNG KIẾN THỐC NỀN VÀ CHUYÊN SÂU\u003c/h2\u003e\u003ch3\u003e1. Vai trò và ý nghĩa của nuôi dưỡng, chăm sóc và phòng, trị bệnh cho vật nuôi\u003c/h3\u003e\u003cp\u003eChăn nu\u0026#244;i hiện đại kh\u0026#244;ng chỉ dừng lại ở việc cung cấp thức ăn m\u0026#224; l\u0026#224; một hệ thống t\u0026#225;c động kỹ thuật to\u0026#224;n diện nhằm tối ưu h\u0026#243;a tiềm năng sinh học của giống vật nu\u0026#244;i v\u0026#224; bảo đảm an to\u0026#224;n dịch bệnh, bảo vệ m\u0026#244;i trường.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eKh\u0026#225;i niệm Nu\u0026#244;i dưỡng: \u003c/strong\u003el\u0026#224; qu\u0026#225; tr\u0026#236;nh cung cấp cho vật nu\u0026#244;i đầy đủ chất dinh dưỡng (chất đạm, tinh bột, chất b\u0026#233;o, vitamin v\u0026#224; chất kho\u0026#225;ng) về cả lượng v\u0026#224; chất, ph\u0026#249; hợp với từng giai đoạn sinh trưởng v\u0026#224; từng đối tượng vật nu\u0026#244;i. Nu\u0026#244;i dưỡng quyết định sự ph\u0026#225;t triển thể chất v\u0026#224; năng suất sản phẩm.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eKh\u0026#225;i niệm Chăm s\u0026#243;c: \u003c/strong\u003el\u0026#224; qu\u0026#225; tr\u0026#236;nh con người thường xuy\u0026#234;n quan t\u0026#226;m tạo ra m\u0026#244;i trường sống (nhiệt độ, độ ẩm, \u0026#225;nh s\u0026#225;ng, độ th\u0026#244;ng tho\u0026#225;ng) ph\u0026#249; hợp trong chuồng nu\u0026#244;i, giữ vệ sinh chuồng trại sạch sẽ v\u0026#224; chăm s\u0026#243;c sức khỏe thể chất để vật nu\u0026#244;i sống thoải m\u0026#225;i, khỏe mạnh.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eVai tr\u0026#242; tổng qu\u0026#225;t: \u003c/strong\u003eGi\u0026#250;p vật nu\u0026#244;i khỏe mạnh, lớn nhanh, tăng sức đề kh\u0026#225;ng, giảm tỷ lệ mắc bệnh, khai th\u0026#225;c tối đa năng suất v\u0026#224; chất lượng sản phẩm chăn nu\u0026#244;i (thịt, trứng, sữa), mang lại hiệu quả kinh tế cao cho người chăn nu\u0026#244;i.\u003c/p\u003e\u003ch4\u003eKhái niệm Phúc lợi động vật (Animal Welfare) trong Chăn nuôi\u003c/h4\u003e\u003cp\u003ePh\u0026#250;c lợi động vật l\u0026#224; việc đối xử tốt với vật nu\u0026#244;i để ch\u0026#250;ng c\u0026#243; trạng th\u0026#225;i thể chất v\u0026#224; tinh thần tốt nhất, tr\u0026#225;nh những đau đớn kh\u0026#244;ng đ\u0026#225;ng c\u0026#243;. Theo Luật Chăn nu\u0026#244;i 2018, ph\u0026#250;c lợi động vật được đ\u0026#225;nh gi\u0026#225; qua ti\u0026#234;u chuẩn \u0026#39;5 Kh\u0026#244;ng\u0026#39;:\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e1. Kh\u0026#244;ng bị đ\u0026#243;i kh\u0026#225;t: \u003c/strong\u003eĐược cung cấp đầy đủ nước sạch v\u0026#224; thức ăn ph\u0026#249; hợp.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e2. Kh\u0026#244;ng bị kh\u0026#243; chịu về thể x\u0026#225;c: \u003c/strong\u003eC\u0026#243; chuồng trại che chắn nắng mưa, gi\u0026#243; l\u0026#249;a, kh\u0026#244;ng gian thoải m\u0026#225;i.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e3. Kh\u0026#244;ng bị đau đớn, thương tật, bệnh tật: \u003c/strong\u003eĐược ph\u0026#242;ng bệnh chủ động v\u0026#224; điều trị kịp thời khi bị thương/bệnh.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e4. Kh\u0026#244;ng bị sợ h\u0026#227;i v\u0026#224; lo \u0026#226;u: \u003c/strong\u003eĐược sống trong m\u0026#244;i trường th\u0026#226;n thiện, kh\u0026#244;ng bị ngược đ\u0026#227;i.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e5. Tự do thể hiện c\u0026#225;c h\u0026#224;nh vi tự nhi\u0026#234;n: \u003c/strong\u003eC\u0026#243; kh\u0026#244;ng gian vận động v\u0026#224; thể hiện c\u0026#225;c tập t\u0026#237;nh tự nhi\u0026#234;n của lo\u0026#224;i.\u003c/p\u003e\u003ch3\u003e2. Kỹ thuật nuôi dưỡng và chăm sóc các nhóm vật nuôi\u003c/h3\u003e\u003ch4\u003e2.1. Vật nuôi non (Gia súc con, gà con/gia cầm con)\u003c/h4\u003e\u003cp\u003eVật nu\u0026#244;i non c\u0026#243; những đặc điểm sinh l\u0026#253; đặc th\u0026#249; rất nhạy cảm với m\u0026#244;i trường ngoại cảnh, đ\u0026#242;i hỏi quy tr\u0026#236;nh chăm s\u0026#243;c đặc biệt nghi\u0026#234;m ngặt:\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eĐặc điểm sinh l\u0026#253; của vật nu\u0026#244;i non\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eBiện ph\u0026#225;p kỹ thuật nu\u0026#244;i dưỡng \u0026amp; chăm s\u0026#243;c tương ứng\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e1. Khả năng điều tiết th\u0026#226;n nhiệt chưa ho\u0026#224;n chỉnh:\u003cbr\u003eLớp mỡ dưới da mỏng, đường glycogen dự trữ \u0026#237;t, trung khu thần kinh điều khiển th\u0026#226;n nhiệt chưa ho\u0026#224;n thiện n\u0026#234;n dễ bị hạ th\u0026#226;n nhiệt khi r\u0026#233;t.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e• Giữ ấm chuồng nu\u0026#244;i, chăm s\u0026#243;c chu đ\u0026#225;o.\u003cbr\u003e• Sử dụng đ\u0026#232;n sưởi (sưởi ấm qu\u0026#226;y \u0026#250;m cho g\u0026#224; con, l\u0026#224;m s\u0026#224;n l\u0026#243;t ấm cho lợn con/b\u0026#234; con), tr\u0026#225;nh gi\u0026#243; l\u0026#249;a.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e2. Khả năng miễn dịch chưa tốt, sức đề kh\u0026#225;ng k\u0026#233;m:\u003cbr\u003eHệ miễn dịch chưa ho\u0026#224;n thiện, lượng kh\u0026#225;ng thể trong m\u0026#225;u l\u0026#250;c mới sinh rất thấp (chỉ ~1,3% ở lợn con).\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e• Cho con non b\u0026#250; sữa đầu của mẹ c\u0026#224;ng sớm c\u0026#224;ng tốt (trong v\u0026#242;ng 24 giờ đầu).\u003cbr\u003e• Giữ vệ sinh chuồng nu\u0026#244;i sạch sẽ, kh\u0026#244; r\u0026#225;o, ti\u0026#234;m vắc xin ph\u0026#242;ng bệnh đầy đủ.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e3. Chức năng hệ ti\u0026#234;u h\u0026#243;a chưa ho\u0026#224;n chỉnh:\u003cbr\u003eC\u0026#225;c enzym ti\u0026#234;u h\u0026#243;a chưa đầy đủ, dạ d\u0026#224;y v\u0026#224; ruột nhỏ, dễ bị tổn thương bởi thức ăn th\u0026#244; cứng.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e• Cho b\u0026#250; sữa mẹ ho\u0026#224;n to\u0026#224;n giai đoạn đầu.\u003cbr\u003e• Tập cho ăn sớm (từ 7 - 10 ng\u0026#224;y tuổi) bằng thức ăn dễ ti\u0026#234;u, gi\u0026#224;u dinh dưỡng để k\u0026#237;ch th\u0026#237;ch hệ ti\u0026#234;u h\u0026#243;a ph\u0026#225;t triển.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e4. Nhu cầu ph\u0026#225;t triển khung xương v\u0026#224; thể chất nhanh:\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e• Cho vật nu\u0026#244;i non vận động nhẹ nh\u0026#224;ng v\u0026#224; tiếp x\u0026#250;c với \u0026#225;nh nắng mặt trời v\u0026#224;o buổi s\u0026#225;ng sớm để tổng hợp Vitamin D, gi\u0026#250;p hấp thụ Canxi chống r\u0026#242;i xương.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003e💡 BẢN CHẤT KHOA HỌC CỦA SỮA ĐẦU (COLOSTRUM)\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e• Sữa đầu l\u0026#224; sữa được tiết ra trong 3 - 7 ng\u0026#224;y đầu sau khi sinh. Sữa đầu chứa h\u0026#224;m lượng chất dinh dưỡng cao, đặc biệt rất gi\u0026#224;u KH\u0026#193;NG THỂ (Immunoglobulin - IgA, IgG).\u003c/p\u003e\u003cp\u003e• Do hệ miễn dịch của gia s\u0026#250;c con chưa tự sản xuất được kh\u0026#225;ng thể, việc b\u0026#250; sữa đầu gi\u0026#250;p gia s\u0026#250;c con hấp thu kh\u0026#225;ng thể trực tiếp qua ni\u0026#234;m mạc ruột (miễn dịch thụ động), gi\u0026#250;p cơ thể chống lại c\u0026#225;c mầm bệnh nguy hiểm trong giai đoạn đầu đời.\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003ch4\u003e2.2. Vật nuôi đực giống\u003c/h4\u003e\u003cp\u003e\u003cstrong\u003eMục đ\u0026#237;ch: \u003c/strong\u003eNhằm duy tr\u0026#236; thể trạng khỏe mạnh, cho khả năng phối giống tốt, t\u0026#237;nh hăng cao v\u0026#224; sản xuất tinh dịch c\u0026#243; chất lượng cao để tạo ra thế hệ con ch\u0026#225;u chất lượng tốt.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eY\u0026#234;u cầu nu\u0026#244;i dưỡng: \u003c/strong\u003eCung cấp khẩu phần ăn gi\u0026#224;u năng lượng, đủ chất đạm (protein), vitamin (A, D, E) v\u0026#224; chất kho\u0026#225;ng (Ca, P, Zn). Kh\u0026#244;ng cho ăn qu\u0026#225; thừa g\u0026#226;y b\u0026#233;o trệ hoặc qu\u0026#225; thiếu g\u0026#226;y gầy c\u0026#242;m.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eY\u0026#234;u cầu chăm s\u0026#243;c: \u003c/strong\u003eCho vật nu\u0026#244;i đực giống vận động thường xuy\u0026#234;n hằng ng\u0026#224;y, tắm rửa sạch sẽ, theo d\u0026#245;i khối lượng cơ thể v\u0026#224; kiểm tra định kỳ chất lượng tinh dịch.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003ePh\u0026#226;n t\u0026#237;ch t\u0026#225;c hại b\u0026#233;o/gầy: \u003c/strong\u003eNếu đực giống qu\u0026#225; b\u0026#233;o (thừa mỡ) sẽ l\u0026#224;m tho\u0026#225;i h\u0026#243;a mỡ ở tinh ho\u0026#224;n, giảm t\u0026#237;nh hăng phối giống v\u0026#224; giảm chất lượng tinh tr\u0026#249;ng. Ngược lại, nếu qu\u0026#225; gầy do thiếu dinh dưỡng th\u0026#236; phản xạ giao phối yếu, lượng tinh dịch \u0026#237;t v\u0026#224; tỷ lệ tinh tr\u0026#249;ng dị h\u0026#236;nh cao.\u003c/p\u003e\u003ch4\u003e2.3. Vật nuôi cái sinh sản\u003c/h4\u003e\u003cp\u003eQuy tr\u0026#236;nh nu\u0026#244;i dưỡng vật nu\u0026#244;i c\u0026#225;i sinh sản được chia th\u0026#224;nh 3 giai đoạn sinh l\u0026#253; r\u0026#245; rệt với nhu cầu dinh dưỡng kh\u0026#225;c nhau:\u003c/p\u003e\u003cp\u003e\u003cstrong\u003ea) Giai đoạn Hậu bị: \u003c/strong\u003eTừ khi cai sữa đến khi phối giống lần đầu. Cho ăn vừa phải để cơ thể ph\u0026#225;t triển c\u0026#226;n đối, kh\u0026#244;ng b\u0026#233;o mỡ (g\u0026#226;y kh\u0026#243; thụ thai) v\u0026#224; kh\u0026#244;ng qu\u0026#225; gầy.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eb) Giai đoạn Mang thai: \u003c/strong\u003eCung cấp đủ chất dinh dưỡng để nu\u0026#244;i thai nhi ph\u0026#225;t triển khỏe mạnh, t\u0026#237;ch lũy dinh dưỡng chuẩn bị cho kỳ tiết sữa. Tuy nhi\u0026#234;n kh\u0026#244;ng cho ăn qu\u0026#225; nhiều ở giai đoạn đầu để tr\u0026#225;nh thai qu\u0026#225; to g\u0026#226;y kh\u0026#243; đẻ.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003ec) Giai đoạn Đẻ con / Nu\u0026#244;i con / Đẻ trứng: \u003c/strong\u003eCho ăn tự do theo nhu cầu cao nhất để vật nu\u0026#244;i tiết nhiều sữa nu\u0026#244;i con (với gia s\u0026#250;c) hoặc đẻ nhiều trứng (với gia cầm). Khẩu phần ăn gi\u0026#224;u đạm, canxi v\u0026#224; c\u0026#225;c vi chất.\u003c/p\u003e\u003ch4\u003e2.4. Kỹ thuật nuôi dưỡng và chăm sóc gà thịt trong nông hộ\u003c/h4\u003e\u003cp\u003e\u003cstrong\u003eChuồng nu\u0026#244;i: \u003c/strong\u003eL\u0026#224;m ở nơi cao r\u0026#225;o, tho\u0026#225;ng m\u0026#225;t về m\u0026#249;a h\u0026#232;, ấm \u0026#225;p về m\u0026#249;a đ\u0026#244;ng, tr\u0026#225;nh gi\u0026#243; l\u0026#249;a v\u0026#224; \u0026#225;nh nắng gay gắt chiếu trực tiếp. Hướng chuồng n\u0026#234;n chọn hướng Đ\u0026#244;ng Nam hoặc Nam.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eLớp độn chuồng: \u003c/strong\u003eSử dụng trấu, dăm b\u0026#224;o hoặc m\u0026#249;n cưa kh\u0026#244; r\u0026#225;o, sạch sẽ l\u0026#243;t nền chuồng (d\u0026#224;y 10 - 15 cm) để giữ ấm, h\u0026#250;t ẩm v\u0026#224; giữ vệ sinh. C\u0026#243; thể l\u0026#243;t s\u0026#224;n bằng tre/gỗ tho\u0026#225;ng c\u0026#225;ch mặt đất.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eThức ăn \u0026amp; Cho ăn: \u003c/strong\u003eĐủ 4 nh\u0026#243;m chất (đạm, tinh bột, chất b\u0026#233;o, vitamin \u0026amp; kho\u0026#225;ng). G\u0026#224; dưới 1 th\u0026#225;ng tuổi cho ăn tự do thức ăn gi\u0026#224;u đạm; từ 1 - 3 th\u0026#225;ng tuổi cho ăn 3 - 4 lần/ng\u0026#224;y; tr\u0026#234;n 3 th\u0026#225;ng tuổi cho ăn tự do vỗ b\u0026#233;o xuất b\u0026#225;n.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eChăm s\u0026#243;c g\u0026#224; con (Giai đoạn \u0026#250;m): \u003c/strong\u003eSử dụng qu\u0026#226;y \u0026#250;m v\u0026#224; đ\u0026#232;n điện sưởi ấm. Quan s\u0026#225;t sự ph\u0026#226;n bố của g\u0026#224; con trong qu\u0026#226;y để điều chỉnh nhiệt độ: nếu g\u0026#224; ph\u0026#226;n bố đều l\u0026#224; nhiệt độ th\u0026#237;ch hợp; nếu tụ lại dưới đ\u0026#232;n l\u0026#224; bị lạnh; nếu tản ra xa đ\u0026#232;n, h\u0026#225; mỏ thở l\u0026#224; bị n\u0026#243;ng; nếu tụ về một ph\u0026#237;a l\u0026#224; c\u0026#243; gi\u0026#243; l\u0026#249;a.\u003c/p\u003e\u003ch3\u003e3. Nguyên nhân, phân loại và kỹ thuật phòng, trị bệnh cho vật nuôi\u003c/h3\u003e\u003cp\u003eBệnh l\u0026#224; trạng th\u0026#225;i kh\u0026#244;ng b\u0026#236;nh thường của vật nu\u0026#244;i về sinh l\u0026#253;, c\u0026#243; biểu hiện như buồn b\u0026#227;, ủ rũ, giảm/bỏ ăn, sốt, chảy nước mũi, ti\u0026#234;u chảy... l\u0026#224;m giảm khả năng sản xuất v\u0026#224; c\u0026#243; thể g\u0026#226;y chết.\u003c/p\u003e\u003ch4\u003e3.1. Các nguyên nhân gây bệnh cho vật nuôi\u003c/h4\u003e\u003cp\u003e\u003cstrong\u003e1. Vi sinh vật g\u0026#226;y bệnh: \u003c/strong\u003eDo vi khuẩn (như tụ huyết tr\u0026#249;ng, đ\u0026#243;ng dấu lợn, E.coli) hoặc virus (như dịch tả lợn Ch\u0026#226;u Phi, c\u0026#250;m gia cầm, Newcastle, lở mồm long m\u0026#243;ng). Đ\u0026#226;y l\u0026#224; nguy\u0026#234;n nh\u0026#226;n nguy hiểm nhất v\u0026#236; l\u0026#226;y lan nhanh th\u0026#224;nh dịch.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e2. Động vật k\u0026#253; sinh: \u003c/strong\u003eC\u0026#225;c loại giun, s\u0026#225;n, ve, rận, bọ tr\u0026#233;t sống b\u0026#225;m v\u0026#224;o cơ thể vật nu\u0026#244;i tranh đoạt dinh dưỡng hoặc g\u0026#226;y tổn thương m\u0026#244;.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e3. Dinh dưỡng \u0026amp; Thức ăn: \u003c/strong\u003eThức ăn bị \u0026#244;i thiu, nấm mốc, chứa chất độc hại hoặc khẩu phần ăn thiếu/thừa dinh dưỡng k\u0026#233;o d\u0026#224;i.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e4. M\u0026#244;i trường sống bất lợi: \u003c/strong\u003eThời tiết thay đổi đột ngột (qu\u0026#225; n\u0026#243;ng, qu\u0026#225; lạnh), độ ẩm cao, chuồng nu\u0026#244;i ngột nạt, \u0026#244; nhiễm chất thải.\u003c/p\u003e\u003ch4\u003ePhân biệt Bệnh Truyền nhiễm và Bệnh Không truyền nhiễm\u003c/h4\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eTi\u0026#234;u ch\u0026#237; so s\u0026#225;nh\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eBệnh Truyền nhiễm\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eBệnh Kh\u0026#244;ng truyền nhiễm (Bệnh th\u0026#244;ng thường)\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eNguy\u0026#234;n nh\u0026#226;n g\u0026#226;y bệnh\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eDo vi sinh vật g\u0026#226;y ra (vi khuẩn, virus).\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eDo k\u0026#253; sinh tr\u0026#249;ng, cơ học, dinh dưỡng, m\u0026#244;i trường.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eKhả năng l\u0026#226;y lan\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eL\u0026#226;y lan rất nhanh v\u0026#224; rộng từ con bệnh sang con khỏe.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eKh\u0026#244;ng l\u0026#226;y lan từ con bệnh sang con khỏe.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eMức độ nguy hiểm\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eTạo th\u0026#224;nh dịch bệnh, tử vong h\u0026#224;ng loạt, tổn thất kinh tế rất lớn.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eG\u0026#226;y hại lẻ tẻ, ảnh hưởng sức khỏe c\u0026#225; thể.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eV\u0026#237; dụ điển h\u0026#236;nh\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eC\u0026#250;m gia cầm (H5N1), Dịch tả lợn Ch\u0026#226;u Phi, Newcastle, Lở mồm long m\u0026#243;ng.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eBệnh c\u0026#242;i xương, bệnh giun s\u0026#225;n, cảm n\u0026#243;ng, ngộ độc thức ăn.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003ch4\u003e3.2. Nguyên tắc Nguyên lý Phòng và Trị bệnh\u003c/h4\u003e\u003cp\u003eTrong thực tiễn chăn nu\u0026#244;i, nguy\u0026#234;n tắc cốt l\u0026#245;i l\u0026#224; \u0026#39;PH\u0026#210;NG BỆNH HƠN CHỮA BỆNH\u0026#39;. Việc ph\u0026#242;ng bệnh chủ động mang lại lợi \u0026#237;ch to\u0026#224;n diện hơn rất nhiều so với việc chờ bệnh b\u0026#249;ng ph\u0026#225;t mới chữa trị:\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e1. Nu\u0026#244;i dưỡng tốt: \u003c/strong\u003eCho ăn uống đầy đủ dinh dưỡng, hợp vệ sinh, kh\u0026#244;ng d\u0026#249;ng thức ăn \u0026#244;i mốc.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e2. Chăm s\u0026#243;c chu đ\u0026#225;o: \u003c/strong\u003eChuồng trại vệ sinh, khử tr\u0026#249;ng định kỳ, tho\u0026#225;ng m\u0026#225;t m\u0026#249;a h\u0026#232;, ấm \u0026#225;p m\u0026#249;a đ\u0026#244;ng.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e3. Vệ sinh m\u0026#244;i trường: \u003c/strong\u003eQu\u0026#233;t dọn chuồng trại, thu gom v\u0026#224; xử l\u0026#253; chất thải triệt để.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e4. C\u0026#225;ch ly nguồn bệnh: \u003c/strong\u003eKhi ph\u0026#225;t hiện con bệnh phải c\u0026#225;ch ly ngay khỏi đ\u0026#224;n khỏe mạnh để tr\u0026#225;nh l\u0026#226;y lan.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e5. Ti\u0026#234;m ph\u0026#242;ng vắc xin đầy đủ: \u003c/strong\u003eSử dụng vắc xin điều chế từ mầm bệnh để ti\u0026#234;m ph\u0026#242;ng chủ động cho vật nu\u0026#244;i khỏe mạnh, gi\u0026#250;p cơ thể sinh ra miễn dịch chống lại mầm bệnh.\u003c/p\u003e\u003ch4\u003eNguyên tắc khi Trị bệnh (Sử dụng thuốc thú y)\u003c/h4\u003e\u003cp\u003e\u003cstrong\u003e• Đ\u0026#250;ng thuốc: \u003c/strong\u003eD\u0026#249;ng đ\u0026#250;ng loại thuốc cho đ\u0026#250;ng loại bệnh (d\u0026#249;ng kh\u0026#225;ng sinh trị bệnh vi khuẩn, kh\u0026#244;ng d\u0026#249;ng kh\u0026#225;ng sinh trị bệnh do virus).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e• Đ\u0026#250;ng thời điểm: \u003c/strong\u003eD\u0026#249;ng thuốc ngay khi ph\u0026#225;t hiện dấu hiệu bệnh đầu ti\u0026#234;n để đạt hiệu quả cao.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e• Đ\u0026#250;ng liều lượng: \u003c/strong\u003eTu\u0026#226;n thủ đ\u0026#250;ng liều lượng hướng dẫn; kh\u0026#244;ng tự \u0026#253; hạ liều (g\u0026#226;y nhờn thuốc) hoặc tăng liều (g\u0026#226;y độc cho vật nu\u0026#244;i).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e• Thuốc trợ sức: \u003c/strong\u003eBổ sung th\u0026#234;m Vitamin, chất điện giải, men vi sinh để trợ sức, n\u0026#226;ng cao thể trạng gi\u0026#250;p vật nu\u0026#244;i mau phục hồi.\u003c/p\u003e\u003ch2\u003ePHẦN II: PHÂN TÍCH CÁC DẠNG CÂU HỎI HSG VÀ LỖI SAI THƯỜNG GẶP\u003c/h2\u003e\u003ch3\u003e1. Các dạng câu hỏi HSG trọng tâm từ Đề thi nguồn\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003eDạng 1: Ph\u0026#226;n t\u0026#237;ch \u0026amp; So s\u0026#225;nh hiệu quả ph\u0026#242;ng bệnh (Định hướng C\u0026#226;u 2b Đề thi nguồn): \u003c/strong\u003eY\u0026#234;u cầu so s\u0026#225;nh to\u0026#224;n diện về hiệu quả kinh tế, sức khỏe đ\u0026#224;n vật nu\u0026#244;i, chất lượng sản phẩm v\u0026#224; an to\u0026#224;n m\u0026#244;i trường giữa 2 trường hợp thực hiện tốt vs kh\u0026#244;ng tốt c\u0026#244;ng t\u0026#225;c ph\u0026#242;ng bệnh.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eDạng 2: Giải th\u0026#237;ch cơ chế sinh l\u0026#253; \u0026amp; Miễn dịch: \u003c/strong\u003eY\u0026#234;u cầu giải th\u0026#237;ch dựa tr\u0026#234;n đặc điểm sinh l\u0026#253; học (v\u0026#237; dụ: tại sao gia s\u0026#250;c con cần b\u0026#250; sữa đầu ngay trong 24 giờ; tại sao kh\u0026#244;ng được cho đực giống ăn qu\u0026#225; b\u0026#233;o).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eDạng 3: Xử l\u0026#253; t\u0026#236;nh huống dịch bệnh \u0026amp; An to\u0026#224;n sinh học: \u003c/strong\u003eCho một t\u0026#236;nh huống xuất hiện ca bệnh truyền nhiễm nguy hiểm (C\u0026#250;m gia cầm, Dịch tả lợn) \\(\\rightarrow\\) Y\u0026#234;u cầu học sinh đưa ra c\u0026#225;c bước xử l\u0026#253; chuẩn th\u0026#250; y v\u0026#224; an to\u0026#224;n dịch bệnh.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eDạng 4: Lập kế hoạch \u0026amp; T\u0026#237;nh to\u0026#225;n chi ph\u0026#237; chăn nu\u0026#244;i: \u003c/strong\u003eLập danh s\u0026#225;ch c\u0026#225;c khoản chi ph\u0026#237; (con giống, chuồng trại, thức ăn, vắc xin) v\u0026#224; t\u0026#237;nh to\u0026#225;n tổng ng\u0026#226;n s\u0026#225;ch chăn nu\u0026#244;i gia đ\u0026#236;nh trong 1 năm.\u003c/p\u003e\u003ch3\u003e2. Các lỗi sai học sinh hay mắc phải và cách khắc phục\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003eLỗi 1: Lập luận hời hợt, thiếu bước trung gian: \u003c/strong\u003eKhi ph\u0026#226;n t\u0026#237;ch hậu quả của việc ph\u0026#242;ng bệnh kh\u0026#244;ng tốt, học sinh chỉ n\u0026#234;u \u0026#39;vật nu\u0026#244;i bị chết\u0026#39; m\u0026#224; qu\u0026#234;n ph\u0026#226;n t\u0026#237;ch t\u0026#225;c động d\u0026#226;y chuyền: suy giảm hệ miễn dịch \\(\\rightarrow\\) chất lượng sản phẩm k\u0026#233;m \\(\\rightarrow\\) tổn thất kinh tế nặng nề cho người nu\u0026#244;i.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eLỗi 2: Nhầm lẫn giữa Vắc xin v\u0026#224; Thuốc kh\u0026#225;ng sinh: \u003c/strong\u003eNhầm lẫn rằng d\u0026#249;ng thuốc kh\u0026#225;ng sinh c\u0026#243; thể diệt được virus. Kh\u0026#225;ng sinh chỉ diệt hoặc k\u0026#236;m h\u0026#227;m vi khuẩn, đối với bệnh do virus (C\u0026#250;m, Newcastle, Dịch tả) bắt buộc phải ph\u0026#242;ng bằng vắc xin.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eLỗi 3: Đề xuất giải ph\u0026#225;p vi phạm an to\u0026#224;n dịch bệnh: \u003c/strong\u003eKhi gặp dịch bệnh nguy hiểm, một số học sinh đề xuất \u0026#39;b\u0026#225;n chạy\u0026#39; hoặc \u0026#39;vứt x\u0026#225;c xuống s\u0026#244;ng/mương\u0026#39;. Đ\u0026#226;y l\u0026#224; h\u0026#224;nh vi vi phạm ph\u0026#225;p luật nghi\u0026#234;m trọng g\u0026#226;y ph\u0026#225;t t\u0026#225;n dịch bệnh.\u003c/p\u003e\u003ch2\u003ePHẦN III: HỆ THỐNG CÂU HỎI, BÀI TẬP VÀ ĐÁP ÁN CHUẨN HSG\u003c/h2\u003e\u003ch3\u003eA. ĐỀ BÀI (Phân hóa theo 4 mức độ nhận thức)\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 1 (Mức 1 - Nhận biết \u0026amp; Th\u0026#244;ng hiểu - 2,0 điểm): \u003c/strong\u003eTr\u0026#236;nh b\u0026#224;y vai tr\u0026#242; của việc nu\u0026#244;i dưỡng, chăm s\u0026#243;c v\u0026#224; ph\u0026#242;ng, trị bệnh cho vật nu\u0026#244;i. Thế n\u0026#224;o l\u0026#224; \u0026#39;Ph\u0026#250;c lợi động vật\u0026#39; v\u0026#224; n\u0026#234;u 5 ti\u0026#234;u chuẩn đ\u0026#225;nh gi\u0026#225; ph\u0026#250;c lợi động vật trong chăn nu\u0026#244;i hiện đại.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 2 (Mức 2 - Th\u0026#244;ng hiểu \u0026amp; Vận dụng - 2,5 điểm): \u003c/strong\u003ePh\u0026#226;n t\u0026#237;ch đặc điểm sinh l\u0026#253; của vật nu\u0026#244;i non. Từ c\u0026#225;c đặc điểm sinh l\u0026#253; đ\u0026#243;, h\u0026#227;y giải th\u0026#237;ch cơ sở khoa học của c\u0026#225;c biện ph\u0026#225;p kỹ thuật: (1) Sưởi ấm cho vật nu\u0026#244;i non; (2) Cho con non b\u0026#250; sữa đầu c\u0026#224;ng sớm c\u0026#224;ng tốt; (3) Tập cho con non ăn sớm.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 3 (Mức 2 - Vận dụng - 2,5 điểm): \u003c/strong\u003eSo s\u0026#225;nh sự kh\u0026#225;c nhau giữa bệnh truyền nhiễm v\u0026#224; bệnh kh\u0026#244;ng truyền nhiễm ở vật nu\u0026#244;i về: nguy\u0026#234;n nh\u0026#226;n g\u0026#226;y bệnh, khả năng l\u0026#226;y lan, mức độ nguy hiểm v\u0026#224; v\u0026#237; dụ minh họa. Tại sao bệnh do vi sinh vật g\u0026#226;y ra lại nguy hiểm nhất trong chăn nu\u0026#244;i?\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 4 (Mức 3 - Vận dụng cao - 3,0 điểm): \u003c/strong\u003eGiải th\u0026#237;ch tại sao trong chăn nu\u0026#244;i đực giống cần phải tr\u0026#225;nh cho vật nu\u0026#244;i bị qu\u0026#225; b\u0026#233;o hoặc qu\u0026#225; gầy? Ph\u0026#226;n t\u0026#237;ch nhu cầu dinh dưỡng v\u0026#224; chăm s\u0026#243;c của vật nu\u0026#244;i c\u0026#225;i sinh sản qua 3 giai đoạn: hậu bị, mang thai v\u0026#224; nu\u0026#244;i con.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 5 (Mức 3 - Vận dụng cao \u0026amp; Lập luận ph\u0026#226;n h\u0026#243;a - 3,0 điểm): \u003c/strong\u003eTrong c\u0026#244;ng t\u0026#225;c chăn nu\u0026#244;i gia s\u0026#250;c, gia cầm tại địa phương:\u003cbr\u003ea) H\u0026#227;y n\u0026#234;u c\u0026#225;c biện ph\u0026#225;p ph\u0026#242;ng bệnh ch\u0026#237;nh cho vật nu\u0026#244;i hiện nay.\u003cbr\u003eb) Ph\u0026#226;n t\u0026#237;ch v\u0026#224; so s\u0026#225;nh hiệu quả giữa hai trường hợp: Khi người chăn nu\u0026#244;i thực hiện c\u0026#244;ng t\u0026#225;c chăm s\u0026#243;c, ph\u0026#242;ng v\u0026#224; trị bệnh cho vật nu\u0026#244;i TỐT v\u0026#224; KH\u0026#212;NG TỐT.\u003cbr\u003e(Tr\u0026#237;ch định hướng Đề thi HSG ch\u0026#237;nh thức Sở GDĐT Vĩnh Long)\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 6 (Mức 4 - T\u0026#236;nh huống thực tiễn \u0026amp; An to\u0026#224;n dịch bệnh - 3,5 điểm): \u003c/strong\u003eGiả sử trang trại nu\u0026#244;i g\u0026#224; của gia đ\u0026#236;nh em xuất hiện một số con g\u0026#224; c\u0026#243; biểu hiện: ủ rũ, bỏ ăn, diều nh\u0026#227;o, chảy nước d\u0026#227;i, ti\u0026#234;u chảy ph\u0026#226;n xanh/trắng, ho v\u0026#224; ngoẹo cổ. Em nghi ngờ đ\u0026#224;n g\u0026#224; mắc bệnh dịch tả (Newcastle).\u003cbr\u003ea) Em h\u0026#227;y đề xuất quy tr\u0026#236;nh xử l\u0026#253; t\u0026#236;nh huống tr\u0026#234;n một c\u0026#225;ch khoa học v\u0026#224; đ\u0026#250;ng quy định an to\u0026#224;n dịch bệnh.\u003cbr\u003eb) Tại sao kh\u0026#244;ng được tự \u0026#253; b\u0026#225;n tống b\u0026#225;n th\u0026#225;o hoặc vứt x\u0026#225;c g\u0026#224; bệnh ra mương, s\u0026#244;ng, ao hồ?\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 7 (Mức 4 - Lập kế hoạch \u0026amp; T\u0026#237;nh to\u0026#225;n chi ph\u0026#237; - 3,5 điểm): \u003c/strong\u003eMột hộ gia đ\u0026#236;nh dự định đầu tư nu\u0026#244;i 100 con g\u0026#224; thịt thả vườn trong thời gian 3 th\u0026#225;ng (1 lứa). Biết rằng:\u003cbr\u003e- Gi\u0026#225; con giống: 15.000 đồng/con.\u003cbr\u003e- Chi ph\u0026#237; l\u0026#224;m chuồng v\u0026#224; dụng cụ (m\u0026#225;ng ăn, m\u0026#225;ng uống, qu\u0026#226;y \u0026#250;m): 1.500.000 đồng (ph\u0026#226;n bổ cho lứa đầu).\u003cbr\u003e- Lượng thức ăn b\u0026#236;nh qu\u0026#226;n cho 1 con g\u0026#224; trong 3 th\u0026#225;ng l\u0026#224; 6 kg thức ăn hỗn hợp, gi\u0026#225; thức ăn l\u0026#224; 14.000 đồng/kg.\u003cbr\u003e- Chi ph\u0026#237; vắc xin v\u0026#224; thuốc th\u0026#250; y: 5.000 đồng/con.\u003cbr\u003e- Chi ph\u0026#237; điện, nước, trấu l\u0026#243;t nền: 300.000 đồng/lứa.\u003cbr\u003eH\u0026#227;y lập bảng kế hoạch dự to\u0026#225;n chi ph\u0026#237; chi tiết v\u0026#224; t\u0026#237;nh tổng chi ph\u0026#237; để nu\u0026#244;i lứa g\u0026#224; tr\u0026#234;n. Từ đ\u0026#243; t\u0026#237;nh gi\u0026#225; th\u0026#224;nh sản xuất trung b\u0026#236;nh cho 1 kg g\u0026#224; thịt (biết tỷ lệ sống đạt 95% v\u0026#224; khối lượng xuất b\u0026#225;n trung b\u0026#236;nh đạt 2,2 kg/con).\u003c/p\u003e\u003ch3\u003eB. ĐÁP ÁN VÀ HƯỚNG DẪN CHẤM CHI TIẾT\u003c/h3\u003e\u003cp\u003eĐ\u0026#225;p \u0026#225;n được x\u0026#226;y dựng chi tiết theo từng \u0026#253; nhỏ, chuẩn biểu điểm 0,25 điểm của Sở Gi\u0026#225;o dục v\u0026#224; Đ\u0026#224;o tạo Vĩnh Long:\u003c/p\u003e\u003ch4\u003eĐáp án Câu 1 (2,0 điểm)\u003c/h4\u003e\u003cp\u003e\u003cstrong\u003e• Vai tr\u0026#242; nu\u0026#244;i dưỡng \u0026amp; chăm s\u0026#243;c: \u003c/strong\u003eCung cấp đầy đủ chất dinh dưỡng, tạo m\u0026#244;i trường sống thuận lợi gi\u0026#250;p vật nu\u0026#244;i khỏe mạnh, lớn nhanh, tăng sức đề kh\u0026#225;ng, mang lại năng suất v\u0026#224; chất lượng sản phẩm chăn nu\u0026#244;i cao. (0,5đ)\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e• Vai tr\u0026#242; ph\u0026#242;ng, trị bệnh: \u003c/strong\u003eTăng cường sức đề kh\u0026#225;ng, ti\u0026#234;u diệt mầm bệnh, ngăn ngừa sự l\u0026#226;y lan của dịch bệnh, giảm nguy cơ tử vong v\u0026#224; thiệt hại kinh tế. (0,5đ)\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e• Kh\u0026#225;i niệm Ph\u0026#250;c lợi động vật: \u003c/strong\u003eL\u0026#224; việc đối xử nh\u0026#226;n đạo với vật nu\u0026#244;i, tạo điều kiện cho vật nu\u0026#244;i c\u0026#243; trạng th\u0026#225;i thể chất v\u0026#224; tinh thần tốt nhất. (0,25đ)\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e• 5 Ti\u0026#234;u chuẩn ph\u0026#250;c lợi động vật: \u003c/strong\u003eN\u0026#234;u đ\u0026#250;ng 5 ti\u0026#234;u chuẩn (0,1đ/ti\u0026#234;u chuẩn = 0,5đ): Kh\u0026#244;ng bị đ\u0026#243;i kh\u0026#225;t; Kh\u0026#244;ng bị kh\u0026#243; chịu về thể x\u0026#225;c; Kh\u0026#244;ng bị đau đớn/bệnh tật; Kh\u0026#244;ng bị sợ h\u0026#227;i/lo \u0026#226;u; Tự do thể hiện h\u0026#224;nh vi tự nhi\u0026#234;n. \u0026#221; thức bảo vệ m\u0026#244;i trường chăn nu\u0026#244;i. (0,25đ)\u003c/p\u003e\u003ch4\u003eĐáp án Câu 2 (2,5 điểm)\u003c/h4\u003e\u003cp\u003e\u003cstrong\u003e• 4 Đặc điểm sinh l\u0026#253; vật nu\u0026#244;i non: \u003c/strong\u003eKhả năng điều tiết th\u0026#226;n nhiệt chưa ho\u0026#224;n chỉnh (dễ bị lạnh); Chức năng hệ ti\u0026#234;u h\u0026#243;a chưa ho\u0026#224;n thiện; Hệ miễn dịch chưa tốt, lượng kh\u0026#225;ng thể trong m\u0026#225;u thấp; Tốc độ ph\u0026#225;t triển thể chất nhanh. (0,75đ)\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e• Giải th\u0026#237;ch sưởi ấm: \u003c/strong\u003eDo lớp mỡ dưới da mỏng v\u0026#224; trung khu điều h\u0026#242;a th\u0026#226;n nhiệt chưa ho\u0026#224;n thiện, sưởi ấm gi\u0026#250;p giữ ấm cơ thể, tr\u0026#225;nh mất nhiệt g\u0026#226;y hạ th\u0026#226;n nhiệt v\u0026#224; mắc bệnh h\u0026#244; hấp/ti\u0026#234;u h\u0026#243;a. (0,5đ)\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e• Giải th\u0026#237;ch b\u0026#250; sữa đầu: \u003c/strong\u003eSữa đầu rất gi\u0026#224;u chất dinh dưỡng v\u0026#224; chứa h\u0026#224;m lượng kh\u0026#225;ng thể cao (IgA, IgG). Cho con non b\u0026#250; sữa đầu sớm gi\u0026#250;p hấp thu kh\u0026#225;ng thể trực tiếp qua ruột, tạo hệ miễn dịch thụ động bảo vệ cơ thể khi chưa tự tổng hợp được kh\u0026#225;ng thể. (0,75đ)\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e• Giải th\u0026#237;ch tập ăn sớm: \u003c/strong\u003eTập ăn sớm gi\u0026#250;p bổ sung c\u0026#225;c chất dinh dưỡng m\u0026#224; sữa mẹ bắt đầu thiếu hụt, đồng thời r\u0026#232;n luyện v\u0026#224; k\u0026#237;ch th\u0026#237;ch sự ph\u0026#225;t triển ho\u0026#224;n thiện của hệ ti\u0026#234;u h\u0026#243;a. (0,5đ)\u003c/p\u003e\u003ch4\u003eĐáp án Câu 3 (2,5 điểm)\u003c/h4\u003e\u003cp\u003e\u003cstrong\u003e• So s\u0026#225;nh 2 nh\u0026#243;m bệnh: \u003c/strong\u003eN\u0026#234;u đ\u0026#250;ng so s\u0026#225;nh 4 ti\u0026#234;u ch\u0026#237; (1,5đ): Bệnh truyền nhiễm do vi sinh vật (vi khuẩn, virus), l\u0026#226;y lan nhanh/rộng, g\u0026#226;y chết h\u0026#224;ng loạt, tổn thất kinh tế rất lớn (VD: C\u0026#250;m g\u0026#224;, Dịch tả lợn); Bệnh kh\u0026#244;ng truyền nhiễm do k\u0026#253; sinh tr\u0026#249;ng/dinh dưỡng/m\u0026#244;i trường, kh\u0026#244;ng l\u0026#226;y lan, chỉ hại c\u0026#225; thể (VD: C\u0026#242;i xương, giun s\u0026#225;n).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e• Giải th\u0026#237;ch tại sao bệnh vi sinh vật nguy hiểm nhất: \u003c/strong\u003eMầm bệnh vi sinh vật c\u0026#243; k\u0026#237;ch thước si\u0026#234;u nhỏ, tốc độ sinh sản nh\u0026#226;n l\u0026#234;n cực nhanh; C\u0026#243; khả năng biến đổi chủng vi r\u0026#250;t; L\u0026#226;y lan qua nhiều con đường (kh\u0026#244;ng kh\u0026#237;, nước, thức ăn, dụng cụ, con người); G\u0026#226;y tử vong tỷ lệ cao v\u0026#224; b\u0026#249;ng ph\u0026#225;t th\u0026#224;nh dịch lớn kh\u0026#243; kiểm so\u0026#225;t. (1,0đ)\u003c/p\u003e\u003ch4\u003eĐáp án Câu 4 (3,0 điểm)\u003c/h4\u003e\u003cp\u003e\u003cstrong\u003e• T\u0026#225;c hại đực giống b\u0026#233;o/gầy: \u003c/strong\u003eNếu đực giống qu\u0026#225; b\u0026#233;o: T\u0026#237;ch tụ mỡ ở tinh ho\u0026#224;n, giảm hưng phấn phối giống, chất lượng tinh tr\u0026#249;ng suy giảm. Nếu đực giống qu\u0026#225; gầy: Thiếu năng lượng v\u0026#224; chất dinh dưỡng l\u0026#224;m giảm phản xạ sinh dục, lượng tinh dịch \u0026#237;t, tỷ lệ tinh tr\u0026#249;ng dị h\u0026#236;nh cao. Do đ\u0026#243; cần duy tr\u0026#236; thể trạng khỏe mạnh, c\u0026#226;n đối. (1,0đ)\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e• C\u0026#225;i sinh sản - Hậu bị: \u003c/strong\u003eGiai đoạn hậu bị: Cho ăn vừa phải để cơ thể ph\u0026#225;t triển c\u0026#226;n đối, kh\u0026#244;ng b\u0026#233;o mỡ. (0,5đ)\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e• C\u0026#225;i sinh sản - Mang thai: \u003c/strong\u003eGiai đoạn mang thai: Cho ăn đủ dinh dưỡng nu\u0026#244;i thai nhi ph\u0026#225;t triển, nhưng giai đoạn đầu kh\u0026#244;ng cho ăn qu\u0026#225; thừa tr\u0026#225;nh thai qu\u0026#225; to g\u0026#226;y kh\u0026#243; đẻ. (0,75đ)\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e• C\u0026#225;i sinh sản - Nu\u0026#244;i con/Đẻ trứng: \u003c/strong\u003eGiai đoạn đẻ/nu\u0026#244;i con: Cho ăn theo nhu cầu cao nhất, gi\u0026#224;u đạm v\u0026#224; canxi để tiết nhiều sữa nu\u0026#244;i con hoặc đẻ nhiều trứng. (0,75đ)\u003c/p\u003e\u003ch4\u003eĐáp án Câu 5 (3,0 điểm - Chuẩn biểu điểm Sở GDĐT Vĩnh Long)\u003c/h4\u003e\u003cp\u003e\u003cstrong\u003ea) C\u0026#225;c biện ph\u0026#225;p ph\u0026#242;ng bệnh ch\u0026#237;nh (0,75đ): \u003c/strong\u003eN\u0026#234;u đủ 3 biện ph\u0026#225;p (0,75đ):\u003cbr\u003e- Vệ sinh m\u0026#244;i trường sống của vật nu\u0026#244;i (vệ sinh chuồng trại sạch sẽ, tho\u0026#225;ng m\u0026#225;t). (0,25đ)\u003cbr\u003e- Cung cấp thức ăn, nước uống đầy đủ, hợp vệ sinh. (0,25đ)\u003cbr\u003e- Ti\u0026#234;m vaccine ph\u0026#242;ng bệnh đầy đủ v\u0026#224; đ\u0026#250;ng lịch. (0,25đ)\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eb) Ph\u0026#226;n t\u0026#237;ch \u0026amp; So s\u0026#225;nh hiệu quả (2,25đ): \u003c/strong\u003eTh\u0026#237; sinh tr\u0026#236;nh b\u0026#224;y theo 1 trong 2 phương \u0026#225;n sau (2,25đ):\u003cbr\u003e\u003cbr\u003e► PHƯƠNG \u0026#193;N 1: Khi chăm s\u0026#243;c, ph\u0026#242;ng v\u0026#224; trị bệnh cho vật nu\u0026#244;i KH\u0026#212;NG TỐT:\u003cbr\u003e- Vật nu\u0026#244;i c\u0026#243; hệ miễn dịch kh\u0026#244;ng tốt, sức đề kh\u0026#225;ng k\u0026#233;m, sức khỏe yếu, dễ nhiễm bệnh. (0,75đ)\u003cbr\u003e- Chất lượng v\u0026#224; năng suất sản phẩm chăn nu\u0026#244;i k\u0026#233;m (thịt gầy, trứng mỏng, sữa \u0026#237;t). (0,75đ)\u003cbr\u003e- G\u0026#226;y tổn thất kinh tế lớn cho người nu\u0026#244;i (tốn tiền chữa bệnh, vật nu\u0026#244;i chết, lỗ vốn). (0,75đ)\u003cbr\u003e\u003cbr\u003e► PHƯƠNG \u0026#193;N 2: Khi chăm s\u0026#243;c, ph\u0026#242;ng v\u0026#224; trị bệnh cho vật nu\u0026#244;i TỐT sẽ gi\u0026#250;p:\u003cbr\u003e- Vật nu\u0026#244;i c\u0026#243; hệ miễn dịch tốt, sức đề kh\u0026#225;ng cao, sức khỏe tốt, ph\u0026#225;t triển nhanh. (0,75đ)\u003cbr\u003e- Chất lượng v\u0026#224; năng suất sản phẩm chăn nu\u0026#244;i cao, đảm bảo an to\u0026#224;n thực phẩm. (0,75đ)\u003cbr\u003e- Mang lại lợi nhuận kinh tế cao v\u0026#224; bền vững cho người chăn nu\u0026#244;i. (0,75đ)\u003c/p\u003e\u003ch4\u003eĐáp án Câu 6 (3,5 điểm)\u003c/h4\u003e\u003cp\u003e\u003cstrong\u003ea) Quy tr\u0026#236;nh xử l\u0026#253; sự cố dịch bệnh: \u003c/strong\u003eN\u0026#234;u đ\u0026#250;ng quy tr\u0026#236;nh 5 bước (2,0đ):\u003cbr\u003e1. B\u0026#225;o ngay cho c\u0026#225;n bộ th\u0026#250; y x\u0026#227;/phường hoặc ch\u0026#237;nh quyền địa phương kiểm tra. (0,4đ)\u003cbr\u003e2. Nhốt c\u0026#225;ch ly ngay lập tức những con g\u0026#224; c\u0026#243; biểu hiện bệnh ra khu vực ri\u0026#234;ng. (0,4đ)\u003cbr\u003e3. Ngừng vận chuyển, kh\u0026#244;ng mua b\u0026#225;n, kh\u0026#244;ng thả r\u0026#244;ng đ\u0026#224;n g\u0026#224;. (0,4đ)\u003cbr\u003e4. Tiến h\u0026#224;nh phun thuốc s\u0026#225;t tr\u0026#249;ng, rắc v\u0026#244;i bột ti\u0026#234;u độc khử tr\u0026#249;ng to\u0026#224;n bộ chuồng trại. (0,4đ)\u003cbr\u003e5. Nếu ti\u0026#234;u hủy phải thực hiện ch\u0026#244;n/đốt x\u0026#225;c g\u0026#224; chết đ\u0026#250;ng kỹ thuật th\u0026#250; y dưới sự hướng dẫn của c\u0026#225;n bộ chuy\u0026#234;n m\u0026#244;n. (0,4đ)\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eb) L\u0026#253; do kh\u0026#244;ng b\u0026#225;n chạy hay vứt x\u0026#225;c: \u003c/strong\u003eGiải th\u0026#237;ch thuyết phục (1,5đ):\u003cbr\u003e- B\u0026#225;n chạy g\u0026#224; bệnh l\u0026#224;m ph\u0026#225;t t\u0026#225;n mầm bệnh virus ra thị trường, l\u0026#226;y lan dịch bệnh cho c\u0026#225;c đ\u0026#224;n gia cầm kh\u0026#225;c trong v\u0026#249;ng.\u003cbr\u003e- G\u0026#224; mắc bệnh truyền nhiễm kh\u0026#244;ng đảm bảo an to\u0026#224;n vệ sinh thực phẩm, c\u0026#243; thể g\u0026#226;y ngộ độc hoặc l\u0026#226;y truyền bệnh sang người.\u003cbr\u003e- Vứt x\u0026#225;c g\u0026#224; xuống s\u0026#244;ng/mương l\u0026#224;m \u0026#244; nhiễm nghi\u0026#234;m trọng nguồn nước, mầm bệnh ph\u0026#225;t t\u0026#225;n rộng theo d\u0026#242;ng nước đến c\u0026#225;c v\u0026#249;ng hạ lưu, \u0026#244; nhiễm m\u0026#244;i trường sống.\u003c/p\u003e\u003ch4\u003eĐáp án Câu 7 (3,5 điểm - Bài tập chi phí)\u003c/h4\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eSTT\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eKhoản mục chi ph\u0026#237;\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eĐơn vị t\u0026#237;nh\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eSố lượng / Đơn gi\u0026#225;\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eTh\u0026#224;nh tiền (Đồng)\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e1\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eG\u0026#224; giống\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eCon\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e100 con \u0026#215; 15.000 đ\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e1.500.000\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e2\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eChuồng nu\u0026#244;i \u0026amp; dụng cụ\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eLứa\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e1 lứa\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e1.500.000\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e3\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eThức ăn hỗn hợp\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eKg\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e100 con \u0026#215; 6 kg = 600 kg \u0026#215; 14.000 đ\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e8.400.000\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e4\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eVắc xin \u0026amp; Thuốc th\u0026#250; y\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eCon\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e100 con \u0026#215; 5.000 đ\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e500.000\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e5\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eĐiện, nước, độn chuồng\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eLứa\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e1 lứa\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e300.000\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eTỔNG CHI PH\u0026#205; DỰ TO\u0026#193;N\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003c/td\u003e\u003ctd\u003e\u003c/td\u003e\u003ctd\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003e12.200.000\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003cp\u003e\u003cstrong\u003e• Bảng dự to\u0026#225;n chi ph\u0026#237;: \u003c/strong\u003eLập bảng chi tiết đ\u0026#250;ng từng khoản mục v\u0026#224; t\u0026#237;nh ra Tổng chi ph\u0026#237; = 12.200.000 đồng. (2,0đ)\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e• Sản lượng g\u0026#224; xuất b\u0026#225;n: \u003c/strong\u003eSố g\u0026#224; sống xuất b\u0026#225;n = 100 con \u0026#215; 95% = 95 con. Tổng khối lượng g\u0026#224; xuất b\u0026#225;n = 95 con \u0026#215; 2,2 kg/con = 209 kg. (0,75đ)\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e• T\u0026#237;nh gi\u0026#225; th\u0026#224;nh sản xuất 1 kg g\u0026#224;: \u003c/strong\u003eGi\u0026#225; th\u0026#224;nh 1 kg g\u0026#224; thịt = 12.200.000 / 209 kg ≈ 58.373 đồng/kg. (0,75đ)\u003c/p\u003e\u003ch2\u003ePHẦN IV: GHI NHỚ NHANH VÀ SƠ ĐỒ TƯ DUY TỔNG HỢP\u003c/h2\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003e🧠 C\u0026#212;NG THỨC V\u0026#192; TỪ KH\u0026#211;A GHI NHỚ NHANH (FLASH-MEMORIZE)\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e1. Vật nu\u0026#244;i non: Giữ ấm + B\u0026#250; sữa đầu sớm (\u0026lt;24h) + Tập ăn sớm (7-10 ng\u0026#224;y) + Tắm nắng s\u0026#225;ng.\u003c/p\u003e\u003cp\u003e2. Đực giống: Thể trạng c\u0026#226;n đối (Kh\u0026#244;ng qu\u0026#225; b\u0026#233;o, Kh\u0026#244;ng qu\u0026#225; gầy) + Dinh dưỡng gi\u0026#224;u đạm/kho\u0026#225;ng + Vận động hằng ng\u0026#224;y.\u003c/p\u003e\u003cp\u003e3. C\u0026#225;i sinh sản: Hậu bị (vừa phải) -\u0026gt; Mang thai (đủ dinh dưỡng) -\u0026gt; Nu\u0026#244;i con (ăn tự do, gi\u0026#224;u đạm/Ca).\u003c/p\u003e\u003cp\u003e4. Nguy\u0026#234;n tắc ph\u0026#242;ng bệnh: PH\u0026#210;NG BỆNH HƠN CHỮA BỆNH; Ti\u0026#234;m Vắc xin = Tạo miễn dịch chủ động; Ăn sạch, ở sạch, uống sạch.\u003c/p\u003e\u003cp\u003e5. Bệnh truyền nhiễm: Do Vi sinh vật (Vi khuẩn/Virus) -\u0026gt; L\u0026#226;y lan nhanh -\u0026gt; Nguy hiểm h\u0026#224;ng đầu -\u0026gt; Bắt buộc c\u0026#225;ch ly \u0026amp; b\u0026#225;o th\u0026#250; y.\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e","3":"\u003ch2\u003eCHUYÊN ĐỀ 3: KỸ THUẬT NUÔI TRỒNG VÀ QUẢN LÝ MÔI TRƯỜNG THỦY SẢN\u003c/h2\u003e\u003cp\u003e\u003cem\u003eB\u0026#225;m s\u0026#225;t C\u0026#244;ng văn 730/SGDĐT-GDPT tỉnh Vĩnh Long \u0026amp; Bộ SGK/SGV/SBT C\u0026#244;ng nghệ 7 (KNTT)\u003c/em\u003e\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003e📌\u003c/strong\u003e\u003cstrong\u003e ĐỊNH HƯỚNG TRỌNG T\u0026#194;M CẤU TR\u0026#218;C ĐỀ THI HSG\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e\u003cem\u003eChuy\u0026#234;n đề 3 bao gồm to\u0026#224;n bộ nội dung l\u0026#253; thuyết chuy\u0026#234;n s\u0026#226;u về vai tr\u0026#242; thủy sản, quy tr\u0026#236;nh nu\u0026#244;i c\u0026#225; ao, quản l\u0026#253; m\u0026#244;i trường nước, đo chỉ số chất lượng nước, ph\u0026#242;ng trị bệnh v\u0026#224; khai th\u0026#225;c bảo vệ nguồn lợi thủy sản. Hệ thống b\u0026#224;i tập được bi\u0026#234;n soạn chi tiết theo 4 mức độ nhận thức, đặc biệt cập nhật đ\u0026#225;p \u0026#225;n chuẩn c\u0026#226;u hỏi tự luận ph\u0026#226;n h\u0026#243;a (3.0 điểm) về t\u0026#225;c hại sinh th\u0026#225;i - kinh tế khi l\u0026#227;ng ph\u0026#237; thức ăn thủy sản từ Đề thi HSG ch\u0026#237;nh thức tỉnh Vĩnh Long.\u003c/em\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003ch3\u003eI. MỤC TIÊU \u0026 CHUẨN NĂNG LỰC CẦN ĐẠT CỦA CHUYÊN ĐỀ\u003c/h3\u003e\u003cp\u003eTheo Phụ lục C\u0026#244;ng văn 730/SGDĐT-GDPT v\u0026#224; Chương tr\u0026#236;nh GDPT 2018 m\u0026#244;n C\u0026#244;ng nghệ 7, chuy\u0026#234;n đề Nu\u0026#244;i thủy sản y\u0026#234;u cầu học sinh đạt được c\u0026#225;c mục ti\u0026#234;u kiến thức v\u0026#224; năng lực chuy\u0026#234;n s\u0026#226;u như sau:\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eKiến thức nền tảng chắc chắn: \u003c/strong\u003eTr\u0026#236;nh b\u0026#224;y được vai tr\u0026#242;, triển vọng của ng\u0026#224;nh thủy sản; kể t\u0026#234;n c\u0026#225;c lo\u0026#224;i thủy sản c\u0026#243; gi\u0026#225; trị kinh tế cao ở Việt Nam; nắm vững từng bước trong quy tr\u0026#236;nh nu\u0026#244;i c\u0026#225; ao (chuẩn bị ao, thả giống, chăm s\u0026#243;c, quản l\u0026#253; m\u0026#244;i trường nước, thu hoạch).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eTư duy bản chất kỹ thuật - sinh học: \u003c/strong\u003eGiải th\u0026#237;ch được cơ sở khoa học của c\u0026#225;c c\u0026#244;ng việc chuẩn bị ao nu\u0026#244;i (tẩy v\u0026#244;i, phơi đ\u0026#225;y, lọc nước); cơ chế ngấm nhiệt khi thả c\u0026#225;; bản chất sinh h\u0026#243;a của hiện tượng l\u0026#227;ng ph\u0026#237; thức ăn l\u0026#224;m biến đổi m\u0026#224;u nước, b\u0026#249;ng ph\u0026#225;t tảo độc v\u0026#224; suy giảm \u0026#244;xy h\u0026#242;a tan.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eKỹ năng thực h\u0026#224;nh \u0026amp; Định lượng: \u003c/strong\u003eNắm vững quy tr\u0026#236;nh v\u0026#224; \u0026#253; nghĩa kỹ thuật của việc đo nhiệt độ v\u0026#224; độ trong nước ao nu\u0026#244;i bằng đĩa Secchi; lập kế hoạch v\u0026#224; t\u0026#237;nh to\u0026#225;n chi ph\u0026#237; nu\u0026#244;i thủy sản (nu\u0026#244;i c\u0026#225; ao thương phẩm hoặc nu\u0026#244;i c\u0026#225; cảnh) cho hộ gia đ\u0026#236;nh.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eNăng lực ph\u0026#226;n t\u0026#237;ch \u0026amp; Giải quyết t\u0026#236;nh huống HSG: \u003c/strong\u003ePh\u0026#226;n t\u0026#237;ch, so s\u0026#225;nh hiệu quả giữa 2 phương ph\u0026#225;p thu hoạch (thu tỉa vs thu to\u0026#224;n bộ); đề xuất giải ph\u0026#225;p xử l\u0026#253; khi c\u0026#225; ngạt/nổi đầu; ph\u0026#226;n t\u0026#237;ch c\u0026#225;c biện ph\u0026#225;p bảo vệ m\u0026#244;i trường v\u0026#224; nguồn lợi thủy sản bền vững.\u003c/p\u003e\u003ch3\u003eII. HỆ THỐNG LÝ THUYẾT CHUYÊN SÂU \u0026 BẢN CHẤT KHOA HỌC\u003c/h3\u003e\u003ch3\u003e1. Vai trò và triển vọng của ngành thủy sản trong nền kinh tế\u003c/h3\u003e\u003cp\u003eThủy sản đ\u0026#243;ng vai tr\u0026#242; v\u0026#244; c\u0026#249;ng quan trọng đối với đời sống con người, sự ph\u0026#225;t triển kinh tế quốc gia v\u0026#224; bảo vệ chủ quyền biển đảo:\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eCung cấp thực phẩm chất lượng cao: \u003c/strong\u003eCung cấp nguồn đạm (protein) động vật c\u0026#243; gi\u0026#225; trị dinh dưỡng cao, dễ ti\u0026#234;u h\u0026#243;a, gi\u0026#224;u axit b\u0026#233;o omega-3, vitamin v\u0026#224; kho\u0026#225;ng chất cho bữa ăn h\u0026#224;ng ng\u0026#224;y.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eCung cấp nguy\u0026#234;n liệu xuất khẩu \u0026amp; c\u0026#244;ng nghiệp: \u003c/strong\u003eCung cấp nguy\u0026#234;n liệu cho ng\u0026#224;nh chế biến thực phẩm xuất khẩu đạt kim ngạch nhiều tỷ USD (c\u0026#225; tra, t\u0026#244;m s\u0026#250;, t\u0026#244;m thẻ ch\u0026#226;n trắng, t\u0026#244;m h\u0026#249;m) v\u0026#224; nguy\u0026#234;n liệu sản xuất thức ăn chăn nu\u0026#244;i (bột c\u0026#225;).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eTạo việc l\u0026#224;m \u0026amp; n\u0026#226;ng cao thu nhập: \u003c/strong\u003eGiải quyết việc l\u0026#224;m cho h\u0026#224;ng triệu lao động trực tiếp (ngư d\u0026#226;n đ\u0026#225;nh bắt, hộ nu\u0026#244;i trồng) v\u0026#224; lao động gi\u0026#225;n tiếp (chế biến, dịch vụ hậu cần nghề c\u0026#225;, thương mại).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eKhẳng định chủ quyền quốc gia: \u003c/strong\u003eC\u0026#225;c hoạt động khai th\u0026#225;c v\u0026#224; nu\u0026#244;i trồng thủy sản tr\u0026#234;n biển g\u0026#243;p phần duy tr\u0026#236; sự c\u0026#243; mặt thường xuy\u0026#234;n của ngư d\u0026#226;n, khẳng định v\u0026#224; bảo vệ chủ quyền, quyền chủ quyền biển đảo của Tổ quốc.\u003c/p\u003e\u003ch3\u003e2. Quy trình kỹ thuật nuôi cá ao và bản chất khoa học từng khâu\u003c/h3\u003e\u003cp\u003eQuy tr\u0026#236;nh nu\u0026#244;i c\u0026#225; ao chuẩn kỹ thuật bao gồm 4 bước nối tiếp bắt buộc:\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eBước 1: Chuẩn bị ao nu\u0026#244;i c\u0026#225;\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003eTrước mỗi lứa nu\u0026#244;i, phải thực hiện vệ sinh v\u0026#224; cải tạo ao đ\u0026#250;ng tr\u0026#236;nh tự: \u003cem\u003eTh\u0026#225;o/bơm cạn nước → Bắt sạch c\u0026#225; tạp, c\u0026#225; dữ → H\u0026#250;t bớt b\u0026#249;n đ\u0026#225;y (chỉ để lại 10 – 15 cm b\u0026#249;n xốp) → Rắc v\u0026#244;i bột (7 – 10 kg/100m\u0026#178;) → Phơi đ\u0026#225;y ao 3 – 5 ng\u0026#224;y → Lấy nước sạch qua t\u0026#250;i lọc vải d\u0026#224;y.\u003c/em\u003e\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003e📌\u003c/strong\u003e\u003cstrong\u003e GIAI M\u0026#195; BẢN CHẤT KHOA HỌC CỦA C\u0026#212;NG T\u0026#193;C CHUẨN BỊ AO NU\u0026#212;I\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e\u003cem\u003e1. H\u0026#250;t bớt b\u0026#249;n đ\u0026#225;y: B\u0026#249;n đ\u0026#225;y qu\u0026#225; d\u0026#224;y chứa lượng lớn chất hữu cơ thối rữa, l\u0026#224; nơi t\u0026#237;ch tụ kh\u0026#237; độc (H2S, NH3, CH4) v\u0026#224; mầm bệnh hại c\u0026#225;.\u003c/em\u003e\u003cem\u003e\u003cbr\u003e2. Rắc v\u0026#244;i bột (CaOH2/CaCO3): C\u0026#243; t\u0026#225;c dụng hạ chua (n\u0026#226;ng pH nước/đất về mức th\u0026#237;ch hợp 6.5 - 8.5), diệt vi khuẩn, nấm, vi sinh vật g\u0026#226;y bệnh v\u0026#224; c\u0026#225;c lo\u0026#224;i c\u0026#225; tạp, địch hại c\u0026#242;n s\u0026#243;t lại.\u003c/em\u003e\u003cem\u003e\u003cbr\u003e3. Phơi đ\u0026#225;y ao (3 - 5 ng\u0026#224;y): Nhờ \u0026#225;nh nắng mặt trời (tia cực t\u0026#237;m) gi\u0026#250;p diệt khuẩn, l\u0026#224;m oxy h\u0026#243;a c\u0026#225;c chất độc tồn đọng trong đ\u0026#225;y đất v\u0026#224; gi\u0026#250;p đ\u0026#225;y ao tho\u0026#225;ng kh\u0026#237;.\u003c/em\u003e\u003cem\u003e\u003cbr\u003e4. Lấy nước qua t\u0026#250;i lọc: Ngăn chặn trứng, ấu tr\u0026#249;ng, c\u0026#225; tạp, r\u0026#225;c thải hoặc sinh vật trung gian truyền bệnh theo nguồn nước v\u0026#224;o ao.\u003c/em\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003cp\u003e\u003cstrong\u003eBước 2: Chuẩn bị c\u0026#225; giống v\u0026#224; thả c\u0026#225;\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e• Ti\u0026#234;u chuẩn c\u0026#225; giống: C\u0026#225; đồng đều k\u0026#237;ch cỡ, khỏe mạnh, kh\u0026#244;ng mang mầm bệnh, bơi lội nhanh nhẹn theo đ\u0026#224;n, v\u0026#226;y vẩy ho\u0026#224;n chỉnh, m\u0026#224;u sắc tươi s\u0026#225;ng.\u003cbr\u003e• Kỹ thuật thả c\u0026#225; giống: Thả v\u0026#224;o thời điểm trời m\u0026#225;t (s\u0026#225;ng sớm hoặc chiều m\u0026#225;t). Trước khi thả, phải ng\u0026#226;m cả t\u0026#250;i nylon chứa c\u0026#225; giống v\u0026#224;o ao nu\u0026#244;i từ 15 – 20 ph\u0026#250;t. Sau đ\u0026#243; mở miệng t\u0026#250;i, cho nước ao tr\u0026#224;n v\u0026#224;o t\u0026#250;i từ từ rồi mới để c\u0026#225; tự bơi ra ao.\u003cbr\u003e→ Bản chất khoa học: Ng\u0026#226;m t\u0026#250;i c\u0026#225; nhằm c\u0026#226;n bằng nhiệt độ giữa nước trong t\u0026#250;i v\u0026#224; nước ao nu\u0026#244;i, gi\u0026#250;p c\u0026#225; quen dần với m\u0026#244;i trường mới, tr\u0026#225;nh hiện tượng sốc nhiệt (c\u0026#225; bị co giật, yếu hoặc chết sau khi thả).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eBước 3: Chăm s\u0026#243;c v\u0026#224; quản l\u0026#253; m\u0026#244;i trường nước ao nu\u0026#244;i\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e• Thức ăn \u0026amp; Chế độ cho ăn: Sử dụng thức ăn vi\u0026#234;n nổi c\u0026#243; h\u0026#224;m lượng protein th\u0026#237;ch hợp (28% – 35% đối với c\u0026#225; nhỏ; 28% – 30% đối với c\u0026#225; lớn). \u0026#193;p dụng nguy\u0026#234;n tắc \u0026#39;4 định\u0026#39;: Định lượng, Định chất, Định vị tr\u0026#237;, Định thời gian.\u003cbr\u003e• Điều chỉnh lượng thức ăn: Khẩu phần ăn h\u0026#224;ng ng\u0026#224;y chiếm 3% – 5% khối lượng c\u0026#225; trong ao. \u003cstrong\u003eV\u0026#224;o những ng\u0026#224;y thời tiết xấu (trời \u0026#226;m u, nắng n\u0026#243;ng k\u0026#233;o d\u0026#224;i, mưa r\u0026#224;o, r\u0026#233;t đậm) hoặc khi nước ao bị bẩn, phải giảm lượng thức ăn hoặc ngừng cho ăn.\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003ePH\u0026#194;N T\u0026#205;CH CHUY\u0026#202;N S\u0026#194;U: T\u0026#193;C HẠI KHI DƯ THỪA THỨC ĂN TRONG NU\u0026#212;I THỦY SẢN\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e(Nội dung trọng t\u0026#226;m Đề thi HSG Vĩnh Long — 3.0 điểm)\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003eKhi cho c\u0026#225;/thủy sản ăn qu\u0026#225; nhiều so với nhu cầu, lượng thức ăn dư thừa sẽ g\u0026#226;y ra chuỗi t\u0026#225;c hại nghi\u0026#234;m trọng về cả sinh th\u0026#225;i v\u0026#224; kinh tế:\u003cbr\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eG\u0026#226;y l\u0026#227;ng ph\u0026#237; thức ăn \u0026amp; Tăng chi ph\u0026#237; sản xuất: \u003c/strong\u003eThức ăn chiếm 60% – 70% tổng chi ph\u0026#237; nu\u0026#244;i thủy sản. Cho ăn dư thừa l\u0026#224;m l\u0026#227;ng ph\u0026#237; vốn đầu tư, tăng gi\u0026#225; th\u0026#224;nh sản phẩm, giảm hoặc mất lợi nhuận.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eL\u0026#224;m dơ ao, bẩn nước \u0026amp; B\u0026#249;ng ph\u0026#225;t tảo mạnh: \u003c/strong\u003eThức ăn thừa dư đạm v\u0026#224; l\u0026#226;n ph\u0026#226;n hủy trong nước l\u0026#224;m nước ao bị ph\u0026#250; dưỡng (chứa qu\u0026#225; nhiều dinh dưỡng). Đ\u0026#226;y l\u0026#224; điều kiện cho c\u0026#225;c loại tảo độc (tảo lam, tảo gi\u0026#225;p) b\u0026#249;ng ph\u0026#225;t mạnh mẽ.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eL\u0026#224;m suy giảm \u0026#244;xy h\u0026#242;a tan \u0026amp; \u0026#212; nhiễm nguồn nước: \u003c/strong\u003eQu\u0026#225; tr\u0026#236;nh ph\u0026#226;n hủy chất hữu cơ của vi sinh vật ti\u0026#234;u tốn lượng lớn \u0026#244;xy h\u0026#242;a tan trong nước v\u0026#224; giải ph\u0026#243;ng c\u0026#225;c kh\u0026#237; độc như H2S, NH3, NO2-.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eThủy sản bị stress, yếu \u0026amp; Ph\u0026#225;t sinh dịch bệnh: \u003c/strong\u003eSự thiếu hụt \u0026#244;xy k\u0026#233;o theo kh\u0026#237; độc cao khiến c\u0026#225; bị stress, giảm khả năng đề kh\u0026#225;ng, tổn thương mang v\u0026#224; ruột, d\u0026#225;n tiếp l\u0026#224;m vi khuẩn/k\u0026#253; sinh tr\u0026#249;ng b\u0026#249;ng ph\u0026#225;t g\u0026#226;y bệnh v\u0026#224; chết h\u0026#224;ng loạt.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eẢnh hưởng đến tốc độ tăng trưởng: \u003c/strong\u003eSống trong m\u0026#244;i trường \u0026#244; nhiễm v\u0026#224; thiếu \u0026#244;xy, c\u0026#225; giảm bắt mồi, chậm lớn, ph\u0026#226;n h\u0026#243;a k\u0026#237;ch thước kh\u0026#244;ng đều.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eBảng 3.1: C\u0026#225;c chỉ ti\u0026#234;u m\u0026#244;i trường nước ao nu\u0026#244;i v\u0026#224; biện ph\u0026#225;p quản l\u0026#253;\u003c/strong\u003e\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eChỉ ti\u0026#234;u m\u0026#244;i trường\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eMức th\u0026#237;ch hợp\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eHiện tượng bất lợi \u0026amp; Nguy\u0026#234;n nh\u0026#226;n\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eBiện ph\u0026#225;p xử l\u0026#253; / Khắc phục\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eNhiệt độ nước\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e25\u0026#176;C – 28\u0026#176;C\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e• \u0026gt; 32\u0026#176;C (qu\u0026#225; n\u0026#243;ng): C\u0026#225; giảm ăn, O2 giảm.\u003cbr\u003e• \u0026lt; 18\u0026#176;C (qu\u0026#225; lạnh): C\u0026#225; ngừng ăn, dễ nhiễm nấm.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e• Giữ mức nước ao s\u0026#226;u (1.5 - 2m).\u003cbr\u003e• Trồng c\u0026#226;y b\u0026#243;ng m\u0026#225;t quanh bờ hoặc thả b\u0026#232;o t\u0026#226;y 1/5 diện t\u0026#237;ch ao.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eĐộ trong của nước\u003cbr\u003e(Đo đĩa Secchi)\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e20 cm – 30 cm\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e• \u0026lt; 20 cm: Nước qu\u0026#225; đục, nhiều ph\u0026#249; sa hoặc tảo qu\u0026#225; d\u0026#224;y.\u003cbr\u003e• \u0026gt; 30 cm: Nước qu\u0026#225; trong, ngh\u0026#232;o dinh dưỡng/thức ăn tự nhi\u0026#234;n.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e• Nước qu\u0026#225; đục: Thay nước sạch, b\u0026#243;n chế phẩm vi sinh EM.\u003cbr\u003e• Nước qu\u0026#225; trong: B\u0026#243;n ph\u0026#226;n hữu cơ hoai mục để g\u0026#226;y m\u0026#224;u nước.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eM\u0026#224;u sắc của nước\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eXanh đọt chuối / V\u0026#224;ng n\u0026#226;u\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e• Nước m\u0026#224;u xanh đen/xanh đậm: Tảo lam ph\u0026#225;t triển qu\u0026#225; mức.\u003cbr\u003e• Nước m\u0026#224;u đen/thối: \u0026#212; nhiễm chất hữu cơ nặng.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e• Bật m\u0026#225;y sục kh\u0026#237;/m\u0026#225;y quạt nước.\u003cbr\u003e• Thay 20% - 30% nước sạch.\u003cbr\u003e• Sử dụng v\u0026#244;i đ\u0026#234;m hoặc vi sinh xử l\u0026#253; đ\u0026#225;y.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003cp\u003e\u003cstrong\u003eBước 4: Thu hoạch c\u0026#225; nu\u0026#244;i trong ao\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003eKhi c\u0026#225; đạt k\u0026#237;ch thước thương phẩm, tiến h\u0026#224;nh thu hoạch theo một trong hai h\u0026#236;nh thức:\u003cbr\u003e• Thu tỉa: D\u0026#249;ng lưới k\u0026#233;o chọn bắt những con c\u0026#225; đạt cỡ thương phẩm b\u0026#225;n trước, giữ lại c\u0026#225; nhỏ tiếp tục nu\u0026#244;i. \u0026#193;p dụng khi mật độ c\u0026#225; trong ao qu\u0026#225; d\u0026#224;y.\u003cbr\u003e• Thu to\u0026#224;n bộ: R\u0026#250;t bớt nước, k\u0026#233;o lưới bắt đại bộ phận c\u0026#225;, sau đ\u0026#243; th\u0026#225;o cạn nước ao để bắt sạch c\u0026#225;. \u0026#193;p dụng khi đại đa số c\u0026#225; trong ao đạt cỡ thương phẩm.\u003c/p\u003e\u003ch3\u003e3. Bảo vệ môi trường nuôi thủy sản và nguồn lợi thủy sản bền vững\u003c/h3\u003e\u003cp\u003eBảo vệ m\u0026#244;i trường sống v\u0026#224; nguồn lợi thủy sản l\u0026#224; tr\u0026#225;ch nhiệm cấp thiết nhằm ph\u0026#225;t triển ng\u0026#224;nh thủy sản bền vững:\u003cbr\u003e1. C\u0026#225;c biện ph\u0026#225;p bảo vệ m\u0026#244;i trường nu\u0026#244;i: \u003cem\u003eXử l\u0026#253; nước thải v\u0026#224; b\u0026#249;n thải trước khi xả ra m\u0026#244;i trường; kh\u0026#244;ng sử dụng h\u0026#243;a chất, kh\u0026#225;ng sinh cấm; tăng cường ứng dụng c\u0026#244;ng nghệ vi sinh (chế phẩm sinh học); ứng dụng hệ thống nu\u0026#244;i tuần ho\u0026#224;n (RAS).\u003c/em\u003e\u003cem\u003e\u003cbr\u003e\u003c/em\u003e2. C\u0026#225;c biện ph\u0026#225;p bảo vệ nguồn lợi thủy sản tự nhi\u0026#234;n: \u003cem\u003eNghi\u0026#234;m cấm đ\u0026#225;nh bắt bằng chất nổ, xung điện, h\u0026#243;a chất độc hại; nghi\u0026#234;m cấm sử dụng lưới c\u0026#243; k\u0026#237;ch thước mắt lưới qu\u0026#225; nhỏ; bảo vệ c\u0026#225;c khu bảo tồn biển v\u0026#224; rừng ngập mặn; cấm đ\u0026#225;nh bắt trong m\u0026#249;a sinh sản của thủy sản; thả bổ sung c\u0026#225; giống t\u0026#225;i tạo nguồn lợi.\u003c/em\u003e\u003c/p\u003e\u003ch3\u003eIII. MA TRẬN BÀI TẬP VÀ ĐÁP ÁN CHUẨN HSG (4 MỨC ĐỘ)\u003c/h3\u003e\u003ch3\u003e1. Mức độ Nhận biết – Thông hiểu\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 1.1: \u003c/strong\u003eTr\u0026#236;nh b\u0026#224;y t\u0026#243;m tắt c\u0026#225;c bước trong quy tr\u0026#236;nh chuẩn bị ao nu\u0026#244;i c\u0026#225;. Tại sao trong kh\u0026#226;u l\u0026#224;m sạch đ\u0026#225;y ao, người ta kh\u0026#244;ng h\u0026#250;t sạch ho\u0026#224;n to\u0026#224;n b\u0026#249;n đ\u0026#225;y m\u0026#224; chỉ để lại một lớp b\u0026#249;n d\u0026#224;y khoảng 10 – 15 cm?\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003e📌\u003c/strong\u003e\u003cstrong\u003e HƯỚNG DẪN CHẤM C\u0026#194;U 1.1\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e\u003cem\u003eĐ\u0026#193;P \u0026#193;N CHUẨN C\u0026#194;U 1.1:\u003c/em\u003e\u003cem\u003e\u003cbr\u003e1. C\u0026#225;c bước chuẩn bị ao nu\u0026#244;i c\u0026#225;:\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   - Bước 1: Th\u0026#225;o cạn nước, dọn vệ sinh bờ ao, bắt sạch c\u0026#225; tạp, c\u0026#225; dữ.\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   - Bước 2: V\u0026#233;t b\u0026#249;n đ\u0026#225;y ao, chỉ giữ lại lớp b\u0026#249;n xốp d\u0026#224;y 10 - 15 cm.\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   - Bước 3: Rắc v\u0026#244;i bột (7 - 10 kg/100m2) khử tr\u0026#249;ng, khử chua đ\u0026#225;y ao.\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   - Bước 4: Phơi đ\u0026#225;y ao 3 - 5 ng\u0026#224;y dưới \u0026#225;nh nắng mặt trời.\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   - Bước 5: Lấy nước sạch v\u0026#224;o ao qua t\u0026#250;i lọc vải d\u0026#224;y.\u003c/em\u003e\u003cem\u003e\u003cbr\u003e2. Giải th\u0026#237;ch l\u0026#253; do giữ lại 10 - 15 cm b\u0026#249;n đ\u0026#225;y:\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   - Lớp b\u0026#249;n đ\u0026#225;y vừa phải l\u0026#224; nơi t\u0026#237;ch tụ dinh dưỡng cần thiết để ph\u0026#225;t triển sinh vật đ\u0026#225;y v\u0026#224; tảo c\u0026#243; lợi (nguồn thức ăn tự nhi\u0026#234;n ban đầu cho c\u0026#225;).\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   - B\u0026#249;n đ\u0026#225;y c\u0026#243; khả năng đệm nhiệt độ v\u0026#224; đệm pH cho nước ao, gi\u0026#250;p m\u0026#244;i trường nước ao ổn định hơn.\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   - Nếu h\u0026#250;t sạch b\u0026#249;n, ao trở th\u0026#224;nh \u0026#39;ao ngh\u0026#232;o\u0026#39;, nước kh\u0026#243; g\u0026#226;y m\u0026#224;u v\u0026#224; c\u0026#225; thiếu nguồn thức ăn tự nhi\u0026#234;n.\u003c/em\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 1.2: \u003c/strong\u003eTr\u0026#236;nh b\u0026#224;y phương ph\u0026#225;p đo độ trong của nước ao nu\u0026#244;i bằng đĩa Secchi. Độ trong th\u0026#237;ch hợp cho ao nu\u0026#244;i c\u0026#225; l\u0026#224; bao nhi\u0026#234;u?\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003e📌\u003c/strong\u003e\u003cstrong\u003e HƯỚNG DẪN CHẤM C\u0026#194;U 1.2\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e\u003cem\u003eĐ\u0026#193;P \u0026#193;N CHUẨN C\u0026#194;U 1.2:\u003c/em\u003e\u003cem\u003e\u003cbr\u003e\u003c/em\u003e\u003cem\u003e1. C\u0026#225;c bước đo độ trong bằng đĩa Secchi:\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   - Bước 1: Thả chậm đĩa Secchi xuống nước ao theo phương thẳng đứng cho đến khi kh\u0026#244;ng c\u0026#242;n nh\u0026#236;n thấy vạch đen/trắng tr\u0026#234;n mặt đĩa. Ghi lại độ s\u0026#226;u d1 (cm).\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   - Bước 2: M\u0026#243;c đĩa l\u0026#234;n từ từ cho đến khi vừa nh\u0026#236;n thấy lại vạch đen/trắng tr\u0026#234;n mặt đĩa. Ghi lại độ s\u0026#226;u d2 (cm).\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   - Bước 3: T\u0026#237;nh độ trong trung b\u0026#236;nh: D = (d1 + d2) / 2 (cm).\u003c/em\u003e\u003cem\u003e\u003cbr\u003e2. Chỉ số độ trong th\u0026#237;ch hợp:\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   - Độ trong th\u0026#237;ch hợp cho ao nu\u0026#244;i c\u0026#225; l\u0026#224; từ 20 cm đến 30 cm.\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   - Nếu D \u0026lt; 20 cm: Nước qu\u0026#225; đục (nhiều ph\u0026#249; sa hoặc tảo b\u0026#249;ng ph\u0026#225;t).\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   - Nếu D \u0026gt; 30 cm: Nước qu\u0026#225; trong (ngh\u0026#232;o dinh dưỡng v\u0026#224; thức ăn tự nhi\u0026#234;n).\u003c/em\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003ch3\u003e2. Mức độ Vận dụng\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 2.1: \u003c/strong\u003eTại sao trước khi thả c\u0026#225; giống v\u0026#224;o ao nu\u0026#244;i, người ta phải ng\u0026#226;m t\u0026#250;i chứa c\u0026#225; giống trong nước ao từ 15 – 20 ph\u0026#250;t? Nếu bỏ qua bước n\u0026#224;y sẽ dẫn đến hậu quả g\u0026#236;?\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003e📌\u003c/strong\u003e\u003cstrong\u003e HƯỚNG DẪN CHẤM C\u0026#194;U 2.1\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e\u003cem\u003eĐ\u0026#193;P \u0026#193;N CHUẨN C\u0026#194;U 2.1:\u003c/em\u003e\u003cem\u003e\u003cbr\u003e1. L\u0026#253; do ng\u0026#226;m t\u0026#250;i c\u0026#225; giống:\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   - Nước trong t\u0026#250;i vận chuyển c\u0026#225; v\u0026#224; nước trong ao nu\u0026#244;i thường c\u0026#243; sự ch\u0026#234;nh lệch về nhiệt độ, pH v\u0026#224; độ mặn.\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   - Việc ng\u0026#226;m t\u0026#250;i nylon chứa c\u0026#225; trong nước ao 15 - 20 ph\u0026#250;t gi\u0026#250;p nhiệt độ nước b\u0026#234;n trong t\u0026#250;i từ từ c\u0026#226;n bằng với nhiệt độ nước ao nu\u0026#244;i.\u003c/em\u003e\u003cem\u003e\u003cbr\u003e2. Hậu quả nếu bỏ qua bước n\u0026#224;y:\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   - C\u0026#225; bị \u0026#39;sốc nhiệt\u0026#39; đột ngột khi thả trực tiếp v\u0026#224;o ao.\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   - Hậu quả: C\u0026#225; bị co giật, suy yếu, ch\u0026#236;m xuống đ\u0026#225;y hoặc chết h\u0026#224;ng loạt sau khi thả v\u0026#224;i giờ, l\u0026#224;m giảm tỷ lệ sống nghi\u0026#234;m trọng.\u003c/em\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 2.2: \u003c/strong\u003eSo s\u0026#225;nh ưu điểm v\u0026#224; hạn chế của hai phương ph\u0026#225;p thu hoạch c\u0026#225; nu\u0026#244;i trong ao: Thu tỉa v\u0026#224; Thu to\u0026#224;n bộ. Trong trường hợp n\u0026#224;o th\u0026#236; n\u0026#234;n \u0026#225;p dụng từng phương ph\u0026#225;p?\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003e📌\u003c/strong\u003e\u003cstrong\u003e HƯỚNG DẪN CHẤM C\u0026#194;U 2.2\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e\u003cem\u003eĐ\u0026#193;P \u0026#193;N CHUẨN C\u0026#194;U 2.2:\u003c/em\u003e\u003cem\u003e\u003cbr\u003e1. So s\u0026#225;nh hai phương ph\u0026#225;p thu hoạch:\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   • Thu tỉa:\u003c/em\u003e\u003cem\u003e\u003cbr\u003e     - Ưu điểm: Bắt được c\u0026#225; lớn đạt chuẩn, giảm mật độ ao nu\u0026#244;i, gi\u0026#250;p c\u0026#225; nhỏ c\u0026#242;n lại c\u0026#243; kh\u0026#244;ng gian v\u0026#224; thức ăn để lớn nhanh hơn; cung cấp sản phẩm rải r\u0026#225;c theo nhu cầu thị trường.\u003c/em\u003e\u003cem\u003e\u003cbr\u003e     - Hạn chế: L\u0026#224;m đục nước ao, g\u0026#226;y stress cho lượng c\u0026#225; c\u0026#242;n lại trong ao mỗi lần k\u0026#233;o lưới.\u003c/em\u003e\u003cem\u003e\u003cbr\u003e     - \u0026#193;p dụng: Khi mật độ c\u0026#225; trong ao qu\u0026#225; d\u0026#224;y, cỡ c\u0026#225; kh\u0026#244;ng đồng đều.\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   • Thu to\u0026#224;n bộ:\u003c/em\u003e\u003cem\u003e\u003cbr\u003e     - Ưu điểm: Thu hoạch nhanh ch\u0026#243;ng, tập trung, thu hồi vốn một lần, dễ d\u0026#224;ng vệ sinh cải tạo ao cho lứa nu\u0026#244;i tiếp theo.\u003c/em\u003e\u003cem\u003e\u003cbr\u003e     - Hạn chế: Y\u0026#234;u cầu thị trường ti\u0026#234;u thụ lượng lớn sản phẩm c\u0026#249;ng l\u0026#250;c; c\u0026#225; nhỏ chưa đạt cỡ thương phẩm cũng bị bắt b\u0026#225;n gi\u0026#225; thấp.\u003c/em\u003e\u003cem\u003e\u003cbr\u003e\u003c/em\u003e\u003cem\u003e     - \u0026#193;p dụng: Khi đa số c\u0026#225; trong ao đ\u0026#227; đạt k\u0026#237;ch cỡ thương phẩm đồng đều.\u003c/em\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003ch3\u003e3. Mức độ Vận dụng cao \u0026 Phân tích chuyên sâu (Đề HSG nguồn)\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 3.1 (Đề HSG tỉnh Vĩnh Long - 3.0 điểm): \u003c/strong\u003ePh\u0026#226;n t\u0026#237;ch chi tiết t\u0026#225;c hại đến vật nu\u0026#244;i thủy sản v\u0026#224; ảnh hưởng đến m\u0026#244;i trường ao nu\u0026#244;i khi người nu\u0026#244;i sử dụng lượng thức ăn qu\u0026#225; nhiều so với nhu cầu. Từ đ\u0026#243;, h\u0026#227;y đề xuất c\u0026#225;c biện ph\u0026#225;p quản l\u0026#253; thức ăn th\u0026#244;ng minh trong nu\u0026#244;i thủy sản.\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003e📌\u003c/strong\u003e\u003cstrong\u003e HƯỚNG DẪN CHẤM C\u0026#194;U 3.1 CHUẨN SỞ GDĐT\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e\u003cem\u003eĐ\u0026#193;P \u0026#193;N CHUẨN V\u0026#192; THANG ĐIỂM CHẤM (C\u0026#194;U 2C ĐỀ HSG VĨNH LONG - 3.0 ĐIỂM):\u003c/em\u003e\u003cem\u003e\u003cbr\u003e1. T\u0026#225;c hại của việc cho ăn thừa thức ăn (2.5 điểm - Mỗi \u0026#253; đ\u0026#250;ng 0.25 - 0.5đ):\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   - G\u0026#226;y l\u0026#227;ng ph\u0026#237; thức ăn (chi ph\u0026#237; thức ăn chiếm tỷ trọng cao nhất trong chăn nu\u0026#244;i) (0.25đ).\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   - L\u0026#224;m dơ ao, bẩn nước, tạo điều kiện cho tảo độc b\u0026#249;ng ph\u0026#225;t mạnh (0.5đ).\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   - L\u0026#224;m suy giảm nồng độ \u0026#244;xy h\u0026#242;a tan v\u0026#224; l\u0026#224;m \u0026#244; nhiễm nguồn nước trong ao (0.5đ).\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   - Thủy sản bị stress, suy giảm sức đề kh\u0026#225;ng, dễ bị vi khuẩn/k\u0026#253; sinh tr\u0026#249;ng tấn c\u0026#244;ng g\u0026#226;y bệnh (0.5đ).\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   - Tăng chi ph\u0026#237; sản xuất (chi ph\u0026#237; xử l\u0026#253; nước, thuốc điều trị bệnh) (0.25đ).\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   - Ảnh hưởng ti\u0026#234;u cực đến sự tăng trưởng v\u0026#224; tỷ lệ sống của thủy sản (0.5đ).\u003c/em\u003e\u003cem\u003e\u003cbr\u003e2. Đề xuất giải ph\u0026#225;p quản l\u0026#253; thức ăn th\u0026#244;ng minh (0.5 điểm):\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   - Thực hiện đ\u0026#250;ng nguy\u0026#234;n tắc \u0026#39;4 định\u0026#39; (định lượng, định chất, định vị tr\u0026#237;, định thời gian).\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   - Sử dụng s\u0026#224;ng ăn/s\u0026#224;n cho ăn để kiểm tra sức ăn của c\u0026#225; sau 1 - 2 giờ cho ăn.\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   - Cắt giảm hoặc ngừng cho ăn khi thời tiết biến động xấu (mưa b\u0026#227;o, oi n\u0026#243;ng) hoặc nước ao bị bẩn.\u003c/em\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003ch3\u003e4. Bài tập Tình huống Thực tiễn \u0026 Lập Kế hoạch Chi phí\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 4.1 (B\u0026#224;i tập lập kế hoạch nu\u0026#244;i c\u0026#225; cảnh / c\u0026#225; ao): \u003c/strong\u003eGia đ\u0026#236;nh bạn An dự định nu\u0026#244;i một bể c\u0026#225; v\u0026#224;ng gồm 10 con. Biết rằng: Gi\u0026#225; mỗi con c\u0026#225; v\u0026#224;ng giống l\u0026#224; 20.000 đồng; Tiền mua bể k\u0026#237;nh v\u0026#224; c\u0026#225;c thiết bị phụ trợ (m\u0026#225;y lọc, m\u0026#225;y sục kh\u0026#237; O2) l\u0026#224; 800.000 đồng; Tiền mua thức ăn cho c\u0026#225; l\u0026#224; 40.000 đồng/th\u0026#225;ng; Chi ph\u0026#237; điện, nước sinh hoạt cho bể c\u0026#225; ước t\u0026#237;nh 20.000 đồng/th\u0026#225;ng; Chi ph\u0026#237; ph\u0026#242;ng trị bệnh dự ph\u0026#242;ng l\u0026#224; 50.000 đồng/năm. Em h\u0026#227;y gi\u0026#250;p bạn An lập bảng kế hoạch dự to\u0026#225;n chi ph\u0026#237; cần thiết để nu\u0026#244;i 10 con c\u0026#225; v\u0026#224;ng trong năm đầu ti\u0026#234;n.\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003e📌\u003c/strong\u003e\u003cstrong\u003e HƯỚNG DẪN CHẤM C\u0026#194;U 4.1\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e\u003cem\u003eĐ\u0026#193;P \u0026#193;N CHUẨN C\u0026#194;U 4.1 (B\u0026#192;I TẬP BẢNG DỰ TO\u0026#193;N CHI PH\u0026#205;):\u003c/em\u003e\u003cem\u003e\u003cbr\u003eLập Bảng dự to\u0026#225;n chi ph\u0026#237; nu\u0026#244;i 10 con c\u0026#225; v\u0026#224;ng trong năm đầu ti\u0026#234;n (12 th\u0026#225;ng):\u003c/em\u003e\u003cem\u003e\u003cbr\u003e\u003c/em\u003e\u003cem\u003e\u003cbr\u003e| STT | Nội dung chi ph\u0026#237; | Đơn vị t\u0026#237;nh | Số lượng | Đơn gi\u0026#225; (đồng) | Th\u0026#224;nh tiền (đồng) |\u003c/em\u003e\u003cem\u003e\u003cbr\u003e| --- | --- | --- | --- | --- | --- |\u003c/em\u003e\u003cem\u003e\u003cbr\u003e| 1 | C\u0026#225; v\u0026#224;ng giống | Con | 10 | 20.000 | 200.000 |\u003c/em\u003e\u003cem\u003e\u003cbr\u003e| 2 | Bể k\u0026#237;nh \u0026amp; Thiết bị (lọc, sục kh\u0026#237;) | Bộ | 1 | 800.000 | 800.000 |\u003c/em\u003e\u003cem\u003e\u003cbr\u003e| 3 | Thức ăn cho c\u0026#225; (12 th\u0026#225;ng) | Th\u0026#225;ng | 12 | 40.000 | 480.000 |\u003c/em\u003e\u003cem\u003e\u003cbr\u003e| 4 | Điện, nước sinh hoạt (12 th\u0026#225;ng) | Th\u0026#225;ng | 12 | 20.000 | 240.000 |\u003c/em\u003e\u003cem\u003e\u003cbr\u003e| 5 | Thuốc ph\u0026#242;ng trị bệnh dự ph\u0026#242;ng | Năm | 1 | 50.000 | 50.000 |\u003c/em\u003e\u003cem\u003e\u003cbr\u003e| TỔNG CỘNG CHI PH\u0026#205; NĂM ĐẦU TI\u0026#202;N | | | | | 1.770.000 đồng |\u003c/em\u003e\u003cem\u003e\u003cbr\u003e\u003c/em\u003e\u003cem\u003e\u003cbr\u003e\u003c/em\u003e\u003cem\u003e→ Nhận x\u0026#233;t: Chi ph\u0026#237; ban đầu cho bể k\u0026#237;nh \u0026amp; thiết bị chiếm tỷ trọng lớn (45.2%), tuy nhi\u0026#234;n sang c\u0026#225;c năm tiếp theo, chi ph\u0026#237; cố định n\u0026#224;y sẽ kh\u0026#244;ng c\u0026#242;n, gi\u0026#250;p giảm chi ph\u0026#237; vận h\u0026#224;nh h\u0026#224;ng năm xuống chỉ c\u0026#242;n 770.000 đồng/năm.\u003c/em\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003ch3\u003eIV. PHẦN GHI NHỚ NHANH CỐT LÕI (CHUYÊN ĐỀ 3)\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003e✔\u003c/strong\u003e\u003cstrong\u003e Điểm 1: \u003c/strong\u003e4 bước quy tr\u0026#236;nh nu\u0026#244;i c\u0026#225; ao: (1) Chuẩn bị ao nu\u0026#244;i → (2) Chuẩn bị c\u0026#225; giống \u0026amp; thả c\u0026#225; → (3) Chăm s\u0026#243;c \u0026amp; Quản l\u0026#253; m\u0026#244;i trường nước → (4) Thu hoạch.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e✔\u003c/strong\u003e\u003cstrong\u003e Điểm 2: \u003c/strong\u003eChuẩn bị ao nu\u0026#244;i: H\u0026#250;t bớt b\u0026#249;n (giữ 10-15cm) → Rắc v\u0026#244;i bột (7-10kg/100m\u0026#178;) → Phơi đ\u0026#225;y (3-5 ng\u0026#224;y) → Lấy nước qua t\u0026#250;i lọc.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e✔\u003c/strong\u003e\u003cstrong\u003e Điểm 3: \u003c/strong\u003eThả c\u0026#225; giống: Ng\u0026#226;m t\u0026#250;i c\u0026#225; trong nước ao 15-20 ph\u0026#250;t trước khi mở miệng t\u0026#250;i thả c\u0026#225; để chống \u0026#39;sốc nhiệt\u0026#39;.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e✔\u003c/strong\u003e\u003cstrong\u003e Điểm 4: \u003c/strong\u003eNguy\u0026#234;n tắc cho ăn \u0026#39;4 định\u0026#39;: Định lượng, Định chất, Định vị tr\u0026#237;, Định thời gian. Giảm/ngừng cho ăn khi thời tiết xấu.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e✔\u003c/strong\u003e\u003cstrong\u003e Điểm 5: \u003c/strong\u003eT\u0026#225;c hại cho ăn thừa: L\u0026#227;ng ph\u0026#237; chi ph\u0026#237; → Ph\u0026#250; dưỡng nước → B\u0026#249;ng ph\u0026#225;t tảo độc → Thiếu O2 \u0026amp; sinh kh\u0026#237; độc → C\u0026#225; stress/bệnh/chết h\u0026#224;ng loạt.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e✔\u003c/strong\u003e\u003cstrong\u003e Điểm 6: \u003c/strong\u003eC\u0026#225;c chỉ ti\u0026#234;u nước ao: Nhiệt độ 25 - 28\u0026#176;C; Độ trong th\u0026#237;ch hợp 20 - 30 cm (đo bằng đĩa Secchi).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e✔\u003c/strong\u003e\u003cstrong\u003e Điểm 7: \u003c/strong\u003e2 h\u0026#236;nh thức thu hoạch: Thu tỉa (bắt c\u0026#225; lớn, giảm mật độ khi ao qu\u0026#225; d\u0026#224;y) v\u0026#224; Thu to\u0026#224;n bộ (th\u0026#225;o cạn bắt hết khi c\u0026#225; đồng đều thương phẩm).\u003c/p\u003e","4":"\u003ch2\u003eCHUYÊN ĐỀ 4: BIỂU DIỄN KỸ THUẬT VÀ BẢN VẼ KỸ THUẬT(TRỌNG TÂM CÔNG NGHỆ 8)\u003c/h2\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003e★ MỤC TI\u0026#202;U V\u0026#192; ĐỊNH HƯỚNG \u0026#212;N HSG CHUY\u0026#202;N ĐỀ 4\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e• Phạm vi kiến thức: Ti\u0026#234;u chuẩn tr\u0026#236;nh b\u0026#224;y bản vẽ kỹ thuật (TCVN/ISO), Ph\u0026#233;p chiếu g\u0026#243;c thứ nhất, Dựng 3 h\u0026#236;nh chiếu vu\u0026#244;ng g\u0026#243;c, Đọc bản vẽ chi tiết, bản vẽ lắp, bản vẽ nh\u0026#224; (C\u0026#244;ng nghệ 8 - B\u0026#224;i 1 đến B\u0026#224;i 5).\u003c/p\u003e\u003cp\u003e• Cấu tr\u0026#250;c thi HSG Vĩnh Long: Chiếm 3,0/20,0 điểm (C\u0026#226;u 3 tự luận đồ họa). Y\u0026#234;u cầu vẽ ch\u0026#237;nh x\u0026#225;c 3 h\u0026#236;nh chiếu vu\u0026#244;ng g\u0026#243;c (Đứng, Bằng, Cạnh) từ m\u0026#244; h\u0026#236;nh 3D cho trước theo đ\u0026#250;ng tỉ lệ (v\u0026#237; dụ 1:2), gi\u0026#243;ng đối ứng, n\u0026#233;t vẽ quy chuẩn v\u0026#224; ghi k\u0026#237;ch thước.\u003c/p\u003e\u003cp\u003e• Năng lực ph\u0026#226;n h\u0026#243;a: Kỹ năng tư duy h\u0026#236;nh học kh\u0026#244;ng gian 3D  2D, sự cẩn thận ch\u0026#237;nh x\u0026#225;c trong đường n\u0026#233;t gi\u0026#243;ng, tu\u0026#226;n thủ đ\u0026#250;ng quy chuẩn ISO/TCVN v\u0026#224; kh\u0026#244;ng bị mắc c\u0026#225;c lỗi sai kinh điển bị trừ điểm.\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003cp\u003e\u003cstrong\u003ePHẦN I: L\u0026#221; THUYẾT CHUY\u0026#202;N S\u0026#194;U V\u0026#192; BẢN CHẤT KHOA HỌC\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e1. C\u0026#225;c ti\u0026#234;u chuẩn tr\u0026#236;nh b\u0026#224;y bản vẽ kỹ thuật (TCVN \u0026amp; ISO)\u003c/strong\u003e\u003c/p\u003e\u003cp\u003eBản vẽ kỹ thuật l\u0026#224; \u0026quot;ng\u0026#244;n ngữ\u0026quot; chung của giới kỹ thuật. Để đảm bảo mọi người trong ng\u0026#224;nh sản xuất, chế tạo v\u0026#224; x\u0026#226;y dựng đều hiểu thống nhất, bản vẽ phải tu\u0026#226;n thủ nghi\u0026#234;m ngặt c\u0026#225;c quy định về khổ giấy, tỉ lệ, đường n\u0026#233;t v\u0026#224; ghi k\u0026#237;ch thước.\u003cbr\u003e\u003cstrong\u003ea) Ti\u0026#234;u chuẩn về Khổ giấy (TCVN 7285:2003 / ISO 5457:1999):\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003eKhổ giấy bản vẽ được chia từ khổ giấy ch\u0026#237;nh A0. C\u0026#225;c khổ giấy nhỏ hơn được tạo ra bằng c\u0026#225;ch chia đ\u0026#244;i chiều d\u0026#224;i của khổ giấy ngay trước n\u0026#243;.\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eK\u0026#253; hiệu khổ giấy\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eK\u0026#237;ch thước (mm)\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#225;ch tạo lập \u0026amp; Ứng dụng trong thực tế\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eA0\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e1189 x 841\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eKhổ gốc ti\u0026#234;u chuẩn, diện t\u0026#237;ch xấp xỉ 1 m\u0026#178;.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eA1\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e841 x 594\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eBằng 1/2 khổ A0 (chia đ\u0026#244;i chiều d\u0026#224;i 1189 mm).\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eA2\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e594 x 420\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eBằng 1/2 khổ A1 (chia đ\u0026#244;i chiều d\u0026#224;i 841 mm).\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eA3\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e420 x 297\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eBằng 1/2 khổ A2 (chia đ\u0026#244;i chiều d\u0026#224;i 594 mm).\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eA4\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e297 x 210\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eBằng 1/2 khổ A3 (khổ ti\u0026#234;u chuẩn vẽ b\u0026#224;i tập \u0026amp; thi HSG).\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003cp\u003e\u003cstrong\u003eQuy tắc Khung bản vẽ v\u0026#224; Khung t\u0026#234;n: \u003c/strong\u003eMọi bản vẽ kỹ thuật đều phải c\u0026#243; khung bản vẽ (c\u0026#225;ch m\u0026#233;p giấy 10 mm, ri\u0026#234;ng m\u0026#233;p tr\u0026#225;i đ\u0026#243;ng tập c\u0026#225;ch 20 mm) v\u0026#224; khung t\u0026#234;n. Khung t\u0026#234;n đặt ở g\u0026#243;c dưới b\u0026#234;n phải bản vẽ, chữ viết trong khung t\u0026#234;n hướng l\u0026#234;n tr\u0026#234;n hoặc sang tr\u0026#225;i.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eb) Ti\u0026#234;u chuẩn về Tỉ lệ (TCVN 7286:2003 / ISO 5455:1979):\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003eTỉ lệ l\u0026#224; tỉ số giữa k\u0026#237;ch thước d\u0026#224;i đo được tr\u0026#234;n h\u0026#236;nh biểu diễn của vật thể v\u0026#224; k\u0026#237;ch thước thực tương ứng tr\u0026#234;n vật thể đ\u0026#243;.\u003cbr\u003e\u003cstrong\u003e• Tỉ lệ nguy\u0026#234;n h\u0026#236;nh (1:1): \u003c/strong\u003eK\u0026#237;ch thước vẽ bằng k\u0026#237;ch thước thực.\u003cbr\u003e\u003cstrong\u003e• Tỉ lệ thu nhỏ (1:2, 1:5, 1:10,...): \u003c/strong\u003eK\u0026#237;ch thước vẽ nhỏ hơn k\u0026#237;ch thước thực (thường d\u0026#249;ng trong thi HSG khi vật thể lớn, v\u0026#237; dụ tỉ lệ 1:2 l\u0026#224;m giảm một nửa k\u0026#237;ch thước vẽ).\u003cbr\u003e\u003cstrong\u003e• Tỉ lệ ph\u0026#243;ng to (2:1, 5:1, 10:1,...): \u003c/strong\u003eK\u0026#237;ch thước vẽ lớn hơn k\u0026#237;ch thước thực (d\u0026#249;ng cho c\u0026#225;c chi tiết qu\u0026#225; nhỏ).\u003cbr\u003e\u003cstrong\u003e⚠️ LƯU \u0026#221; BẢN CHẤT CỰC KỲ QUAN TRỌNG: \u003c/strong\u003eD\u0026#249; vẽ theo tỉ lệ thu nhỏ hay ph\u0026#243;ng to, con số k\u0026#237;ch thước ghi tr\u0026#234;n bản vẽ LU\u0026#212;N LU\u0026#212;N l\u0026#224; CHỈ SỐ K\u0026#205;CH THƯỚC THỰC của vật thể, tuyệt đối kh\u0026#244;ng được ghi k\u0026#237;ch thước đ\u0026#227; chia/nh\u0026#226;n tỉ lệ!\u003c/p\u003e\u003cp\u003e\u003cstrong\u003ec) Ti\u0026#234;u chuẩn về Đường n\u0026#233;t (TCVN 8-20:2002 / ISO 128-20:1996):\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eT\u0026#234;n đường n\u0026#233;t\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eDạng n\u0026#233;t vẽ\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eChiều d\u0026#224;y (mm)\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eỨng dụng biểu diễn ch\u0026#237;nh\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eN\u0026#233;t liền đậm\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e───────\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003es ≈ 0,5 – 0,7\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eĐường bao thấy, cạnh thấy của vật thể.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eN\u0026#233;t liền mảnh\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e─────── (mảnh)\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003es/2 ≈ 0,25 – 0,35\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eĐường d\u0026#243;ng, đường k\u0026#237;ch thước, đường gạch gạch mặt cắt.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eN\u0026#233;t đứt mảnh\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e– – – – – –\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003es/2 ≈ 0,25 – 0,35\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eĐường bao khuất, cạnh khuất của vật thể.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eN\u0026#233;t gạch chấm mảnh\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e─ ∙ ─ ∙ ─ ∙ ─\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003es/2 ≈ 0,25 – 0,35\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eĐường t\u0026#226;m, trục đối xứng, đường t\u0026#226;m đường tr\u0026#242;n.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003cp\u003e\u003cstrong\u003ed) Ti\u0026#234;u chuẩn về Ghi k\u0026#237;ch thước (TCVN 5705:1993):\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003eMột k\u0026#237;ch thước đầy đủ gồm 3 th\u0026#224;nh phần ch\u0026#237;nh:\u003cbr\u003e\u003cstrong\u003e1. Đường d\u0026#243;ng k\u0026#237;ch thước: \u003c/strong\u003eVẽ bằng n\u0026#233;t liền mảnh, vạch vu\u0026#244;ng g\u0026#243;c với đoạn cần ghi k\u0026#237;ch thước v\u0026#224; vượt qu\u0026#225; đường k\u0026#237;ch thước khoảng 2 – 4 mm.\u003cbr\u003e\u003cstrong\u003e2. Đường k\u0026#237;ch thước: \u003c/strong\u003eVẽ bằng n\u0026#233;t liền mảnh, song song với đoạn cần ghi k\u0026#237;ch thước, hai đầu c\u0026#243; mũi t\u0026#234;n nhọn chạm v\u0026#224;o đường d\u0026#243;ng.\u003cbr\u003e\u003cstrong\u003e3. Chữ số k\u0026#237;ch thước: \u003c/strong\u003eChỉ trị số k\u0026#237;ch thước thực (đơn vị mm, kh\u0026#244;ng ghi chữ \u0026quot;mm\u0026quot; sau con số). Chữ số được ghi nằm tr\u0026#234;n v\u0026#224; khoảng giữa đường k\u0026#237;ch thước, hướng chữ số đối với đường k\u0026#237;ch thước nghi\u0026#234;ng/thẳng đứng l\u0026#224; nh\u0026#236;n từ dưới l\u0026#234;n hoặc nh\u0026#236;n từ b\u0026#234;n phải sang.\u003cbr\u003e• Trước trị số đường k\u0026#237;nh đường tr\u0026#242;n ghi k\u0026#253; hiệu \u0026#216; (v\u0026#237; dụ \u0026#216;30).\u003cbr\u003e• Trước trị số b\u0026#225;n k\u0026#237;nh cung tr\u0026#242;n ghi k\u0026#253; hiệu R (v\u0026#237; dụ R15).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e2. Ph\u0026#233;p chiếu g\u0026#243;c thứ nhất v\u0026#224; Hệ thống 3 H\u0026#236;nh chiếu Vu\u0026#244;ng g\u0026#243;c\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003ea) Bản chất Ph\u0026#233;p chiếu g\u0026#243;c thứ nhất (Phương ph\u0026#225;p g\u0026#243;c chiếu I):\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003eTrong phương ph\u0026#225;p chiếu g\u0026#243;c thứ nhất, vật thể được đặt trong kh\u0026#244;ng gian giới hạn bởi 3 mặt phẳng chiếu vu\u0026#244;ng g\u0026#243;c với nhau từng đ\u0026#244;i một. \u003cstrong\u003eVị tr\u0026#237; tương đối: Người quan s\u0026#225;t -\u0026gt; Vật thể -\u0026gt; Mặt phẳng chiếu. \u003c/strong\u003eC\u0026#225;c tia chiếu từ mắt người quan s\u0026#225;t đi qua vật thể v\u0026#224; vu\u0026#244;ng g\u0026#243;c với c\u0026#225;c mặt phẳng chiếu.\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eMặt phẳng chiếu\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eVị tr\u0026#237; trong kh\u0026#244;ng gian\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eHướng chiếu quan s\u0026#225;t\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eH\u0026#236;nh chiếu thu được \u0026amp; K\u0026#237;ch thước thể hiện\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eMặt phẳng chiếu đứng (P1)\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eCh\u0026#237;nh diện (thẳng đứng đối diện)\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eHướng nh\u0026#236;n từ TRƯỚC tới\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eH\u0026#204;NH CHIẾU ĐỨNG:\u003cbr\u003eThể hiện chiều D\u0026#192;I v\u0026#224; chiều CAO.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eMặt phẳng chiếu bằng (P2)\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eNằm ngang ở ph\u0026#237;a dưới\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eHướng nh\u0026#236;n từ TR\u0026#202;N xuống\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eH\u0026#204;NH CHIẾU BẰNG:\u003cbr\u003eThể hiện chiều D\u0026#192;I v\u0026#224; chiều RỘNG.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eMặt phẳng chiếu cạnh (P3)\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eThẳng đứng ở b\u0026#234;n phải\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eHướng nh\u0026#236;n từ TR\u0026#193;I sang\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eH\u0026#204;NH CHIẾU CẠNH:\u003cbr\u003eThể hiện chiều RỘNG v\u0026#224; chiều CAO.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003cp\u003e\u003cstrong\u003eb) Quy tắc Trải phẳng kh\u0026#244;ng gian \u0026amp; Vị tr\u0026#237; 3 H\u0026#236;nh chiếu tr\u0026#234;n mặt phẳng bản vẽ:\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003eĐể đưa 3 h\u0026#236;nh chiếu trong kh\u0026#244;ng gian 3D về c\u0026#249;ng một mặt phẳng giấy vẽ 2D, người ta xoay:\u003cbr\u003e• Mặt phẳng chiếu bằng (P2) xoay xuống dưới 90\u0026#176; quanh trục nằm ngang.\u003cbr\u003e• Mặt phẳng chiếu cạnh (P3) xoay sang phải 90\u0026#176; quanh trục thẳng đứng.\u003cbr\u003eSau khi trải phẳng, vị tr\u0026#237; chuẩn x\u0026#225;c tuyệt đối của 3 h\u0026#236;nh chiếu tr\u0026#234;n bản vẽ như sau:\u003cbr\u003e\u003cstrong\u003e1. H\u0026#236;nh chiếu đứng: \u003c/strong\u003eĐặt ở g\u0026#243;c tr\u0026#234;n b\u0026#234;n tr\u0026#225;i bản vẽ (l\u0026#224;m h\u0026#236;nh chiếu trung t\u0026#226;m).\u003cbr\u003e\u003cstrong\u003e2. H\u0026#236;nh chiếu bằng: \u003c/strong\u003eĐặt ở NGAY DƯỚI h\u0026#236;nh chiếu đứng.\u003cbr\u003e\u003cstrong\u003e3. H\u0026#236;nh chiếu cạnh: \u003c/strong\u003eĐặt ở NGAY B\u0026#202;N PHẢI h\u0026#236;nh chiếu đứng.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003ec) Mối quan hệ Gi\u0026#243;ng đối ứng k\u0026#237;ch thước giữa 3 h\u0026#236;nh chiếu (Đ\u0026#227; thi HSG):\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e• QUA ĐƯỜNG GI\u0026#211;NG DỌC (ĐỨNG – BẰNG): \u003c/strong\u003eH\u0026#236;nh chiếu đứng v\u0026#224; H\u0026#236;nh chiếu bằng c\u0026#243; C\u0026#217;NG CHIỀU D\u0026#192;I. Cạnh tr\u0026#234;n/dưới của h\u0026#236;nh chiếu đứng d\u0026#243;ng thẳng đứng xuống cạnh tương ứng của h\u0026#236;nh chiếu bằng.\u003cbr\u003e\u003cstrong\u003e• QUA ĐƯỜNG GI\u0026#211;NG NGANG (ĐỨNG – CẠNH): \u003c/strong\u003eH\u0026#236;nh chiếu đứng v\u0026#224; H\u0026#236;nh chiếu cạnh c\u0026#243; C\u0026#217;NG CHIỀU CAO. Cạnh tr\u0026#225;i/phải của h\u0026#236;nh chiếu đứng d\u0026#243;ng nằm ngang sang cạnh tương ứng của h\u0026#236;nh chiếu cạnh.\u003cbr\u003e\u003cstrong\u003e• QUA ĐƯỜNG GI\u0026#211;NG RỘNG (BẰNG – CẠNH): \u003c/strong\u003eH\u0026#236;nh chiếu bằng v\u0026#224; H\u0026#236;nh chiếu cạnh c\u0026#243; C\u0026#217;NG CHIỀU RỘNG. K\u0026#237;ch thước chiều rộng từ h\u0026#236;nh chiếu bằng được chuyển sang h\u0026#236;nh chiếu cạnh qua đường ph\u0026#226;n gi\u0026#225;c 45\u0026#176; hoặc đường gi\u0026#243;ng b\u0026#225;n k\u0026#237;nh.\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003e★ SƠ ĐỒ BỐ TR\u0026#205; VỊ TR\u0026#205; V\u0026#192; MỐI QUAN HỆ GI\u0026#211;NG DỐI ỨNG H\u0026#204;NH CHIẾU\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e\u003c/p\u003e\u003cp\u003eSơ đồ bố tr\u0026#237; chuẩn vị tr\u0026#237; 3 h\u0026#236;nh chiếu tr\u0026#234;n bản vẽ:\u003c/p\u003e\u003cp\u003e       [ H\u0026#204;NH CHIẾU ĐỨNG ]  ─────────\u0026gt;  [ H\u0026#204;NH CHIẾU CẠNH ]\u003c/p\u003e\u003cp\u003e                │                                │\u003c/p\u003e\u003cp\u003e                │ (Gi\u0026#243;ng thẳng đứng)              │ (C\u0026#249;ng chiều rộng)\u003c/p\u003e\u003cp\u003e                ▼                                ▼\u003c/p\u003e\u003cp\u003e       [ H\u0026#204;NH CHIẾU BẰNG ]  ─────────────────────┘\u003c/p\u003e\u003cp\u003e⚠️ Tuyệt đối kh\u0026#244;ng được vẽ h\u0026#236;nh chiếu bằng sang b\u0026#234;n phải hay h\u0026#236;nh chiếu cạnh xuống dưới! Đổi vị tr\u0026#237; l\u0026#224; sai ho\u0026#224;n to\u0026#224;n bản chất phương ph\u0026#225;p chiếu g\u0026#243;c thứ nhất.\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003cp\u003e\u003cstrong\u003e3. Quy tr\u0026#236;nh Đọc Bản vẽ Kỹ thuật (Chi tiết, Lắp, Nh\u0026#224;)\u003c/strong\u003e\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eTr\u0026#236;nh tự\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eBản vẽ Chi tiết\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eBản vẽ Lắp\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eBản vẽ Nh\u0026#224;\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eBước 1\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eKhung t\u0026#234;n:\u003cbr\u003eT\u0026#234;n chi tiết, vật liệu, tỉ lệ.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eKhung t\u0026#234;n:\u003cbr\u003eT\u0026#234;n sản phẩm, tỉ lệ bản vẽ.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eKhung t\u0026#234;n:\u003cbr\u003eT\u0026#234;n ng\u0026#244;i nh\u0026#224;, tỉ lệ bản vẽ.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eBước 2\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eH\u0026#236;nh biểu diễn:\u003cbr\u003eT\u0026#234;n gọi c\u0026#225;c h\u0026#236;nh chiếu, h\u0026#236;nh cắt.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eBảng k\u0026#234;:\u003cbr\u003eT\u0026#234;n gọi chi tiết, số lượng, vật liệu.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eH\u0026#236;nh biểu diễn:\u003cbr\u003eT\u0026#234;n gọi h\u0026#236;nh biểu diễn (Mặt đứng, mặt bằng, mặt cắt).\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eBước 3\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eK\u0026#237;ch thước:\u003cbr\u003eK\u0026#237;ch thước chung, k\u0026#237;ch thước từng phần.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eH\u0026#236;nh biểu diễn:\u003cbr\u003eH\u0026#236;nh chiếu, h\u0026#236;nh cắt thể hiện kết cấu.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eK\u0026#237;ch thước:\u003cbr\u003eK\u0026#237;ch thước chung, k\u0026#237;ch thước từng bộ phận.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eBước 4\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eY\u0026#234;u cầu kỹ thuật:\u003cbr\u003eGia c\u0026#244;ng, xử l\u0026#253; bề mặt.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eK\u0026#237;ch thước:\u003cbr\u003eK\u0026#237;ch thước chung, k\u0026#237;ch thước lắp gh\u0026#233;p.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eC\u0026#225;c bộ phận ch\u0026#237;nh:\u003cbr\u003eSố ph\u0026#242;ng, số cửa đi, cửa sổ, chiều cao.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eBước 5\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003ePh\u0026#226;n t\u0026#237;ch: Vị tr\u0026#237; chi tiết.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eBước \u003c/strong\u003e\u003cstrong\u003e6\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eTổng hợp: Tr\u0026#236;nh tự th\u0026#225;o lắp.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003cp\u003e\u003cstrong\u003ePHẦN II: PH\u0026#194;N T\u0026#205;CH TRỌNG T\u0026#194;M ĐỀ THI HSG VĨNH LONG (B\u0026#192;I TẬP ĐỒ HỌA 3.0 ĐIỂM)\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eTr\u0026#237;ch ph\u0026#226;n t\u0026#237;ch C\u0026#226;u 3 trong Đề thi HSG ch\u0026#237;nh thức Sở GDĐT Vĩnh Long (3,0 điểm):\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e• Đề b\u0026#224;i mẫu: \u003c/strong\u003eCho vật thể c\u0026#243; dạng chữ L (hoặc khối c\u0026#243; bậc, r\u0026#227;nh, lỗ rỗng h\u0026#236;nh trụ) với c\u0026#225;c k\u0026#237;ch thước h\u0026#236;nh học cụ thể (v\u0026#237; dụ: chiều d\u0026#224;i tổng 80, chiều cao 70, chiều rộng 70; bậc dưới cao 20, v\u0026#225;t/s\u0026#226;u 50, r\u0026#227;nh rộng 30,...).\u003cbr\u003e\u003cstrong\u003e• Y\u0026#234;u cầu: \u003c/strong\u003eCăn cứ v\u0026#224;o th\u0026#244;ng tin m\u0026#244; h\u0026#236;nh 3D, h\u0026#227;y vẽ h\u0026#236;nh chiếu đứng, h\u0026#236;nh chiếu bằng, h\u0026#236;nh chiếu cạnh của vật thể tr\u0026#234;n theo tỉ lệ 1:2 đ\u0026#250;ng vị tr\u0026#237; quy định v\u0026#224; ghi k\u0026#237;ch thước cơ bản của vật thể tr\u0026#234;n c\u0026#225;c h\u0026#236;nh chiếu.\u003cbr\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e1. Quy tr\u0026#236;nh 6 bước vẽ 3 h\u0026#236;nh chiếu vu\u0026#244;ng g\u0026#243;c đạt điểm tối đa (3,0/3,0 điểm):\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e• Bước 1: Ph\u0026#226;n t\u0026#237;ch h\u0026#236;nh dạng vật thể. \u003c/strong\u003eX\u0026#225;c định vật thể được tạo th\u0026#224;nh từ c\u0026#225;c khối đa diện hay khối tr\u0026#242;n xoay n\u0026#224;o; nhận diện c\u0026#225;c chi tiết đặc biệt như bậc, v\u0026#225;t g\u0026#243;c, r\u0026#227;nh xẻ, lỗ trụ xuy\u0026#234;n suốt.\u003cbr\u003e\u003cstrong\u003e• Bước 2: Chọn hướng chiếu đứng. \u003c/strong\u003eChọn hướng chiếu từ trước sao cho h\u0026#236;nh chiếu đứng thể hiện r\u0026#245; nhất đặc điểm h\u0026#236;nh dạng đặc trưng của vật thể.\u003cbr\u003e\u003cstrong\u003e• Bước 3: T\u0026#237;nh to\u0026#225;n tỉ lệ v\u0026#224; k\u0026#237;ch thước vẽ. \u003c/strong\u003eNếu đề b\u0026#224;i y\u0026#234;u cầu tỉ lệ 1:2, h\u0026#227;y chia tất cả k\u0026#237;ch thước đo/đề cho 2 khi đặt thước vẽ n\u0026#233;t (V\u0026#237; dụ: 80 mm -\u0026gt; vẽ 40 mm; 70 mm -\u0026gt; vẽ 35 mm; 20 mm -\u0026gt; vẽ 10 mm). Nhưng khi GHI CHỮ SỐ K\u0026#205;CH THƯỚC vẫn ghi con số thực (80, 70, 20).\u003cbr\u003e\u003cstrong\u003e• Bước 4: Vẽ ph\u0026#225;c bằng n\u0026#233;t liền mảnh. \u003c/strong\u003eVẽ khung bao h\u0026#236;nh chiếu đứng -\u0026gt; gi\u0026#243;ng thẳng đứng xuống vẽ h\u0026#236;nh chiếu bằng -\u0026gt; gi\u0026#243;ng nằm ngang sang vẽ h\u0026#236;nh chiếu cạnh. Vẽ c\u0026#225;c n\u0026#233;t bao thấy, n\u0026#233;t khuất (n\u0026#233;t đứt mảnh) v\u0026#224; đường t\u0026#226;m (n\u0026#233;t gạch chấm mảnh).\u003cbr\u003e\u003cstrong\u003e• Bước 5: Kiểm tra gi\u0026#243;ng đối ứng v\u0026#224; t\u0026#244; đậm. \u003c/strong\u003eKiểm tra khớp chiều d\u0026#224;i (ĐỨNG - BẰNG), chiều cao (ĐỨNG - CẠNH), chiều rộng (BẰNG - CẠNH). Tẩy bỏ c\u0026#225;c đường gi\u0026#243;ng thừa, t\u0026#244; đậm n\u0026#233;t liền đậm cho tất cả c\u0026#225;c cạnh thấy v\u0026#224; đường bao thấy.\u003cbr\u003e\u003cstrong\u003e• Bước 6: Ghi k\u0026#237;ch thước v\u0026#224; ho\u0026#224;n thiện. \u003c/strong\u003eKẻ đường d\u0026#243;ng, đường k\u0026#237;ch thước n\u0026#233;t mảnh v\u0026#224; ghi trị số k\u0026#237;ch thước thực chuẩn x\u0026#225;c.\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003e★ C\u0026#193;C BẪY TRỪ ĐIỂM NGUY HẠI CẦN TR\u0026#193;NH TRONG B\u0026#192;I TẬP VẼ H\u0026#204;NH CHIẾU\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e\u003c/p\u003e\u003cp\u003eBẢNG B\u0026#193;O ĐỘNG C\u0026#193;C LỖI SAI KHIẾN HỌC SINH BỊ TRỪ ĐIỂM HSG (Căn cứ Đ\u0026#225;p \u0026#225;n Sở Vĩnh Long):\u003c/p\u003e\u003cp\u003e1. Sai vị tr\u0026#237; h\u0026#236;nh chiếu (-0,5đ đến -1,0đ): Đặt h\u0026#236;nh chiếu bằng nằm ngang h\u0026#224;ng với h\u0026#236;nh chiếu đứng, hoặc đổi chỗ h\u0026#236;nh chiếu cạnh sang tr\u0026#225;i.\u003c/p\u003e\u003cp\u003e2. Sai tỉ lệ vẽ (-0,25đ mỗi h\u0026#236;nh chiếu): Qu\u0026#234;n kh\u0026#244;ng chia tỉ lệ 1:2 khi đặt thước vẽ n\u0026#233;t dẫn đến h\u0026#236;nh chiếu bị ph\u0026#243;ng to gấp đ\u0026#244;i so với y\u0026#234;u cầu.\u003c/p\u003e\u003cp\u003e3. Sai chữ số k\u0026#237;ch thước (-0,25đ): Ghi k\u0026#237;ch thước đ\u0026#227; chia tỉ lệ (v\u0026#237; dụ ghi 40 thay v\u0026#236; ghi 80), hoặc ghi k\u0026#232;m đơn vị \u0026#39;mm\u0026#39; sau con số.\u003c/p\u003e\u003cp\u003e4. Nhầm lẫn quy chuẩn đường n\u0026#233;t (-0,25đ mỗi h\u0026#236;nh chiếu): Cạnh khuất b\u0026#234;n trong kh\u0026#244;ng vẽ n\u0026#233;t đứt mảnh m\u0026#224; vẽ n\u0026#233;t liền đậm, hoặc qu\u0026#234;n vẽ n\u0026#233;t gạch chấm mảnh cho đường t\u0026#226;m lỗ tr\u0026#242;n/trục đối xứng.\u003c/p\u003e\u003cp\u003e5. Kh\u0026#244;ng gi\u0026#243;ng đối ứng (-0,25đ): Chiều d\u0026#224;i tr\u0026#234;n h\u0026#236;nh chiếu đứng kh\u0026#244;ng khớp thẳng đứng với chiều d\u0026#224;i h\u0026#236;nh chiếu bằng.\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003cp\u003e\u003cstrong\u003ePHẦN III: NG\u0026#194;N H\u0026#192;NG B\u0026#192;I TẬP MẪU PH\u0026#194;N H\u0026#211;A 4 MỨC ĐỘ\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eMức độ 1: Nhận biết – Th\u0026#244;ng hiểu (L\u0026#253; thuyết Ti\u0026#234;u chuẩn \u0026amp; Ph\u0026#233;p chiếu)\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 1.1 (1,5 điểm): \u003c/strong\u003eTr\u0026#236;nh b\u0026#224;y c\u0026#225;c ti\u0026#234;u chuẩn về đường n\u0026#233;t trong bản vẽ kỹ thuật (t\u0026#234;n đường n\u0026#233;t, dạng n\u0026#233;t vẽ, chiều d\u0026#224;y, ứng dụng). Tại sao tr\u0026#234;n bản vẽ kỹ thuật phải ph\u0026#226;n biệt r\u0026#245; r\u0026#224;ng độ d\u0026#224;y v\u0026#224; dạng n\u0026#233;t vẽ giữa đường bao thấy v\u0026#224; đường bao khuất?\u003cbr\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 1.2 (1,5 điểm): \u003c/strong\u003eH\u0026#227;y cho biết vị tr\u0026#237; tương đối giữa người quan s\u0026#225;t, vật thể v\u0026#224; mặt phẳng chiếu trong phương ph\u0026#225;p chiếu g\u0026#243;c thứ nhất. So s\u0026#225;nh vị tr\u0026#237; của 3 h\u0026#236;nh chiếu (Đứng, Bằng, Cạnh) tr\u0026#234;n mặt phẳng bản vẽ sau khi đ\u0026#227; trải phẳng.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eMức độ 2: Vận dụng thấp (Ph\u0026#226;n t\u0026#237;ch h\u0026#236;nh chiếu khối đa diện \u0026amp; Khối tr\u0026#242;n xoay)\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 2.1 (2,0 điểm): \u003c/strong\u003eCho h\u0026#236;nh trụ đặt thẳng đứng c\u0026#243; đường k\u0026#237;nh đ\u0026#225;y d = 40 mm, chiều cao h = 60 mm. Nếu đặt h\u0026#236;nh trụ n\u0026#224;y sao cho trục của n\u0026#243; vu\u0026#244;ng g\u0026#243;c với mặt phẳng chiếu đứng:\u003cbr\u003ea) H\u0026#236;nh chiếu đứng, h\u0026#236;nh chiếu bằng v\u0026#224; h\u0026#236;nh chiếu cạnh c\u0026#243; h\u0026#236;nh dạng l\u0026#224; g\u0026#236;?\u003cbr\u003eb) N\u0026#234;u k\u0026#237;ch thước thể hiện tr\u0026#234;n từng h\u0026#236;nh chiếu.\u003cbr\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 2.2 (2,0 điểm): \u003c/strong\u003eTr\u0026#236;nh b\u0026#224;y tr\u0026#236;nh tự đọc bản vẽ chi tiết Gối đỡ (hoặc Tấm đế). H\u0026#227;y giải th\u0026#237;ch \u0026#253; nghĩa của c\u0026#225;c nội dung ghi trong Khung t\u0026#234;n v\u0026#224; Y\u0026#234;u cầu kỹ thuật tr\u0026#234;n bản vẽ chi tiết.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eMức độ 3: Vận dụng cao (B\u0026#224;i tập Đồ họa Dựng 3 H\u0026#236;nh chiếu theo Tỉ lệ – Dạng thi HSG Vĩnh Long)\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 3.1 (3,0 điểm – Đề xuất chuẩn đề thi HSG): \u003c/strong\u003eCho vật thể g\u0026#225; chạc c\u0026#243; m\u0026#244; h\u0026#236;nh 3D với c\u0026#225;c k\u0026#237;ch thước như sau:\u003cbr\u003e• Khối đế h\u0026#236;nh hộp chữ nhật k\u0026#237;ch thước tổng: Chiều d\u0026#224;i L = 90 mm, Chiều rộng W = 60 mm, Chiều cao tổng H = 50 mm.\u003cbr\u003e• Ở ch\u0026#237;nh giữa phần bậc tr\u0026#234;n c\u0026#243; một r\u0026#227;nh h\u0026#236;nh chữ nhật xuy\u0026#234;n suốt theo chiều d\u0026#224;i với chiều rộng r\u0026#227;nh b = 30 mm, chiều s\u0026#226;u r\u0026#227;nh h1 = 20 mm.\u003cbr\u003e• Ở hai b\u0026#234;n khối đế c\u0026#243; hai lỗ trụ tr\u0026#242;n xuy\u0026#234;n suốt từ tr\u0026#234;n xuống dưới với đường k\u0026#237;nh d = 16 mm, khoảng c\u0026#225;ch giữa t\u0026#226;m hai lỗ l\u0026#224; 60 mm.\u003cbr\u003eCăn cứ v\u0026#224;o c\u0026#225;c th\u0026#244;ng tin k\u0026#237;ch thước tr\u0026#234;n, em h\u0026#227;y:\u003cbr\u003ea) T\u0026#237;nh to\u0026#225;n k\u0026#237;ch thước n\u0026#233;t vẽ khi thể hiện bản vẽ theo tỉ lệ 1:2.\u003cbr\u003eb) Vẽ h\u0026#236;nh chiếu đứng, h\u0026#236;nh chiếu bằng, h\u0026#236;nh chiếu cạnh của vật thể đ\u0026#250;ng vị tr\u0026#237; v\u0026#224; gi\u0026#243;ng đối ứng chuẩn x\u0026#225;c theo phương ph\u0026#225;p chiếu g\u0026#243;c thứ nhất.\u003cbr\u003ec) Ghi c\u0026#225;c k\u0026#237;ch thước cơ bản tr\u0026#234;n 3 h\u0026#236;nh chiếu theo đ\u0026#250;ng quy chuẩn TCVN.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eMức độ 4: T\u0026#236;nh huống thực tiễn \u0026amp; Ph\u0026#225;t hiện lỗi sai tr\u0026#234;n Bản vẽ Kỹ thuật\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 4.1 (2,5 điểm): \u003c/strong\u003eMột học sinh thực hiện b\u0026#224;i thi HSG vẽ 3 h\u0026#236;nh chiếu của một vật thể kim loại c\u0026#243; lỗ rỗng b\u0026#234;n trong. Học sinh đ\u0026#243; mắc c\u0026#225;c lỗi sau tr\u0026#234;n bản vẽ:\u003cbr\u003e1. Đặt h\u0026#236;nh chiếu bằng ở b\u0026#234;n phải h\u0026#236;nh chiếu đứng.\u003cbr\u003e2. C\u0026#225;c đường bao khuất b\u0026#234;n trong lỗ rỗng được vẽ bằng n\u0026#233;t liền mảnh.\u003cbr\u003e3. Ghi k\u0026#237;ch thước \u0026#216;20 th\u0026#224;nh \u0026#216;10 v\u0026#236; vẽ theo tỉ lệ thu nhỏ 1:2.\u003cbr\u003e4. Đường d\u0026#243;ng k\u0026#237;ch thước cắt ngang qua chữ số k\u0026#237;ch thước.\u003cbr\u003eEm h\u0026#227;y ph\u0026#226;n t\u0026#237;ch t\u0026#225;c hại của từng lỗi sai tr\u0026#234;n đối với qu\u0026#225; tr\u0026#236;nh đọc bản vẽ v\u0026#224; gia c\u0026#244;ng sản xuất thực tế tại xưởng cơ kh\u0026#237;, từ đ\u0026#243; đề xuất c\u0026#225;ch sửa lại cho đ\u0026#250;ng quy chuẩn.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003ePHẦN IV: Đ\u0026#193;P \u0026#193;N V\u0026#192; HƯỚNG DẪN CHẤM CHI TIẾT\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eĐ\u0026#193;P \u0026#193;N C\u0026#194;U 1.1 (1,5 điểm):\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e• Tr\u0026#236;nh b\u0026#224;y đ\u0026#250;ng 4 loại đường n\u0026#233;t quy chuẩn (0,75đ):\u003cbr\u003e  + N\u0026#233;t liền đậm (s ≈ 0,5 - 0,7 mm): Vẽ đường bao thấy, cạnh thấy (0,25đ).\u003cbr\u003e  + N\u0026#233;t đứt mảnh (s/2): Vẽ đường bao khuất, cạnh khuất (0,20đ).\u003cbr\u003e  + N\u0026#233;t liền mảnh (s/2): Vẽ đường d\u0026#243;ng, đường k\u0026#237;ch thước (0,15đ).\u003cbr\u003e  + N\u0026#233;t gạch chấm mảnh (s/2): Vẽ đường t\u0026#226;m, trục đối xứng (0,15đ).\u003cbr\u003e• Giải th\u0026#237;ch bản chất (0,75đ): Ph\u0026#226;n biệt r\u0026#245; n\u0026#233;t đậm v\u0026#224; n\u0026#233;t mảnh gi\u0026#250;p người thợ cơ kh\u0026#237; khi nh\u0026#236;n v\u0026#224;o bản vẽ lập tức nhận biết được bề mặt nổi/cạnh nh\u0026#236;n thấy b\u0026#234;n ngo\u0026#224;i so với c\u0026#225;c chi tiết bị che khuất b\u0026#234;n trong, tr\u0026#225;nh nhầm lẫn nguy hiểm khi gia c\u0026#244;ng cắt gọt kim loại.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eHƯỚNG DẪN CHẤM C\u0026#194;U 3.1 - B\u0026#192;I TẬP ĐỒ HỌA 3.0 ĐIỂM (Chuẩn Sở GDĐT Vĩnh Long):\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eHạng mục chấm\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eY\u0026#234;u cầu kỹ thuật \u0026amp; Nội dung thể hiện chi tiết\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eĐiểm chuẩn\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eT\u0026#237;nh tỉ lệ 1:2\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eT\u0026#237;nh to\u0026#225;n đ\u0026#250;ng k\u0026#237;ch thước n\u0026#233;t vẽ: D\u0026#224;i = 45 mm, rộng = 30 mm, cao = 25 mm, R\u0026#227;nh rộng 15 mm, s\u0026#226;u 10 mm, Lỗ \u0026#216;8 mm.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e0,25đ\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eH\u0026#236;nh chiếu đứng\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eVẽ đ\u0026#250;ng dạng h\u0026#236;nh chữ nhật bao ngo\u0026#224;i 45x25 mm, thể hiện r\u0026#227;nh h\u0026#236;nh chữ nhật n\u0026#233;t liền đậm, hai đường n\u0026#233;t đứt mảnh thể hiện 2 lỗ trụ tr\u0026#242;n.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e0,75đ\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eH\u0026#236;nh chiếu bằng\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eVẽ đ\u0026#250;ng dạng h\u0026#236;nh chữ nhật 45x30 mm nằm NGAY DƯỚI h\u0026#236;nh chiếu đứng, thể hiện 2 đường tr\u0026#242;n \u0026#216;8 n\u0026#233;t liền đậm + đường t\u0026#226;m gạch chấm mảnh, r\u0026#227;nh xẻ n\u0026#233;t liền đậm.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e0,75đ\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eH\u0026#236;nh chiếu cạnh\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eVẽ đ\u0026#250;ng dạng h\u0026#236;nh chữ nhật 30x25 mm nằm NGAY B\u0026#202;N PHẢI h\u0026#236;nh chiếu đứng, thể hiện r\u0026#227;nh n\u0026#233;t đứt mảnh/liền đậm đ\u0026#250;ng hướng nh\u0026#236;n, đường bao lỗ rỗng.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e0,50đ\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eBố tr\u0026#237; \u0026amp; Gi\u0026#243;ng\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eĐặt đ\u0026#250;ng vị tr\u0026#237; 3 h\u0026#236;nh chiếu (Phương ph\u0026#225;p g\u0026#243;c chiếu I), c\u0026#225;c đường gi\u0026#243;ng dọc v\u0026#224; gi\u0026#243;ng ngang thẳng h\u0026#224;ng ho\u0026#224;n to\u0026#224;n kh\u0026#244;ng lệch.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e0,40đ\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eGhi k\u0026#237;ch thước\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eGhi đầy đủ c\u0026#225;c k\u0026#237;ch thước cơ bản L90, W60, H50, r\u0026#227;nh b30, h20, lỗ \u0026#216;16 đ\u0026#250;ng quy chuẩn TCVN (chữ số nghi\u0026#234;ng/đứng đ\u0026#250;ng hướng).\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e0,35đ\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e","5":"\u003ch2\u003eCHUYÊN ĐỀ 5: CƠ KHÍ \u0026 TRUYỀN – BIẾN ĐỔI CHUYỂN ĐỘNG(Trọng tâm Công nghệ 8 – Bám sát Công văn 730/SGDĐT-GDPT \u0026 Cấu trúc Đề thi HSG Vĩnh Long)\u003c/h2\u003e\u003ch2\u003ePHẦN 1: DANH MỤC TRỌNG TÂM \u0026 MA TRẬN YÊU CẦU NĂNG LỰC\u003c/h2\u003e\u003ch2\u003eChuyên đề 5 chiếm vị trí cốt lõi trong phần Công nghệ Kỹ thuật lớp 8 với bài tập tự luận Câu 4 (3,0 điểm - chiếm 15% tổng số điểm toàn đề thi). Yêu cầu không chỉ dừng lại ở việc học thuộc công thức tính tỉ số truyền i mà phải hiểu sâu bản chất động học, cơ chế ăn khớp vs ma sát, mối quan hệ giữa tốc độ quay - đường kính/số răng - mô-men xoắn và lập luận phân tích nguy cơ mất an toàn vận hành cơ khí.\u003c/h2\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eNội dung trọng t\u0026#226;m\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eMức độ đ\u0026#225;nh gi\u0026#225;\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eDạng c\u0026#226;u hỏi thi HSG nguồn\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eThang điểm\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eVật liệu cơ kh\u0026#237; \u0026amp; Dụng cụ gia c\u0026#244;ng cầm tay\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eNhận biết - Th\u0026#244;ng hiểu\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003ePh\u0026#226;n loại vật liệu; N\u0026#234;u đặc t\u0026#237;nh \u0026amp; ứng dụng; Quy tắc an to\u0026#224;n đục, dũa, cưa\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e0,5 - 0,75đ\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eCấu tạo \u0026amp; Nguy\u0026#234;n l\u0026#253; bộ truyền động/biến đổi chuyển động\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eTh\u0026#244;ng hiểu - Vận dụng\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eSo s\u0026#225;nh truyền động đai vs b\u0026#225;nh răng/x\u0026#237;ch; Biến đổi tay quay con trượt\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e0,75 - 1,0đ\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eB\u0026#224;i tập t\u0026#237;nh to\u0026#225;n tỉ số truyền i \u0026amp; Tốc độ quay n2\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eVận dụng cao\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eT\u0026#237;nh to\u0026#225;n i, n2, Z2, D2; X\u0026#225;c định chiều quay; Ph\u0026#226;n t\u0026#237;ch hệ thống truyền động\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e1,0 - 1,25đ\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eLập luận an to\u0026#224;n \u0026amp; Nguy cơ mất an to\u0026#224;n cơ kh\u0026#237;\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eVận dụng cao\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003ePh\u0026#226;n t\u0026#237;ch nguy\u0026#234;n nh\u0026#226;n sự cố cuốn kẹt; Đề xuất giải ph\u0026#225;p an to\u0026#224;n vận h\u0026#224;nh\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e0,5đ\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003ch2\u003ePHẦN 2: LÝ THUYẾT CHUYÊN SÂU \u0026 BẢN CHẤT KĨ THUẬT\u003c/h2\u003e\u003ch3\u003e1. Vật liệu cơ khí và Dụng cụ gia công cơ khí cầm tay\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003ea) Ph\u0026#226;n loại v\u0026#224; Đặc t\u0026#237;nh Vật liệu Cơ kh\u0026#237;:\u003c/strong\u003e\u003c/p\u003e\u003cp\u003eVật liệu cơ kh\u0026#237; được chia th\u0026#224;nh 2 nh\u0026#243;m lớn: Vật liệu kim loại (Kim loại đen v\u0026#224; Kim loại m\u0026#224;u) v\u0026#224; Vật liệu phi kim.\u003cbr\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eKim loại đen: \u003c/strong\u003eTh\u0026#224;nh phần ch\u0026#237;nh l\u0026#224; sắt (Fe) v\u0026#224; carbon (C). Chia th\u0026#224;nh Th\u0026#233;p (tỉ lệ C ≤ 2,14%) v\u0026#224; Gang (tỉ lệ C \u0026gt; 2,14%). Th\u0026#233;p c\u0026#243; độ dẻo, độ bền cao, dễ gia c\u0026#244;ng, d\u0026#249;ng l\u0026#224;m khung xe, m\u0026#225;y m\u0026#243;c, c\u0026#244;ng cụ. Gang d\u0026#242;n hơn, chịu n\u0026#233;n tốt, d\u0026#249;ng l\u0026#224;m th\u0026#226;n m\u0026#225;y, vỏ động cơ.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eKim loại m\u0026#224;u: \u003c/strong\u003eKh\u0026#244;ng chứa sắt hoặc chứa rất \u0026#237;t (Đồng, Nh\u0026#244;m v\u0026#224; hợp kim của ch\u0026#250;ng). Ưu điểm: Dẫn điện, dẫn nhiệt tốt, chống ăn m\u0026#242;n cao, nhẹ. D\u0026#249;ng l\u0026#224;m d\u0026#226;y dẫn điện, l\u0026#245;i tản nhiệt, vỏ m\u0026#225;y bay, chi tiết m\u0026#225;y chịu ăn m\u0026#242;n.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eVật liệu phi kim: \u003c/strong\u003eGồm Chất dẻo (Chất dẻo nhiệt v\u0026#224; Chất dẻo nhiệt rắn) v\u0026#224; Cao su. Ưu điểm: Dẫn điện/nhiệt k\u0026#233;m (c\u0026#225;ch điện/nhiệt tốt), nhẹ, kh\u0026#244;ng bị gỉ s\u0026#233;t. D\u0026#249;ng l\u0026#224;m vỏ d\u0026#226;y điện, tay cầm dụng cụ, lốp xe, đệm giảm chấn.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eb) Dụng cụ gia c\u0026#244;ng cầm tay v\u0026#224; Quy tắc An to\u0026#224;n:\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e• Dụng cụ đo v\u0026#224; kiểm tra: \u003c/strong\u003eThước l\u0026#225;, thước cuộn, thước kẹp (đo k\u0026#237;ch thước ngo\u0026#224;i, k\u0026#237;ch thước trong, chiều s\u0026#226;u lỗ với độ ch\u0026#237;nh x\u0026#225;c cao 0,1 - 0,02 mm).\u003cbr\u003e\u003cstrong\u003e• Dụng cụ th\u0026#225;o lắp v\u0026#224; kẹp chặt: \u003c/strong\u003eMỏ lết, cờ l\u0026#234;, tua v\u0026#237;t, \u0026#234;-t\u0026#244;, k\u0026#236;m.\u003cbr\u003e\u003cstrong\u003e• Dụng cụ gia c\u0026#244;ng: \u003c/strong\u003eCưa tay (cắt kim loại), dũa (l\u0026#224;m nhẵn bề mặt), đục (chặt kim loại), b\u0026#250;a.\u003cbr\u003e\u003cstrong\u003e• Quy tắc an to\u0026#224;n gia c\u0026#244;ng: \u003c/strong\u003eTrang bị bảo hộ lao động (k\u0026#237;nh bảo hộ, găng tay); kẹp chặt ph\u0026#244;i tr\u0026#234;n \u0026#234;-t\u0026#244; trước khi cưa/dũa; kh\u0026#244;ng d\u0026#249;ng cưa/dũa kh\u0026#244;ng c\u0026#243; c\u0026#225;n hoặc c\u0026#225;n bị nứt; khi cưa gần đứt phải giảm lực b\u0026#243;p v\u0026#224; đỡ ph\u0026#244;i để tr\u0026#225;nh rơi v\u0026#224;o ch\u0026#226;n.\u003c/p\u003e\u003ch3\u003e2. Cấu tạo, Nguyên lý và Phân loại các Bộ truyền động Cơ khí\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003eTại sao cần truyền động cơ kh\u0026#237;? \u003c/strong\u003eTrong m\u0026#225;y m\u0026#243;c, động cơ thường quay với tốc độ cố định v\u0026#224; đặt ở vị tr\u0026#237; nhất định, trong khi c\u0026#225;c bộ phận c\u0026#244;ng t\u0026#225;c cần tốc độ kh\u0026#225;c nhau, chiều quay kh\u0026#225;c nhau hoặc nằm xa động cơ. Do đ\u0026#243;, cần c\u0026#243; c\u0026#225;c bộ truyền động để truyền năng lượng v\u0026#224; biến đổi tốc độ/chiều quay.\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eBộ truyền động\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eCấu tạo \u0026amp; Yếu tố li\u0026#234;n kết\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eNguy\u0026#234;n l\u0026#253; hoạt động\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eƯu - Nhược điểm \u0026amp; Ứng dụng\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eTruyền động đai\u003cbr\u003e(Ma s\u0026#225;t)\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eGồm b\u0026#225;nh dẫn (D1), b\u0026#225;nh bị dẫn (D2) v\u0026#224; d\u0026#226;y đai \u0026#244;m quanh 2 b\u0026#225;nh.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eDựa v\u0026#224;o ma s\u0026#225;t giữa d\u0026#226;y đai v\u0026#224; bề mặt b\u0026#225;nh đai. B\u0026#225;nh dẫn quay k\u0026#233;o d\u0026#226;y đai chuyển động, l\u0026#224;m b\u0026#225;nh bị dẫn quay.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eƯu: Ếm \u0026#225;i, chạy an to\u0026#224;n khi qu\u0026#225; tải (đai trượt). Nhược: Dễ trượt, tỉ số truyền i kh\u0026#244;ng ch\u0026#237;nh x\u0026#225;c tuyệt đối. Ứng dụng: Quạt gi\u0026#243;, m\u0026#225;y may, m\u0026#225;y bơm.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eTruyền động b\u0026#225;nh răng\u003cbr\u003e(Ăn khớp)\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eGồm b\u0026#225;nh răng dẫn (Z1) v\u0026#224; b\u0026#225;nh răng bị dẫn (Z2) ăn khớp trực tiếp.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eDựa v\u0026#224;o sự ăn khớp trực tiếp giữa c\u0026#225;c răng. Răng b\u0026#225;nh dẫn đẩy răng b\u0026#225;nh bị dẫn quay (2 b\u0026#225;nh quay ngược chiều).\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eƯu: Tỉ số truyền i ch\u0026#237;nh x\u0026#225;c tuyệt đối, chịu tải lớn, k\u0026#237;ch thước nhỏ gọn. Nhược: Đ\u0026#242;i hỏi gia c\u0026#244;ng ch\u0026#237;nh x\u0026#225;c, g\u0026#226;y ồn khi quay nhanh. Ứng dụng: Đồng hồ, hộp số \u0026#244; t\u0026#244;, xe m\u0026#225;y.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eTruyền động x\u0026#237;ch\u003cbr\u003e(Ăn khớp)\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eGồm đĩa x\u0026#237;ch dẫn (Z1), đĩa x\u0026#237;ch bị dẫn (Z2) v\u0026#224; x\u0026#237;ch \u0026#244;m qua 2 đĩa.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eDựa v\u0026#224;o sự ăn khớp giữa mắt x\u0026#237;ch với c\u0026#225;c răng của đĩa x\u0026#237;ch khi đĩa dẫn quay.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eƯu: Tỉ số truyền i ch\u0026#237;nh x\u0026#225;c, truyền được khoảng c\u0026#225;ch xa hơn b\u0026#225;nh răng, kh\u0026#244;ng bị trượt. Nhược: G\u0026#226;y tiếng ồn, cần b\u0026#244;i trơn thường xuy\u0026#234;n. Ứng dụng: Xe đạp, xe m\u0026#225;y, băng tải.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003ch3\u003e3. Bản chất Động học \u0026 Hệ thống Công thức Tính toán Tỉ số truyền (i)\u003c/h3\u003e\u003cp\u003eTỉ số truyền i l\u0026#224; đại lượng đặc trưng cho sự biến đổi tốc độ quay giữa trục dẫn (trục 1) v\u0026#224; trục bị dẫn (trục 2).\u003cbr\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e1) C\u0026#244;ng thức tổng qu\u0026#225;t cho Truyền động Đai (theo Đường k\u0026#237;nh D):\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e\u003cstrong\u003e    i = n₁ / n₂ = D₂ / D₁  ⇒  n₂ = n₁ \u0026#215; (D₁ / D₂)\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e   Trong đ\u0026#243;: n₁, n₂ l\u0026#224; tốc độ quay của b\u0026#225;nh dẫn v\u0026#224; b\u0026#225;nh bị dẫn (v\u0026#242;ng/ph\u0026#250;t hay rpm).\u003cbr\u003e             D₁, D₂ l\u0026#224; đường k\u0026#237;nh của b\u0026#225;nh đai dẫn v\u0026#224; b\u0026#225;nh đai bị dẫn (mm hoặc cm).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e2) C\u0026#244;ng thức tổng qu\u0026#225;t cho Truyền động B\u0026#225;nh răng / X\u0026#237;ch (theo Số răng Z):\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e\u003cstrong\u003e    i = n₁ / n₂ = Z₂ / Z₁  ⇒  n₂ = n₁ \u0026#215; (Z₁ / Z₂)\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e   Trong đ\u0026#243;: Z₁, Z₂ l\u0026#224; số răng của b\u0026#225;nh/đĩa x\u0026#237;ch dẫn v\u0026#224; b\u0026#225;nh/đĩa x\u0026#237;ch bị dẫn.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e★ QUY TẮC PH\u0026#194;N T\u0026#205;CH TỈ SỐ TRUYỀN (LẬP LUẬN HSG):\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eKhi i \u0026gt; 1 (D₁ \u0026lt; D₂ hoặc Z₁ \u0026lt; Z₂): \u003c/strong\u003eTốc độ quay bị giảm (n₂ \u0026lt; n₁) ⇒ Đ\u0026#226;y l\u0026#224; bộ truyền GIẢM TỐC. B\u0026#225;nh bị dẫn quay chậm hơn b\u0026#225;nh dẫn, nhưng lực quay (m\u0026#244;-men xoắn) tại trục bị dẫn TĂNG L\u0026#202;N.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eKhi i \u0026lt; 1 (D₁ \u0026gt; D₂ hoặc Z₁ \u0026gt; Z₂): \u003c/strong\u003eTốc độ quay được tăng (n₂ \u0026gt; n₁) ⇒ Đ\u0026#226;y l\u0026#224; bộ truyền TĂNG TỐC. B\u0026#225;nh bị dẫn quay nhanh hơn b\u0026#225;nh dẫn, nhưng m\u0026#244;-men xoắn bị giảm.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eKhi i = 1 (D₁ = D₂ hoặc Z₁ = Z₂): \u003c/strong\u003eTruyền nguy\u0026#234;n vẹn tốc độ quay (n₂ = n₁).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eChiều quay: \u003c/strong\u003eTruyền động đai đai thẳng v\u0026#224; truyền động x\u0026#237;ch th\u0026#236; 2 b\u0026#225;nh quay C\u0026#217;NG CHIỀU. Truyền động b\u0026#225;nh răng ăn khớp ngo\u0026#224;i th\u0026#236; 2 b\u0026#225;nh quay NGƯỢC CHIỀU nhau.\u003c/p\u003e\u003ch3\u003e4. Cơ cấu Biến đổi Chuyển động (Tay quay - Con trượt, Tay quay - Thanh lắc)\u003c/h3\u003e\u003cp\u003eNgo\u0026#224;i việc truyền v\u0026#224; biến đổi tốc độ quay, trong m\u0026#225;y m\u0026#243;c c\u0026#242;n cần biến đổi dạng chuyển động (từ chuyển động quay th\u0026#224;nh tịnh tiến hoặc lắc).\u003cbr\u003e\u003cstrong\u003e• Cơ cấu Tay quay - Con trượt: \u003c/strong\u003eCấu tạo gồm Tay quay (1), Thanh truyền (2), Con trượt (3) v\u0026#224; Gi\u0026#225; đỡ (4). Nguy\u0026#234;n l\u0026#253;: Khi tay quay (1) quay quanh trục, th\u0026#244;ng qua thanh truyền (2) l\u0026#224;m con trượt (3) chuyển động tịnh tiến qua lại tr\u0026#234;n gi\u0026#225; đỡ. Ứng dụng: Động cơ đốt trong (p\u0026#237;t-t\u0026#244;ng tịnh tiến l\u0026#224;m trục khuỷu quay), m\u0026#225;y may, m\u0026#225;y \u0026#233;p.\u003cbr\u003e\u003cstrong\u003e• Cơ cấu Tay quay - Thanh lắc: \u003c/strong\u003eCấu tạo gồm Tay quay, Thanh truyền, Thanh lắc v\u0026#224; Gi\u0026#225; đỡ. Nguy\u0026#234;n l\u0026#253;: Khi tay quay quay tr\u0026#242;n, thanh lắc chuyển động lắc qua lắc lại một g\u0026#243;c nhất định. Ứng dụng: Quạt m\u0026#225;y đảo chiều, m\u0026#225;y may ch\u0026#226;n.\u003c/p\u003e\u003ch3\u003e5. Lập luận Phân tích Nguy cơ Mất An toàn Cơ khí \u0026 Biện pháp Kỹ thuật\u003c/h3\u003e\u003cp\u003eTrong đề thi HSG, c\u0026#226;u hỏi ph\u0026#226;n ho\u0026#225; thường y\u0026#234;u cầu học sinh vạch r\u0026#245; nguy cơ mất an to\u0026#224;n khi vận h\u0026#224;nh thiết bị cơ kh\u0026#237;. Cần lập luận theo 3 điểm cốt l\u0026#245;i sau:\u003cbr\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eNguy cơ cuốn kẹt: \u003c/strong\u003eC\u0026#225;c v\u0026#249;ng tiếp x\u0026#250;c giữa d\u0026#226;y đai - b\u0026#225;nh đai, răng ăn khớp, đĩa x\u0026#237;ch - mắt x\u0026#237;ch c\u0026#243; lực kẹt rất lớn. Nếu người vận h\u0026#224;nh để t\u0026#243;c d\u0026#224;i, quần \u0026#225;o rộng, găng tay bị cuốn v\u0026#224;o sẽ g\u0026#226;y tai nạn kẹp dập nghi\u0026#234;m trọng.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eNguy cơ văng bắn \u0026amp; Ma s\u0026#225;t nhiệt: \u003c/strong\u003eC\u0026#225;c chi tiết quay với tốc độ cao c\u0026#243; thể bị văng bắn dầu mỡ, mảnh vỡ khi sự cố. Bề mặt c\u0026#225;c bộ truyền động t\u0026#237;ch tụ nhiệt do ma s\u0026#225;t c\u0026#243; thể g\u0026#226;y bỏng.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eBiện ph\u0026#225;p bảo vệ kỹ thuật bắt buộc: \u003c/strong\u003e(1) Bắt buộc lắp đai chắn/hộp bảo vệ che k\u0026#237;n ho\u0026#224;n to\u0026#224;n bộ truyền động; (2) Ngắt ho\u0026#224;n to\u0026#224;n nguồn điện v\u0026#224; chờ m\u0026#225;y dừng hẳn trước khi kiểm tra, tra dầu mỡ; (3) T\u0026#243;c gọn g\u0026#224;ng, mặc bảo hộ lao động vừa vặn, kh\u0026#244;ng đeo trang sức khi vận h\u0026#224;nh.\u003c/p\u003e\u003ch2\u003ePHẦN 3: PHƯƠNG PHÁP GIẢI BÀI TẬP TÍNH TOÁN \u0026 ĐỘNG HỌC CƠ KHÍ\u003c/h2\u003e\u003cp\u003eĐể đạt điểm tối đa (3,0 điểm) b\u0026#224;i tập Cơ kh\u0026#237; trong đề thi HSG Vĩnh Long, học sinh cần tr\u0026#236;nh b\u0026#224;y theo đ\u0026#250;ng \u003cstrong\u003eQuy tr\u0026#236;nh 4 bước chuẩn mực:\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e• Bước 1: T\u0026#243;m tắt đề b\u0026#224;i \u003c/strong\u003e(Ghi r\u0026#245; c\u0026#225;c đại lượng đ\u0026#227; biết: n₁, D₁, D₂, Z₁, Z₂; x\u0026#225;c định đại lượng cần t\u0026#237;nh: i, n₂, Z₂, D₂). Lưu \u0026#253; đổi c\u0026#249;ng đơn vị đo (mm hoặc cm).\u003cbr\u003e\u003cstrong\u003e• Bước 2: Viết c\u0026#244;ng thức gốc \u003c/strong\u003e(N\u0026#234;u r\u0026#245; c\u0026#244;ng thức i = n₁/n₂ = D₂/D₁ hoặc i = n₁/n₂ = Z₂/Z₁).\u003cbr\u003e\u003cstrong\u003e• Bước 3: R\u0026#250;t ra đại lượng cần t\u0026#236;m v\u0026#224; Thay số \u003c/strong\u003e(Viết biểu thức đại số r\u0026#245; r\u0026#224;ng trước khi thế số, t\u0026#237;nh to\u0026#225;n ra đ\u0026#225;p số k\u0026#232;m đơn vị chuẩn v\u0026#242;ng/ph\u0026#250;t hoặc rpm).\u003cbr\u003e\u003cstrong\u003e• Bước 4: Nhận x\u0026#233;t bản chất động học v\u0026#224; Lập luận \u003c/strong\u003e(So s\u0026#225;nh n₂ với n₁, kết luận bộ truyền tăng tốc hay giảm tốc; nhận x\u0026#233;t chiều quay; lập luận an to\u0026#224;n kỹ thuật).\u003c/p\u003e\u003ch2\u003ePHẦN 4: NGÂN HÀNG CÂU HỎI \u0026 BÀI TẬP PHÂN HÓA HSG (4 MỨC ĐỘ)\u003c/h2\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 1 (Mức 1: Nhận biết - Th\u0026#244;ng hiểu - 1,5 điểm):\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003ea) So s\u0026#225;nh sự giống v\u0026#224; kh\u0026#225;c nhau giữa bộ truyền động đai v\u0026#224; bộ truyền động x\u0026#237;ch về cấu tạo, nguy\u0026#234;n l\u0026#253; l\u0026#224;m việc v\u0026#224; phạm vi ứng dụng.\u003cbr\u003eb) Tại sao trong c\u0026#225;c m\u0026#225;y m\u0026#243;c chịu tải lớn, đ\u0026#242;i hỏi tỉ số truyền ch\u0026#237;nh x\u0026#225;c tuyệt đối (như đồng hồ, hộp số \u0026#244; t\u0026#244;) người ta lại d\u0026#249;ng truyền động b\u0026#225;nh răng m\u0026#224; kh\u0026#244;ng d\u0026#249;ng truyền động đai?\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 2 (Mức 2: Vận dụng b\u0026#224;i tập t\u0026#237;nh to\u0026#225;n chuẩn Đề thi nguồn Vĩnh Long - 3,0 điểm):\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003eMột bộ truyền động b\u0026#225;nh răng gồm b\u0026#225;nh răng dẫn 1 c\u0026#243; số răng Z₁ = 20 răng quay với tốc độ n₁ = 120 v\u0026#242;ng/ph\u0026#250;t. B\u0026#225;nh răng bị dẫn 2 c\u0026#243; số răng Z₂ = 60 răng.\u003cbr\u003ea) T\u0026#237;nh tỉ số truyền i của bộ truyền động b\u0026#225;nh răng tr\u0026#234;n.\u003cbr\u003eb) T\u0026#237;nh tốc độ quay n₂ của b\u0026#225;nh răng bị dẫn 2. Cho biết b\u0026#225;nh răng bị dẫn quay nhanh hơn hay chậm hơn b\u0026#225;nh răng dẫn mấy lần? Đ\u0026#226;y l\u0026#224; bộ truyền tăng tốc hay giảm tốc?\u003cbr\u003ec) X\u0026#225;c định chiều quay của b\u0026#225;nh răng bị dẫn 2 so với b\u0026#225;nh răng dẫn 1.\u003cbr\u003ed) Chỉ ra c\u0026#225;c nguy cơ mất an to\u0026#224;n khi vận h\u0026#224;nh bộ truyền động b\u0026#225;nh răng n\u0026#224;y v\u0026#224; đề xuất giải ph\u0026#225;p bảo vệ kỹ thuật.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 3 (Mức 3: Vận dụng cao b\u0026#224;i tập hệ thống truyền động đai - 2,5 điểm):\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003eĐộng cơ điện của một m\u0026#225;y may quay với tốc độ n₁ = 1400 v\u0026#242;ng/ph\u0026#250;t, b\u0026#225;nh đai gắn tr\u0026#234;n trục động cơ (b\u0026#225;nh dẫn 1) c\u0026#243; đường k\u0026#237;nh D₁ = 80 mm. B\u0026#225;nh đai gắn tr\u0026#234;n trục m\u0026#225;y may (b\u0026#225;nh bị dẫn 2) c\u0026#243; đường k\u0026#237;nh D₂ = 280 mm.\u003cbr\u003ea) T\u0026#237;nh tỉ số truyền i v\u0026#224; tốc độ quay n₂ của trục m\u0026#225;y may.\u003cbr\u003eb) Nếu muốn tăng tốc độ quay của m\u0026#225;y may l\u0026#234;n n₂\u0026#39; = 700 v\u0026#242;ng/ph\u0026#250;t m\u0026#224; vẫn giữ nguy\u0026#234;n đường k\u0026#237;nh b\u0026#225;nh dẫn D₁ = 80 mm v\u0026#224; tốc độ động cơ n₁ = 1400 v\u0026#242;ng/ph\u0026#250;t th\u0026#236; cần thay b\u0026#225;nh đai bị dẫn c\u0026#243; đường k\u0026#237;nh D₂\u0026#39; bằng bao nhi\u0026#234;u mm?\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 4 (Mức 4: T\u0026#236;nh huống thực tiễn \u0026amp; Lập luận kỹ thuật - 2,0 điểm):\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003eTrong một xưởng cơ kh\u0026#237;, một c\u0026#244;ng nh\u0026#226;n vận h\u0026#224;nh m\u0026#225;y cưa x\u0026#237;ch th\u0026#225;o bỏ hộp bảo vệ che đĩa x\u0026#237;ch để \u0026#39;dễ quan s\u0026#225;t v\u0026#224; thay x\u0026#237;ch nhanh hơn\u0026#39;. H\u0026#227;y d\u0026#249;ng kiến thức an to\u0026#224;n lao động v\u0026#224; nguy\u0026#234;n l\u0026#253; cơ kh\u0026#237; để ph\u0026#226;n t\u0026#237;ch h\u0026#224;nh vi tr\u0026#234;n, n\u0026#234;u r\u0026#245; c\u0026#225;c rủi ro nguy hiểm c\u0026#243; thể xảy ra v\u0026#224; đề xuất quy tắc an to\u0026#224;n vận h\u0026#224;nh chuẩn.\u003c/p\u003e\u003ch2\u003ePHẦN 5: ĐÁP ÁN, HƯỚNG DẪN CHẤM VÀ BIỂU ĐIỂM CHI TIẾT\u003c/h2\u003e\u003cp\u003e\u003cstrong\u003eĐ\u0026#225;p \u0026#225;n C\u0026#226;u 1 (1,5 điểm):\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003ea) So s\u0026#225;nh truyền động đai v\u0026#224; truyền động x\u0026#237;ch (1,0 điểm):\u003cbr\u003e\u003cstrong\u003e• Giống nhau (0,25đ): \u003c/strong\u003eĐều gồm 2 b\u0026#225;nh quay v\u0026#224; yếu tố li\u0026#234;n kết \u0026#244;m quanh 2 b\u0026#225;nh; d\u0026#249;ng để truyền chuyển động giữa 2 trục xa nhau; chiều quay 2 b\u0026#225;nh c\u0026#249;ng chiều.\u003cbr\u003e• Kh\u0026#225;c nhau (0,75đ):\u003cbr\u003e  - Yếu tố li\u0026#234;n kết \u0026amp; Nguy\u0026#234;n l\u0026#253;: Đai d\u0026#249;ng d\u0026#226;y đai ma s\u0026#225;t; X\u0026#237;ch d\u0026#249;ng x\u0026#237;ch ăn khớp với đĩa x\u0026#237;ch (0,25đ).\u003cbr\u003e  - Đột ch\u0026#237;nh x\u0026#225;c tỉ số truyền: Đai c\u0026#243; hiện tượng trượt, i kh\u0026#244;ng ch\u0026#237;nh x\u0026#225;c tuyệt đối; X\u0026#237;ch ăn khớp n\u0026#234;n i ch\u0026#237;nh x\u0026#225;c tuyệt đối (0,25đ).\u003cbr\u003e  - Khả năng bảo vệ qu\u0026#225; tải: Đai chạy \u0026#234;m, tự trượt khi qu\u0026#225; tải gi\u0026#250;p bảo vệ động cơ; X\u0026#237;ch kh\u0026#244;ng trượt, g\u0026#226;y tiếng ồn lớn hơn (0,25đ).\u003cbr\u003eb) Giải th\u0026#237;ch l\u0026#237; do d\u0026#249;ng truyền động b\u0026#225;nh răng (0,5 điểm):\u003cbr\u003e• Truyền động b\u0026#225;nh răng l\u0026#224;m việc dựa tr\u0026#234;n nguy\u0026#234;n l\u0026#253; ăn khớp trực tiếp giữa c\u0026#225;c răng, kh\u0026#244;ng c\u0026#243; hiện tượng trượt n\u0026#234;n đảm bảo tỷ số truyền i ch\u0026#237;nh x\u0026#225;c tuyệt đối (0,25đ).\u003cbr\u003e• C\u0026#243; khả năng chịu tải rất lớn, lực truyền khỏe, k\u0026#237;ch thước gọn nhẹ hơn truyền động đai (0,25đ).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eĐ\u0026#225;p \u0026#225;n C\u0026#226;u 2 (3,0 điểm - Chuẩn biểu điểm Đề thi nguồn Vĩnh Long):\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003e\u0026#221; / Y\u0026#234;u cầu\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eHướng dẫn giải chi tiết\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eĐiểm\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eT\u0026#243;m tắt đề\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eCho biết: Z₁ = 20 răng, n₁ = 120 v\u0026#242;ng/ph\u0026#250;t, Z₂ = 60 răng.\u003cbr\u003eCần t\u0026#237;nh: i = ?; n₂ = ? (v\u0026#242;ng/ph\u0026#250;t); Chiều quay \u0026amp; Nguy cơ an to\u0026#224;n.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e0,25đ\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003ea) T\u0026#237;nh tỉ số truyền i\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eC\u0026#244;ng thức: i = n₁ / n₂ = Z₂ / Z₁\u003cbr\u003eThay số: i = 60 / 20 = 3\u003cbr\u003eKết luận: Tỉ số truyền i = 3.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e0,75đ\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eb) T\u0026#237;nh tốc độ n₂ \u0026amp; Nhận x\u0026#233;t\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eTừ i = n₁ / n₂ ⇒ n₂ = n₁ / i = 120 / 3 = 40 (v\u0026#242;ng/ph\u0026#250;t).\u003cbr\u003e- B\u0026#225;nh bị dẫn quay chậm hơn b\u0026#225;nh dẫn 3 lần (120/40 = 3 lần).\u003cbr\u003e- Đ\u0026#226;y l\u0026#224; bộ truyền GIẢM TỐC (v\u0026#236; i = 3 \u0026gt; 1 v\u0026#224; n₂ \u0026lt; n₁).\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e1,00đ\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003ec) X\u0026#225;c định chiều quay\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eTrong truyền động b\u0026#225;nh răng ăn khớp ngo\u0026#224;i, b\u0026#225;nh bị dẫn 2 quay NGƯỢC CHIỀU so với b\u0026#225;nh dẫn 1.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e0,50đ\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003ed) An to\u0026#224;n vận h\u0026#224;nh\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e- Nguy cơ: Cuốn kẹt tay, t\u0026#243;c, quần \u0026#225;o v\u0026#224;o khe ăn khớp giữa 2 b\u0026#225;nh răng g\u0026#226;y tai nạn kẹp dập nặng.\u003cbr\u003e- Biện ph\u0026#225;p: Phải lắp vỏ bảo vệ (hộp che k\u0026#237;n) phủ to\u0026#224;n bộ c\u0026#225;c b\u0026#225;nh răng; ngắt điện trước khi bảo tr\u0026#236;.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e0,50đ\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003cp\u003e\u003cstrong\u003eĐ\u0026#225;p \u0026#225;n C\u0026#226;u 3 (2,5 điểm):\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003ea) T\u0026#237;nh i v\u0026#224; n₂ (1,5 điểm):\u003cbr\u003e• Ta c\u0026#243; c\u0026#244;ng thức tỉ số truyền đai: i = D₂ / D₁ = 280 / 80 = 3,5 (0,75đ).\u003cbr\u003e• Tốc độ quay của m\u0026#225;y may n₂: n₂ = n₁ / i = 1400 / 3,5 = 400 (v\u0026#242;ng/ph\u0026#250;t) (0,75đ).\u003cbr\u003eb) T\u0026#237;nh đường k\u0026#237;nh D₂\u0026#39; mới (1,0 điểm):\u003cbr\u003e• Tỉ số truyền mới i\u0026#39; = n₁ / n₂\u0026#39; = 1400 / 700 = 2 (0,5đ).\u003cbr\u003e• Ta c\u0026#243; i\u0026#39; = D₂\u0026#39; / D₁ ⇒ D₂\u0026#39; = i\u0026#39; \u0026#215; D₁ = 2 \u0026#215; 80 = 160 (mm) (0,5đ).\u003cbr\u003e  Kết luận: Cần thay b\u0026#225;nh bị dẫn mới c\u0026#243; đường k\u0026#237;nh D₂\u0026#39; = 160 mm.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eĐ\u0026#225;p \u0026#225;n C\u0026#226;u 4 (2,0 điểm):\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e• Đ\u0026#225;nh gi\u0026#225; h\u0026#224;nh vi (0,5đ): H\u0026#224;nh vi th\u0026#225;o bỏ hộp bảo vệ che đĩa x\u0026#237;ch l\u0026#224; vi phạm nghi\u0026#234;m trọng quy chuẩn an to\u0026#224;n lao động cơ kh\u0026#237;.\u003cbr\u003e• Ph\u0026#226;n t\u0026#237;ch rủi ro nguy hiểm (0,75đ): Đĩa x\u0026#237;ch v\u0026#224; x\u0026#237;ch chuyển động với tốc độ v\u0026#224; lực k\u0026#233;o rất lớn. Khi kh\u0026#244;ng c\u0026#243; vỏ che chắn, bất kỳ sự bất cẩn n\u0026#224;o (sơ hở găng tay, vạt \u0026#225;o, t\u0026#243;c) đều sẽ bị khe ăn khớp x\u0026#237;ch - đĩa x\u0026#237;ch cuốn kẹt v\u0026#224;o lập tức, g\u0026#226;y dập n\u0026#225;t b\u0026#224;n tay hoặc thương t\u0026#237;ch nặng. Đồng thời x\u0026#237;ch c\u0026#243; thể văng bắn mỡ, phoi cắt v\u0026#224;o mắt người vận h\u0026#224;nh.\u003cbr\u003e• Quy tắc an to\u0026#224;n chuẩn (0,75đ):\u003cbr\u003e  1. Bắt buộc duy tr\u0026#236; hộp bảo vệ che k\u0026#237;n ho\u0026#224;n to\u0026#224;n bộ truyền động x\u0026#237;ch trong suốt qu\u0026#225; tr\u0026#236;nh m\u0026#225;y vận h\u0026#224;nh.\u003cbr\u003e  2. Chỉ thực hiện kiểm tra, thay thế hoặc tra dầu x\u0026#237;ch khi Đ\u0026#195; NGẮT HO\u0026#192;N TO\u0026#192;N NGUỒN ĐIỆN v\u0026#224; m\u0026#225;y đ\u0026#227; dừng quay hẳn.\u003c/p\u003e","6":"\u003ch2\u003eCHUYÊN ĐỀ 6: AN TOÀN ĐIỆN, SƠ CỨU TAI NẠN ĐIỆN VÀ TIẾT KIỆM ĐIỆN NĂNG\u003c/h2\u003e\u003ch3\u003eI. BẢN ĐỒ KIẾN THỨC VÀ MỤC TIÊU ÔN TẬP CHUYÊN ĐỀ 6\u003c/h3\u003e\u003ch2\u003eChuyên đề 6 thuộc mạch kiến thức Công nghệ 8 (Trọng tâm Đề thi HSG Vĩnh Long - Câu 7 tự luận, chiếm 2,0 điểm). Chuyên đề kiểm tra năng lực hiểu biết thực tiễn, phân tích bản chất khoa học sinh lý - vật lý của dòng điện, kỹ năng thao tác quy trình sơ cứu cứu người bị tai nạn điện và đề xuất giải pháp công nghệ tiết kiệm năng lượng điện.\u003c/h2\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eMức độ năng lực\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eY\u0026#234;u cầu cần đạt chi tiết trong kỳ thi HSG\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eNhận biết\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eTr\u0026#236;nh b\u0026#224;y ch\u0026#237;nh x\u0026#225;c c\u0026#225;c nguy\u0026#234;n nh\u0026#226;n g\u0026#226;y tai nạn điện (chạm trực tiếp, vi phạm khoảng c\u0026#225;ch an to\u0026#224;n, ph\u0026#243;ng điện); N\u0026#234;u c\u0026#225;c dụng cụ, thiết bị bảo vệ an to\u0026#224;n điện v\u0026#224; quy tr\u0026#236;nh sơ cứu 3 bước.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eTh\u0026#244;ng hiểu\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eGiải th\u0026#237;ch bản chất sinh l\u0026#253; t\u0026#225;c hại của d\u0026#242;ng điện đối với cơ thể người; Ph\u0026#226;n t\u0026#237;ch cơ chế nguy hiểm của điện \u0026#225;p bước v\u0026#224; hiện tượng hồ quang điện; Giải th\u0026#237;ch l\u0026#253; do phải thực hiện nghi\u0026#234;m ngặt c\u0026#225;c thao t\u0026#225;c sơ cứu.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eVận dụng\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eTr\u0026#236;nh b\u0026#224;y đ\u0026#250;ng thứ tự v\u0026#224; ch\u0026#237;nh x\u0026#225;c kỹ thuật c\u0026#225;c bước sơ cứu nạn nh\u0026#226;n bị điện giật (t\u0026#225;ch nguồn, kiểm tra/h\u0026#244; hấp nh\u0026#226;n tạo, cấp cứu y tế); Lập bảng t\u0026#237;nh điện năng ti\u0026#234;u thụ v\u0026#224; chi ph\u0026#237; tiền điện gia đ\u0026#236;nh.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eVận dụng cao\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003ePh\u0026#226;n t\u0026#237;ch, đ\u0026#225;nh gi\u0026#225; t\u0026#236;nh huống tai nạn điện thực tế; Đề xuất m\u0026#244; h\u0026#236;nh/mạng điện th\u0026#244;ng minh, giải ph\u0026#225;p tiết kiệm điện năng sinh hoạt v\u0026#224; sản xuất đ\u0026#225;p ứng ti\u0026#234;u ch\u0026#237; ph\u0026#225;t triển bền vững.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003ch3\u003eII. HỆ THỐNG LÝ THUYẾT CHUYÊN SÂU \u0026 BẢN CHẤT KHOA HỌC\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003e1. Nguy\u0026#234;n nh\u0026#226;n g\u0026#226;y tai nạn điện v\u0026#224; Nguy\u0026#234;n tắc an to\u0026#224;n điện\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cem\u003e\u003cstrong\u003ea) Ph\u0026#226;n loại nguy\u0026#234;n nh\u0026#226;n g\u0026#226;y tai nạn điện:\u003c/strong\u003e\u003c/em\u003e\u003c/p\u003e\u003cp\u003eTrong thực tế sinh hoạt v\u0026#224; sản xuất, tai nạn điện xảy ra do 3 nh\u0026#243;m nguy\u0026#234;n nh\u0026#226;n cốt l\u0026#245;i:\u003cbr\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eChạm trực tiếp v\u0026#224;o vật mang điện: \u003c/strong\u003eChạm v\u0026#224;o d\u0026#226;y điện trần, d\u0026#226;y dẫn bị hở c\u0026#225;ch điện, chạm v\u0026#224;o v\u0026#244; t\u0026#236;nh hoặc cố \u0026#253; v\u0026#224;o thiết bị điện bị r\u0026#242; rỉ điện ra vỏ kim loại khi kh\u0026#244;ng nối đất bảo vệ.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eVi phạm khoảng c\u0026#225;ch an to\u0026#224;n đối với lưới điện cao \u0026#225;p: \u003c/strong\u003eLưới điện cao \u0026#225;p c\u0026#243; điện \u0026#225;p rất lớn (từ 110kV, 220kV, 500kV). D\u0026#249; chưa chạm trực tiếp v\u0026#224;o d\u0026#226;y điện, kh\u0026#244;ng kh\u0026#237; xung quanh đường d\u0026#226;y c\u0026#243; thể bị ion h\u0026#243;a dẫn đến ph\u0026#243;ng điện hồ quang qua kh\u0026#244;ng kh\u0026#237; g\u0026#226;y bỏng nặng hoặc tử vong.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eChạm v\u0026#224;o vật bị nhiễm điện do hiện tượng điện \u0026#225;p bước: \u003c/strong\u003eKhi d\u0026#226;y điện cao \u0026#225;p đứt rơi xuống đất, d\u0026#242;ng điện lan truyền trong đất tạo th\u0026#224;nh c\u0026#225;c v\u0026#249;ng điện thế giảm dần từ t\u0026#226;m đứt ra ngo\u0026#224;i. Khi người đi v\u0026#224;o v\u0026#249;ng n\u0026#224;y, hai ch\u0026#226;n bước tạo ra hiệu điện thế (gọi l\u0026#224; điện \u0026#225;p bước) dẫn đến d\u0026#242;ng điện chạy từ ch\u0026#226;n n\u0026#224;y qua hạ bộ sang ch\u0026#226;n kia g\u0026#226;y co giật, ng\u0026#227; sập.\u003c/p\u003e\u003cp\u003e\u003cem\u003e\u003cstrong\u003eb) C\u0026#225;c nguy\u0026#234;n tắc v\u0026#224; thiết bị bảo vệ an to\u0026#224;n điện:\u003c/strong\u003e\u003c/em\u003e\u003c/p\u003e\u003cp\u003e• \u003cstrong\u003eDụng cụ bảo vệ an to\u0026#224;n điện: \u003c/strong\u003eDụng cụ c\u0026#225;ch điện bổ sung (s\u0026#224;o c\u0026#225;ch điện, găng tay cao su c\u0026#225;ch điện, ủng c\u0026#225;ch điện, thảm c\u0026#225;ch điện, b\u0026#250;t thử điện).\u003cbr\u003e• \u003cstrong\u003eNối đất bảo vệ (Earthing): \u003c/strong\u003eNối vỏ kim loại của thiết bị điện (m\u0026#225;y giặt, tủ lạnh, bếp từ) xuống cọc sắt cắm s\u0026#226;u dưới đất. Khi thiết bị bị r\u0026#242; điện, d\u0026#242;ng điện r\u0026#242; sẽ ưu ti\u0026#234;n chạy xuống đất (do điện trở đất rất nhỏ R_đất \u0026lt; 4 Ω) thay v\u0026#236; chạy qua cơ thể người.\u003cbr\u003e• \u003cstrong\u003eCầu dao chống giật (ELCB/RCCB): \u003c/strong\u003eThiết bị tự động so s\u0026#225;nh d\u0026#242;ng điện đi (d\u0026#226;y pha) v\u0026#224; d\u0026#242;ng điện về (d\u0026#226;y trung t\u0026#237;nh). Khi c\u0026#243; sự ch\u0026#234;nh lệch (r\u0026#242; điện ra ngo\u0026#224;i hoặc qua người \u0026gt; 30mA), ELCB sẽ ngắt mạch điện trong thời gian cực ngắn (0,03 gi\u0026#226;y).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e2. Bản chất hiện tượng d\u0026#242;ng điện chạy qua cơ thể người\u003c/strong\u003e\u003c/p\u003e\u003cp\u003eCơ thể người l\u0026#224; một vật dẫn điện sinh học. Khi người chạm v\u0026#224;o hai điểm c\u0026#243; điện thế kh\u0026#225;c nhau, d\u0026#242;ng điện (I) chạy qua cơ thể phụ thuộc v\u0026#224;o Điện \u0026#225;p tiếp x\u0026#250;c (U) v\u0026#224; Điện trở cơ thể người (R_người) theo định luật \u0026#212;m: \u003cstrong\u003eI = U / R_người\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e• \u003cstrong\u003eĐiện trở cơ thể người (R_người): \u003c/strong\u003eNằm trong khoảng từ 1.000 Ω đến 100.000 Ω. Điện trở tập trung chủ yếu ở lớp da kh\u0026#244; (lớp sừng). Khi da bị ẩm ướt, mồ h\u0026#244;i, trầy xước hoặc diện t\u0026#237;ch tiếp x\u0026#250;c lớn, R_người giảm mạnh xuống chỉ c\u0026#242;n 500 Ω – 1.000 Ω. Do đ\u0026#243;, l\u0026#224;m việc với điện khi tay ướt v\u0026#244; c\u0026#249;ng nguy hiểm.\u003cbr\u003e• \u003cstrong\u003eMức độ t\u0026#225;c động của cường độ d\u0026#242;ng điện (chuẩn tần số 50Hz):\u003c/strong\u003e\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eCường độ d\u0026#242;ng điện (I)\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eT\u0026#225;c động sinh l\u0026#253; l\u0026#234;n cơ thể\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eĐ\u0026#225;nh gi\u0026#225; mức độ nguy hiểm\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003e0,6 mA – 1,5 mA\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eT\u0026#234; nhẹ tại điểm tiếp x\u0026#250;c (D\u0026#242;ng điện cảm gi\u0026#225;c)\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eAn to\u0026#224;n, chưa g\u0026#226;y tổn thương\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003e2 mA – 5 mA\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eBắp tay rung co giật nhẹ\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eCảnh b\u0026#225;o nguy hiểm\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003e10 mA – 15 mA\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eC\u0026#225;c cơ co giật mạnh, kh\u0026#244;ng tự rời vật mang điện (D\u0026#242;ng điện bu\u0026#244;ng thả)\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eNguy hiểm, kh\u0026#244;ng tự tho\u0026#225;t được\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003e50 mA – 100 mA\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eTim đập loạn nhịp, cơ tim co thắt mạnh (Rung thất), liệt h\u0026#244; hấp\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eCực kỳ nguy hiểm, tử vong sau v\u0026#224;i gi\u0026#226;y\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003cp\u003e\u003cstrong\u003e3. Quy tr\u0026#236;nh chuẩn 3 bước sơ cứu người bị tai nạn điện (Nội dung cốt l\u0026#245;i đề thi)\u003c/strong\u003e\u003c/p\u003e\u003cp\u003eKhi ph\u0026#225;t hiện người bị điện giật, phải khẩn trương thực hiện cấp cứu theo đ\u0026#250;ng \u003cstrong\u003eQuy tr\u0026#236;nh 3 bước ti\u0026#234;u chuẩn \u003c/strong\u003esau đ\u0026#226;y. Thứ tự c\u0026#225;c bước kh\u0026#244;ng được ph\u0026#233;p đảo lộn:\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eBƯỚC 1: T\u0026#193;CH NẠN NH\u0026#194;N RA KHỎI NGUỒN ĐIỆN (NGUY\u0026#202;N TẮC AN TO\u0026#192;N TUYỆT ĐỐI)\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e\u003cstrong\u003e• \u003c/strong\u003eMục đ\u0026#237;ch: Ngắt nguồn d\u0026#242;ng điện chạy qua người nạn nh\u0026#226;n để chặn đứt tổn thương sinh l\u0026#253;.\u003cbr\u003e\u003cstrong\u003e• \u003c/strong\u003eH\u0026#224;nh động cụ thể:\u003cbr\u003e  - Nhanh ch\u0026#243;ng cắt cầu dao, ngắt gạt aptomat hoặc r\u0026#250;t ph\u0026#237;ch cắm điện gần nhất.\u003cbr\u003e  - Nếu kh\u0026#244;ng thể ngắt nguồn điện ngay: \u003cstrong\u003eTuyệt đối kh\u0026#244;ng d\u0026#249;ng tay trần chạm v\u0026#224;o nạn nh\u0026#226;n\u003c/strong\u003e (v\u0026#236; cơ thể nạn nh\u0026#226;n đang bị nhiễm điện, chạm tay trần sẽ bị điện giật d\u0026#226;y chuyền).\u003cbr\u003e  - Phải đứng tr\u0026#234;n vật c\u0026#225;ch điện (ghế gỗ kh\u0026#244;, thảm cao su, gạch kh\u0026#244;), đeo găng tay cao su hoặc quấn gậy gỗ kh\u0026#244;, d\u0026#249;ng gậy gỗ/tre kh\u0026#244; gạt d\u0026#226;y điện ra khỏi người nạn nh\u0026#226;n, hoặc d\u0026#249;ng d\u0026#226;y thừng kh\u0026#244;/\u0026#225;o kh\u0026#244; gạt k\u0026#233;o nạn nh\u0026#226;n ra.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eBƯỚC 2: SƠ CỨU NGAY TẠI CHỖ T\u0026#217;Y THEO TRẠNG TH\u0026#193;I NẠN NH\u0026#194;N\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003eSau khi đ\u0026#227; t\u0026#225;ch nạn nh\u0026#226;n khỏi nguồn điện v\u0026#224; chuyển đến vị tr\u0026#237; kh\u0026#244; r\u0026#225;o, tho\u0026#225;ng kh\u0026#237;, lập tức kiểm tra t\u0026#236;nh trạng nạn nh\u0026#226;n:\u003cbr\u003e\u003cstrong\u003e• \u003c/strong\u003eTrường hợp 1: Nạn nh\u0026#226;n c\u0026#242;n tỉnh t\u0026#225;o, thở b\u0026#236;nh thường:\u003cbr\u003e  - Đặt nạn nh\u0026#226;n nằm nghỉ ngơi nơi tho\u0026#225;ng m\u0026#225;t, thả lỏng c\u0026#250;c \u0026#225;o, đai lưng.\u003cbr\u003e  - Mời b\u0026#225;c sĩ hoặc đưa đến cơ sở y tế gần nhất để theo d\u0026#245;i (v\u0026#236; điện giật c\u0026#243; thể g\u0026#226;y rối loạn nhịp tim muộn).\u003cbr\u003e\u003cstrong\u003e• \u003c/strong\u003eTrường hợp 2: Nạn nh\u0026#226;n ngất xỉu, tim ngừng đập, ngừng thở (Ngừng tuần ho\u0026#224;n):\u003cbr\u003e  - Phải thực hiện sơ cứu h\u0026#244; hấp nh\u0026#226;n tạo v\u0026#224; \u0026#233;p tim ngo\u0026#224;i lồng ngực ngay lập tức (Thời gian v\u0026#224;ng cấp cứu trong 3–5 ph\u0026#250;t đầu).\u003cbr\u003e\u003cstrong\u003e  - Kỹ thuật \u0026#233;p tim - thổi nạt: Nằm ngửa nạn nh\u0026#226;n tr\u0026#234;n nền cứng, n\u0026#233;n tim ngo\u0026#224;i lồng ngực với tần số 100 - 120 lần/ph\u0026#250;t, kết hợp thổi ngạt theo tỉ lệ 30 lần \u0026#233;p tim : 2 lần thổi ngạt\u003c/strong\u003e. Ki\u0026#234;n tr\u0026#236; cấp cứu li\u0026#234;n tục cho đến khi nạn nh\u0026#226;n tự thở lại hoặc c\u0026#243; y tế tiếp quản.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eBƯỚC 3: ĐƯA NẠN NH\u0026#194;N ĐẾN CƠ SỞ Y TẾ GẦN NHẤT\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e• Khi nạn nh\u0026#226;n hồi phục nhịp thở hoặc trong qu\u0026#225; tr\u0026#236;nh vừa sơ cứu \u0026#233;p tim vừa nhanh ch\u0026#243;ng chuyển nạn nh\u0026#226;n bằng xe cấp cứu đến bệnh viện gần nhất để điều trị bỏng điện v\u0026#224; biến chứng tim mạch.\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eLƯU \u0026#221; ĐIỂM CHẤM HSG CỦA SỞ GDĐT VĨNH LONG: \u003c/strong\u003e\u003cem\u003eTrong b\u0026#224;i thi HSG, khi tr\u0026#236;nh b\u0026#224;y quy tr\u0026#236;nh sơ cứu tai nạn điện, học sinh bắt buộc phải n\u0026#234;u r\u0026#245; nguy\u0026#234;n tắc \u0026#39;KH\u0026#212;NG D\u0026#217;NG TAY TRẦN CHẠM V\u0026#192;O NẠN NH\u0026#194;N\u0026#39; khi chưa ngắt điện. Bỏ qua chi tiết n\u0026#224;y hoặc nhầm lẫn thứ tự cắt điện sẽ bị trừ điểm nặng.\u003c/em\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003cp\u003e\u003cstrong\u003e4. Tiết kiệm điện năng v\u0026#224; Sử dụng điện hiệu quả trong gia đ\u0026#236;nh\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e• \u003c/strong\u003eC\u0026#244;ng thức t\u0026#237;nh điện năng ti\u0026#234;u thụ của đồ d\u0026#249;ng điện:\u003cbr\u003e\u003cstrong\u003e  C\u0026#244;ng thức: \u003c/strong\u003e\u003cstrong\u003eA = P \u0026#215; t\u003c/strong\u003e\u003cbr\u003e  Trong đ\u0026#243;: A l\u0026#224; điện năng ti\u0026#234;u thụ (Wh hoặc kWh); P l\u0026#224; c\u0026#244;ng suất điện định mức (W hoặc kW); t l\u0026#224; thời gian l\u0026#224;m việc (h).\u003cbr\u003e  Đổi đơn vị: 1 kWh = 1.000 Wh = 1 số điện.\u003cbr\u003e\u003cstrong\u003e• \u003c/strong\u003eC\u0026#225;c giải ph\u0026#225;p tiết kiệm điện năng sinh hoạt:\u003cbr\u003e  1. Lựa chọn thiết bị tiết kiệm năng lượng (c\u0026#243; d\u0026#225;n nh\u0026#227;n năng lượng 5 sao, c\u0026#244;ng nghệ Inverter).\u003cbr\u003e  2. Tắt c\u0026#225;c thiết bị điện khi kh\u0026#244;ng sử dụng, r\u0026#250;t ph\u0026#237;ch cắm để tr\u0026#225;nh ti\u0026#234;u hao điện năng chờ (Standby power).\u003cbr\u003e  3. Sử dụng hợp l\u0026#253; đồ d\u0026#249;ng c\u0026#244;ng suất lớn (Điều h\u0026#242;a c\u0026#224;i đặt 26–28\u0026#176;C kết hợp quạt, hạn chế bật b\u0026#236;nh nước n\u0026#243;ng giờ cao điểm).\u003cbr\u003e  4. Tận dụng nguồn năng lượng tự nhi\u0026#234;n (chiếu s\u0026#225;ng v\u0026#224; th\u0026#244;ng gi\u0026#243; tự nhi\u0026#234;n, lắp b\u0026#236;nh nước n\u0026#243;ng năng lượng mặt trời).\u003c/p\u003e\u003ch3\u003eIII. TRỌNG TÂM CÂU HỎI THI HSG VĨNH LONG \u0026 ĐÁP ÁN MẪU (2,0 ĐIỂM)\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#194;U 7 (2,0 ĐIỂM) - ĐỀ THI CH\u0026#205;NH THỨC HSG THCS TỈNH VĨNH LONG:\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cem\u003eEm h\u0026#227;y tr\u0026#236;nh b\u0026#224;y quy tr\u0026#236;nh sơ cứu tai nạn điện? V\u0026#236; sao khi người bị nạn chưa được t\u0026#225;ch khỏi nguồn điện, người đến cứu kh\u0026#244;ng được chạm trực tiếp v\u0026#224;o cơ thể người bị nạn? Đề xuất 03 giải ph\u0026#225;p cụ thể gi\u0026#250;p gia đ\u0026#236;nh em tiết kiệm điện năng ti\u0026#234;u thụ hằng th\u0026#225;ng?\u003c/em\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eĐ\u0026#193;P \u0026#193;N V\u0026#192; BIỂU ĐIỂM CHẤM CHUẨN CỦA SỞ GDĐT (2,0 ĐIỂM):\u003c/strong\u003e\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003e\u0026#221; / Bước\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eNội dung đ\u0026#225;p \u0026#225;n chuẩn y\u0026#234;u cầu đạt\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eĐiểm\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003e\u0026#221; 1: Quy tr\u0026#236;nh sơ cứu\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eTr\u0026#236;nh b\u0026#224;y chuẩn Quy tr\u0026#236;nh 3 bước sơ cứu tai nạn điện:\u003cbr\u003e- Bước 1: Nhanh ch\u0026#243;ng t\u0026#225;ch nạn nh\u0026#226;n ra khỏi nguồn điện (ngắt cầu dao/aptomat hoặc d\u0026#249;ng vật c\u0026#225;ch điện gạt d\u0026#226;y điện).\u003cbr\u003e- Bước 2: Tiến h\u0026#224;nh sơ cứu ngay tại chỗ (nghỉ ngơi nơi tho\u0026#225;ng kh\u0026#237; nếu tỉnh; \u0026#233;p tim ngo\u0026#224;i lồng ngực + h\u0026#244; hấp nh\u0026#226;n tạo 30:2 nếu ngừng thở/ngừng tim).\u003cbr\u003e- Bước 3: Nhanh ch\u0026#243;ng đưa nạn nh\u0026#226;n đến cơ sở y tế gần nhất.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003e1,00 đ\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003e\u0026#221; 2: Giải th\u0026#237;ch l\u0026#253; do\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eGiải th\u0026#237;ch bản chất vật l\u0026#253; - an to\u0026#224;n:\u003cbr\u003e- Cơ thể người l\u0026#224; một vật dẫn điện.\u003cbr\u003e- Khi chưa ngắt nguồn điện, cơ thể nạn nh\u0026#226;n đang mang điện \u0026#225;p của nguồn điện.\u003cbr\u003e- Nếu người đến cứu chạm trực tiếp tay trần v\u0026#224;o nạn nh\u0026#226;n, d\u0026#242;ng điện sẽ truyền qua cơ thể người cứu xuống đất, khiến người đến cứu cũng bị điện giật (bị d\u0026#237;nh chặt hoặc tai nạn d\u0026#226;y chuyền).\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003e0,50 đ\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003e\u0026#221; 3: Đề xuất giải ph\u0026#225;p\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eĐề xuất đ\u0026#250;ng v\u0026#224; thực tế 03 giải ph\u0026#225;p tiết kiệm điện (mỗi giải ph\u0026#225;p đ\u0026#250;ng đạt 0,17đ):\u003cbr\u003e1. Tắt c\u0026#225;c thiết bị điện (đ\u0026#232;n, quạt, tivi) khi rời khỏi ph\u0026#242;ng v\u0026#224; r\u0026#250;t ph\u0026#237;ch cắm khi kh\u0026#244;ng sử dụng.\u003cbr\u003e2. Sử dụng b\u0026#243;ng đ\u0026#232;n LED tiết kiệm điện, thiết bị Inverter v\u0026#224; c\u0026#224;i đặt điều h\u0026#242;a hợp l\u0026#253; (từ 26\u0026#176;C trở l\u0026#234;n).\u003cbr\u003e3. Tận dụng tối đa \u0026#225;nh s\u0026#225;ng v\u0026#224; gi\u0026#243; tự nhi\u0026#234;n, vệ sinh bảo dưỡng đồ d\u0026#249;ng điện định kỳ.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003e0,50 đ\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eTỔNG ĐIỂM\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eTo\u0026#224;n bộ C\u0026#226;u 7\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003e2,00 đ\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003ch3\u003eIV. NGÂN HÀNG CÂU HỎI VÀ BÀI TẬP PHÂN HÓA (4 MỨC ĐỘ)\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003e1. Mức độ Nhận biết \u0026amp; Th\u0026#244;ng hiểu\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 1: \u003c/strong\u003eTr\u0026#236;nh b\u0026#224;y c\u0026#225;c nguy\u0026#234;n nh\u0026#226;n phổ biến g\u0026#226;y ra tai nạn điện trong sinh hoạt gia đ\u0026#236;nh? Cho biết c\u0026#225;c thiết bị bảo vệ an to\u0026#224;n điện được lắp đặt trong mạng điện nh\u0026#224; c\u0026#243; vai tr\u0026#242; g\u0026#236;?\u003cbr\u003e\u003cstrong\u003eC\u0026#226;u 2: \u003c/strong\u003eV\u0026#236; sao khi tay bị ẩm ướt hoặc đứng tr\u0026#234;n nền nh\u0026#224; ẩm ướt, nguy cơ bị điện giật v\u0026#224; mức độ nguy hiểm lại tăng l\u0026#234;n gấp nhiều lần so với khi tay kh\u0026#244; r\u0026#225;o?\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e2. Mức độ Vận dụng\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 3: \u003c/strong\u003eMột gia đ\u0026#236;nh sử dụng c\u0026#225;c đồ d\u0026#249;ng điện trung b\u0026#236;nh một ng\u0026#224;y như sau:\u003cbr\u003e  - 04 b\u0026#243;ng đ\u0026#232;n LED loại 20W, thời gian sử dụng 5 giờ/ng\u0026#224;y.\u003cbr\u003e  - 02 quạt b\u0026#224;n loại 60W, thời gian sử dụng 8 giờ/ng\u0026#224;y.\u003cbr\u003e  - 01 tivi loại 100W, thời gian sử dụng 4 giờ/ng\u0026#224;y.\u003cbr\u003e  - 01 tủ lạnh loại 150W, hoạt động li\u0026#234;n tục 24 giờ/ng\u0026#224;y.\u003cbr\u003ea) T\u0026#237;nh tổng điện năng ti\u0026#234;u thụ của gia đ\u0026#236;nh đ\u0026#243; trong 1 ng\u0026#224;y (theo đơn vị Wh v\u0026#224; kWh).\u003cbr\u003eb) T\u0026#237;nh tổng tiền điện gia đ\u0026#236;nh phải trả trong th\u0026#225;ng 4 (30 ng\u0026#224;y), biết gi\u0026#225; điện trung b\u0026#236;nh l\u0026#224; 2.200 đồng/kWh.\u003cbr\u003e\u003cstrong\u003eC\u0026#226;u 4: \u003c/strong\u003eTr\u0026#236;nh b\u0026#224;y quy tr\u0026#236;nh kiểm tra an to\u0026#224;n đồ d\u0026#249;ng điện gia đ\u0026#236;nh trước khi đưa v\u0026#224;o sử dụng.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e3. Mức độ Vận dụng cao \u0026amp; T\u0026#236;nh huống thực tiễn\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 5 (T\u0026#236;nh huống sơ cứu): \u003c/strong\u003eTrong l\u0026#250;c mưa to b\u0026#227;o lớn, Nam đi học về ph\u0026#225;t hiện một d\u0026#226;y điện cao \u0026#225;p đứt rơi xuống mặt đường nhựa wet. Một người đi xe đạp ph\u0026#237;a trước v\u0026#244; t\u0026#236;nh c\u0026#225;n qua vạch đường gần d\u0026#226;y điện v\u0026#224; ng\u0026#227; gục xuống đường, xe đạp đ\u0026#232; l\u0026#234;n d\u0026#226;y điện.\u003cbr\u003ea) Nam c\u0026#243; n\u0026#234;n chạy ngay lại nắm tay k\u0026#233;o người bị nạn ra khỏi d\u0026#226;y điện kh\u0026#244;ng? Tại sao?\u003cbr\u003eb) Dựa v\u0026#224;o kiến thức về an to\u0026#224;n điện v\u0026#224; hiện tượng điện \u0026#225;p bước, h\u0026#227;y đưa ra quy tr\u0026#236;nh xử l\u0026#253; t\u0026#236;nh huống th\u0026#244;ng minh, an to\u0026#224;n để cứu người bị nạn m\u0026#224; kh\u0026#244;ng nguy hiểm đến bản th\u0026#226;n.\u003cbr\u003e\u003cstrong\u003eC\u0026#226;u 6 (C\u0026#244;ng nghệ xanh \u0026amp; Tiết kiệm năng lượng): \u003c/strong\u003ePh\u0026#226;n t\u0026#237;ch cơ chế hoạt động của hệ thống b\u0026#236;nh nước n\u0026#243;ng năng lượng mặt trời (Th\u0026#225;i dương năng) v\u0026#224; giải ph\u0026#225;p kết hợp chiếu s\u0026#225;ng tự nhi\u0026#234;n với c\u0026#244;ng nghệ cảm biến th\u0026#244;ng minh nhằm tối ưu h\u0026#243;a chi ph\u0026#237; điện năng cho trường học.\u003c/p\u003e\u003ch3\u003eV. ĐÁP ÁN VÀ HƯỚNG DẪN CHẤM CHI TIẾT\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003eHướng dẫn giải chi tiết C\u0026#226;u 3 (B\u0026#224;i tập t\u0026#237;nh to\u0026#225;n điện năng):\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003ea) T\u0026#237;nh điện năng ti\u0026#234;u thụ trong 1 ng\u0026#224;y (A_ng\u0026#224;y):\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e  - Đ\u0026#232;n LED: A1 = 4 \u0026#215; 20W \u0026#215; 5h = 400 Wh.\u003cbr\u003e  - Quạt b\u0026#224;n: A2 = 2 \u0026#215; 60W \u0026#215; 8h = 960 Wh.\u003cbr\u003e  - Tivi: A3 = 1 \u0026#215; 100W \u0026#215; 4h = 400 Wh.\u003cbr\u003e  - Tủ lạnh: A4 = 1 \u0026#215; 150W \u0026#215; 24h = 3.600 Wh.\u003cbr\u003e\u003cstrong\u003e  =\u0026gt; Tổng điện năng ti\u0026#234;u thụ 1 ng\u0026#224;y: A_ng\u0026#224;y = 400 + 960 + 400 + 3.600 = 5.360 Wh = \u003c/strong\u003e\u003cstrong\u003e5,36 kWh.\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eb) T\u0026#237;nh tiền điện trong th\u0026#225;ng 4 (30 ng\u0026#224;y):\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e  - Tổng điện năng ti\u0026#234;u thụ th\u0026#225;ng 4: A_th\u0026#225;ng = 5,36 kWh/ng\u0026#224;y \u0026#215; 30 ng\u0026#224;y = 160,8 kWh.\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e  - Tổng tiền điện phải trả: T = 160,8 kWh \u0026#215; 2.200 đồng/kWh = \u003c/strong\u003e\u003cstrong\u003e353.760 đồng.\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eHướng dẫn giải chi tiết C\u0026#226;u 5 (T\u0026#236;nh huống xử l\u0026#253; sự cố đứt d\u0026#226;y điện cao \u0026#225;p):\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003ea) Nam tuyệt đối KH\u0026#212;NG ĐƯỢC chạy ngay lại nắm tay k\u0026#233;o người bị nạn \u003c/strong\u003ev\u0026#236;:\u003cbr\u003e  - D\u0026#226;y điện đứt l\u0026#224; điện cao \u0026#225;p, mặt đường nhựa wet v\u0026#224; xe đạp bằng kim loại dẫn điện cực tốt.\u003cbr\u003e  - Khi chạm v\u0026#224;o nạn nh\u0026#226;n, d\u0026#242;ng điện cao \u0026#225;p sẽ truyền ngay sang Nam g\u0026#226;y tử vong d\u0026#226;y chuyền.\u003cbr\u003e  - Xung quanh điểm d\u0026#226;y điện chạm đất c\u0026#243; hiện tượng điện \u0026#225;p bước. Nếu Nam bước chạy b\u0026#236;nh thường (sải bước rộng), hai ch\u0026#226;n ở hai v\u0026#249;ng điện thế kh\u0026#225;c nhau sẽ bị điện giật ngay từ khoảng c\u0026#225;ch xa.\u003cbr\u003e\u003cstrong\u003eb) Quy tr\u0026#236;nh xử l\u0026#253; th\u0026#244;ng minh v\u0026#224; an to\u0026#224;n:\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e  - Bước 1 (Cảnh b\u0026#225;o \u0026amp; Giữ khoảng c\u0026#225;ch): H\u0026#244; to cảnh b\u0026#225;o những người xung quanh kh\u0026#244;ng được tiến lại gần v\u0026#249;ng d\u0026#226;y điện đứt (khoảng c\u0026#225;ch an to\u0026#224;n tối thiểu 10m).\u003cbr\u003e  - Bước 2 (Di chuyển an to\u0026#224;n nếu lỡ v\u0026#224;o v\u0026#249;ng điện \u0026#225;p bước): D\u0026#249;ng kỹ thuật \u0026#39;Chụm 2 ch\u0026#226;n nhảy c\u0026#243;t gọt\u0026#39; hoặc \u0026#39;L\u0026#234; 2 ch\u0026#226;n s\u0026#225;t nhau kh\u0026#244;ng rời mặt đất\u0026#39; để di chuyển ra xa v\u0026#249;ng nguy hiểm.\u003cbr\u003e  - Bước 3 (B\u0026#225;o động khẩn cấp): Gọi ngay tổng đ\u0026#224;i điện lực (19001006/19001909) ngắt điện khu vực v\u0026#224; gọi cấp cứu 115.\u003cbr\u003e  - Bước 4 (Sơ cứu an to\u0026#224;n): Sau khi ng\u0026#224;nh điện lực x\u0026#225;c nhận đ\u0026#227; ngắt điện ho\u0026#224;n to\u0026#224;n, mới tiến h\u0026#224;nh tiếp cận sơ cứu nạn nh\u0026#226;n theo quy tr\u0026#236;nh 3 bước.\u003c/p\u003e","7":"\u003ch2\u003eCHUYÊN ĐỀ 7: NGHỀ NGHIỆP TRONG LĨNH VỰC KỸ THUẬT, CÔNG NGHỆ\u003c/h2\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003e📌\u003c/strong\u003e\u003cstrong\u003e ĐỊNH HƯỚNG TRỌNG T\u0026#194;M THI HSG (C\u0026#212;NG VĂN 730)\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e\u003cem\u003eChuy\u0026#234;n đề n\u0026#224;y thuộc Khối nội dung C\u0026#244;ng nghệ 9 - Định hướng nghề nghiệp. Theo C\u0026#244;ng văn 730/SGDĐT-GDPT Vĩnh Long, đ\u0026#226;y l\u0026#224; c\u0026#226;u hỏi tự luận chiếm 3,0 điểm (trong tổng số 20 điểm to\u0026#224;n b\u0026#224;i thi HSG). Chuy\u0026#234;n đề trang bị hệ thống l\u0026#253; luận nghề nghiệp, ph\u0026#226;n t\u0026#237;ch đặc điểm lao động kỹ thuật - c\u0026#244;ng nghệ, v\u0026#224; đ\u0026#225;nh gi\u0026#225; phẩm chất, năng lực cần thiết của người lao động trong thời đại C\u0026#244;ng nghiệp 4.0.\u003c/em\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003cp\u003e\u003cstrong\u003ePHẦN I: HỆ THỐNG KẾT CẤU L\u0026#221; THUYẾT CHUY\u0026#202;N S\u0026#194;U\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e1. Kh\u0026#225;i niệm Nghề nghiệp v\u0026#224; \u0026#221; nghĩa của việc Lựa chọn Đ\u0026#250;ng Nghề nghiệp\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003ea) Kh\u0026#225;i niệm Nghề nghiệp:\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003eNghề nghiệp l\u0026#224; tập hợp c\u0026#225;c c\u0026#244;ng việc lao động chuy\u0026#234;n m\u0026#244;n được x\u0026#227; hội c\u0026#244;ng nhận, mang lại thu nhập ch\u0026#237;nh đ\u0026#225;ng cho con người để trang trải cuộc sống v\u0026#224; đ\u0026#243;ng g\u0026#243;p cho x\u0026#227; hội. Một c\u0026#244;ng việc được coi l\u0026#224; nghề nghiệp khi đạt đủ 3 yếu tố cơ bản:\u003cbr\u003e\u003cstrong\u003e• C\u0026#243; tri thức v\u0026#224; kỹ năng chuy\u0026#234;n m\u0026#244;n: \u003c/strong\u003eĐược t\u0026#237;ch lũy qua qu\u0026#225; tr\u0026#236;nh gi\u0026#225;o dục, đ\u0026#224;o tạo b\u0026#224;i bản v\u0026#224; r\u0026#232;n luyện thực tiễn.\u003cbr\u003e\u003cstrong\u003e• Được x\u0026#227; hội thừa nhận v\u0026#224; cấp ph\u0026#233;p: \u003c/strong\u003eTạo ra gi\u0026#225; trị vật chất hoặc tinh thần đ\u0026#225;p ứng nhu cầu x\u0026#227; hội.\u003cbr\u003e\u003cstrong\u003e• Mang lại nguồn thu nhập hợp ph\u0026#225;p: \u003c/strong\u003eGi\u0026#250;p người lao động nu\u0026#244;i sống bản th\u0026#226;n v\u0026#224; gia đ\u0026#236;nh.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eb) \u0026#221; nghĩa của việc Lựa chọn Đ\u0026#250;ng Nghề nghiệp:\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003eViệc lựa chọn đ\u0026#250;ng nghề nghiệp c\u0026#243; \u0026#253; nghĩa chiến lược ở 3 cấp độ:\u003cbr\u003e\u003cstrong\u003e1. Đối với c\u0026#225; nh\u0026#226;n: \u003c/strong\u003eTạo động lực nội tại, gi\u0026#250;p ph\u0026#225;t huy tối đa tiềm năng, năng lực v\u0026#224; sở th\u0026#237;ch; mang lại niềm vui, sự h\u0026#224;i l\u0026#242;ng trong c\u0026#244;ng việc; đảm bảo thu nhập ổn định v\u0026#224; cơ hội thăng tiến bền vững.\u003cbr\u003e\u003cstrong\u003e2. Đối với gia đ\u0026#236;nh: \u003c/strong\u003eTạo nền tảng t\u0026#224;i ch\u0026#237;nh vững chắc, n\u0026#226;ng cao chất lượng cuộc sống gia đ\u0026#236;nh, tạo t\u0026#226;m l\u0026#253; an t\u0026#226;m v\u0026#224; niềm tự h\u0026#224;o cho c\u0026#225;c th\u0026#224;nh vi\u0026#234;n.\u003cbr\u003e\u003cstrong\u003e3. Đối với x\u0026#227; hội: \u003c/strong\u003eTối ưu h\u0026#243;a nguồn nh\u0026#226;n lực, giảm tỷ lệ thất nghiệp hoặc l\u0026#224;m việc tr\u0026#225;i ng\u0026#224;nh nghề; tăng năng suất lao động x\u0026#227; hội, th\u0026#250;c đẩy tăng trưởng kinh tế v\u0026#224; ph\u0026#225;t triển bền vững.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e2. Kh\u0026#225;i qu\u0026#225;t về Lĩnh vực Kỹ thuật, C\u0026#244;ng nghệ\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eKỹ thuật (Engineering) \u003c/strong\u003el\u0026#224; việc ứng dụng c\u0026#225;c nguy\u0026#234;n l\u0026#253; khoa học, to\u0026#225;n học v\u0026#224; tự nhi\u0026#234;n v\u0026#224;o thực tiễn để thiết kế, chế tạo, vận h\u0026#224;nh c\u0026#225;c c\u0026#244;ng tr\u0026#236;nh, m\u0026#225;y m\u0026#243;c, cấu tr\u0026#250;c v\u0026#224; quy tr\u0026#236;nh.\u003cbr\u003e\u003cstrong\u003eC\u0026#244;ng nghệ (Technology) \u003c/strong\u003el\u0026#224; giải ph\u0026#225;p, quy tr\u0026#236;nh, kỹ năng, b\u0026#237; quyết v\u0026#224; c\u0026#244;ng cụ được sử dụng để biến đổi nguồn lực th\u0026#224;nh sản phẩm hoặc dịch vụ đ\u0026#225;p ứng nhu cầu con người.\u003cbr\u003eMối quan hệ hữu cơ: Khoa học ph\u0026#225;t hiện ra quy luật, Kỹ thuật vận dụng quy luật để thiết kế giải ph\u0026#225;p, C\u0026#244;ng nghệ hiện thực h\u0026#243;a giải ph\u0026#225;p th\u0026#224;nh quy tr\u0026#236;nh sản xuất v\u0026#224; sản phẩm thực tế.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e3. Đặc điểm Chung của c\u0026#225;c Ng\u0026#224;nh Nghề Kỹ thuật, C\u0026#244;ng nghệ\u003c/strong\u003e\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eYếu tố đặc trưng\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eNội dung thể hiện\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003e\u0026#221; nghĩa / Y\u0026#234;u cầu thực tiễn\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eĐối tượng lao động\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eVật liệu, năng lượng, m\u0026#225;y m\u0026#243;c, thiết bị, quy tr\u0026#236;nh c\u0026#244;ng nghệ, dữ liệu số, phần mềm, bản vẽ kỹ thuật.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eY\u0026#234;u cầu hiểu biết s\u0026#226;u sắc về thuộc t\u0026#237;nh vật l\u0026#253;, h\u0026#243;a học, cơ học v\u0026#224; thuật to\u0026#225;n của đối tượng.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eM\u0026#244;i trường l\u0026#224;m việc\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eĐa dạng: nh\u0026#224; xưởng cơ kh\u0026#237;, c\u0026#244;ng trường x\u0026#226;y dựng, ph\u0026#242;ng th\u0026#237; nghiệm, ph\u0026#242;ng thiết kế CAD/CAM, trung t\u0026#226;m dữ liệu.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eM\u0026#244;i trường tiềm ẩn yếu tố nguy hiểm (tiếng ồn, điện \u0026#225;p cao, h\u0026#243;a chất) \\(\\rightarrow\\) Y\u0026#234;u cầu nghi\u0026#234;m ngặt về an to\u0026#224;n lao động.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eSản phẩm lao động\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eC\u0026#244;ng tr\u0026#236;nh, m\u0026#225;y m\u0026#243;c, linh kiện điện tử, phần mềm, dịch vụ kỹ thuật, quy tr\u0026#236;nh sản xuất cải tiến.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eSản phẩm c\u0026#243; t\u0026#237;nh ch\u0026#237;nh x\u0026#225;c cao, đ\u0026#242;i hỏi đ\u0026#225;p ứng c\u0026#225;c ti\u0026#234;u chuẩn kỹ thuật quốc gia (TCVN) v\u0026#224; quốc tế (ISO).\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003cp\u003e\u003cstrong\u003e4. Y\u0026#234;u cầu Chung về Phẩm chất v\u0026#224; Năng lực của Người Lao động Kỹ thuật, C\u0026#244;ng nghệ\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003ea) Y\u0026#234;u cầu về Phẩm chất (Attitudes \u0026amp; Ethics):\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e\u003cstrong\u003e• Cần c\u0026#249;, chăm chỉ, ki\u0026#234;n tr\u0026#236;: \u003c/strong\u003eLao động kỹ thuật đ\u0026#242;i hỏi sự tỉ mỉ, ki\u0026#234;n nhẫn khi xử l\u0026#253; sự cố phức tạp hoặc thực hiện c\u0026#225;c thao t\u0026#225;c lắp r\u0026#225;p ch\u0026#237;nh x\u0026#225;c.\u003cbr\u003e\u003cstrong\u003e• Trung thực v\u0026#224; tr\u0026#225;ch nhiệm: \u003c/strong\u003eTự gi\u0026#225;c tu\u0026#226;n thủ quy tr\u0026#236;nh c\u0026#244;ng nghệ, kh\u0026#244;ng bớt x\u0026#250;t vật liệu hay gian dối th\u0026#244;ng số kỹ thuật, chịu tr\u0026#225;ch nhiệm về chất lượng sản phẩm.\u003cbr\u003e\u003cstrong\u003e• \u0026#221; thức kỷ luật v\u0026#224; an to\u0026#224;n lao động: \u003c/strong\u003eTự gi\u0026#225;c chấp h\u0026#224;nh nội quy xưởng, quy chuẩn an to\u0026#224;n điện/cơ kh\u0026#237;, bảo hộ lao động để bảo vệ bản th\u0026#226;n v\u0026#224; đồng nghiệp.\u003cbr\u003e\u003cstrong\u003e• Tinh thần hợp t\u0026#225;c v\u0026#224; bảo vệ m\u0026#244;i trường: \u003c/strong\u003eBiết phối hợp trong nh\u0026#243;m l\u0026#224;m việc, c\u0026#243; \u0026#253; thức tiết kiệm nguy\u0026#234;n nhi\u0026#234;n liệu v\u0026#224; xử l\u0026#253; chất thải c\u0026#244;ng nghiệp đ\u0026#250;ng quy định.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eb) Y\u0026#234;u cầu về Năng lực (Competencies \u0026amp; Skills):\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e\u003cstrong\u003e• Tr\u0026#236;nh độ chuy\u0026#234;n m\u0026#244;n \u0026amp; Tri thức kỹ thuật: \u003c/strong\u003eNắm vững l\u0026#253; thuyết cơ bản, nguy\u0026#234;n l\u0026#253; hoạt động của m\u0026#225;y m\u0026#243;c v\u0026#224; quy tr\u0026#236;nh c\u0026#244;ng nghệ thuộc lĩnh vực đảm nhận.\u003cbr\u003e\u003cstrong\u003e• Kỹ năng thực h\u0026#224;nh \u0026amp; Vận h\u0026#224;nh thiết bị: \u003c/strong\u003eSử dụng th\u0026#224;nh thạo dụng cụ, thiết bị đo kiểm, phần mềm chuy\u0026#234;n ng\u0026#224;nh v\u0026#224; vận h\u0026#224;nh m\u0026#225;y m\u0026#243;c an to\u0026#224;n, hiệu quả.\u003cbr\u003e\u003cstrong\u003e• Tư duy kỹ thuật \u0026amp; Năng lực giải quyết vấn đề: \u003c/strong\u003eC\u0026#243; khả năng đọc bản vẽ, ph\u0026#226;n t\u0026#237;ch nguy\u0026#234;n nh\u0026#226;n sự cố kỹ thuật v\u0026#224; đề xuất giải ph\u0026#225;p cải tiến c\u0026#244;ng nghệ.\u003cbr\u003e\u003cstrong\u003e• Năng lực ứng dụng CNTT, ngoại ngữ v\u0026#224; Tự học: \u003c/strong\u003eSử dụng m\u0026#225;y t\u0026#237;nh, giao tiếp/đọc t\u0026#224;i liệu kỹ thuật bằng tiếng Anh; khả năng chủ động cập nhật c\u0026#244;ng nghệ mới trong thời đại 4.0.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003ePHẦN II: PH\u0026#194;N T\u0026#205;CH ĐỀ THI HSG V\u0026#192; C\u0026#193;C DẠNG B\u0026#192;I TRỌNG T\u0026#194;M\u003c/strong\u003e\u003c/p\u003e\u003cp\u003eTheo ph\u0026#226;n t\u0026#237;ch cấu tr\u0026#250;c Đề thi HSG Vĩnh Long (C\u0026#226;u 5 \u0026amp; C\u0026#226;u 6 tự luận, 3.0 điểm), c\u0026#225;c dạng b\u0026#224;i tập trọng t\u0026#226;m thuộc Chuy\u0026#234;n đề 7 bao gồm:\u003cbr\u003e\u003cem\u003e1. Dạng 1: Ph\u0026#226;n t\u0026#237;ch đặc điểm v\u0026#224; y\u0026#234;u cầu của một ng\u0026#224;nh nghề kỹ thuật cụ thể.\u003c/em\u003e\u003cem\u003e\u003cbr\u003e2. Dạng 2: So s\u0026#225;nh y\u0026#234;u cầu người lao động giữa sản xuất truyền thống v\u0026#224; sản xuất hiện đại (C\u0026#244;ng nghiệp 4.0).\u003c/em\u003e\u003cem\u003e\u003cbr\u003e3. Dạng 3: Đ\u0026#225;nh gi\u0026#225; t\u0026#236;nh huống thực tiễn về sự ph\u0026#249; hợp phẩm chất - năng lực c\u0026#225; nh\u0026#226;n đối với nghề nghiệp kỹ thuật.\u003c/em\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003ePHẦN III: NG\u0026#194;N H\u0026#192;NG C\u0026#194;U HỎI V\u0026#192; Đ\u0026#193;P \u0026#193;N CHUY\u0026#202;N S\u0026#194;U HỌC SINH GIỎI\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 1 (Mức Nhận biết - Th\u0026#244;ng hiểu - 2,0 điểm)\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eTr\u0026#236;nh b\u0026#224;y kh\u0026#225;i niệm nghề nghiệp. Ph\u0026#226;n t\u0026#237;ch 3 \u0026#253; nghĩa quan trọng của việc lựa chọn đ\u0026#250;ng nghề nghiệp đối với c\u0026#225; nh\u0026#226;n, gia đ\u0026#236;nh v\u0026#224; x\u0026#227; hội. Tại sao n\u0026#243;i: \u0026quot;Lựa chọn sai nghề nghiệp sẽ g\u0026#226;y ra l\u0026#227;ng ph\u0026#237; lớn cho cả c\u0026#225; nh\u0026#226;n v\u0026#224; x\u0026#227; hội\u0026quot;?\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eHƯỚNG DẪN CHẤM V\u0026#192; Đ\u0026#193;P \u0026#193;N CHUẨN:\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e1. Kh\u0026#225;i niệm Nghề nghiệp (0,5 điểm):\u003cbr\u003e   - Nghề nghiệp l\u0026#224; tập hợp c\u0026#225;c c\u0026#244;ng việc lao động chuy\u0026#234;n m\u0026#244;n được x\u0026#227; hội thừa nhận, đ\u0026#242;i hỏi qu\u0026#225; tr\u0026#236;nh đ\u0026#224;o tạo tri thức/kỹ năng, mang lại thu nhập ch\u0026#237;nh đ\u0026#225;ng cho con người v\u0026#224; đ\u0026#243;ng g\u0026#243;p cho ph\u0026#225;t triển x\u0026#227; hội.\u003cbr\u003e\u003cbr\u003e2. \u0026#221; nghĩa lựa chọn đ\u0026#250;ng nghề nghiệp (0,9 điểm - mỗi \u0026#253; 0,3đ):\u003cbr\u003e   - Đối với c\u0026#225; nh\u0026#226;n: Tạo động lực l\u0026#224;m việc, ph\u0026#225;t huy tối đa năng lực/sở th\u0026#237;ch; mang lại niềm vui, sự thăng tiến v\u0026#224; bảo đảm thu nhập bền vững.\u003cbr\u003e   - Đối với gia đ\u0026#236;nh: Bảo đảm ổn định kinh tế gia đ\u0026#236;nh, n\u0026#226;ng cao chất lượng cuộc sống v\u0026#224; tạo t\u0026#226;m l\u0026#253; an t\u0026#226;m, tự h\u0026#224;o cho người th\u0026#226;n.\u003cbr\u003e   - Đối với x\u0026#227; hội: Tối ưu h\u0026#243;a ph\u0026#226;n c\u0026#244;ng lao động, tăng năng suất x\u0026#227; hội, giảm thất nghiệp v\u0026#224; th\u0026#250;c đẩy kinh tế ph\u0026#225;t triển.\u003cbr\u003e\u003cbr\u003e3. Giải th\u0026#237;ch c\u0026#226;u n\u0026#243;i (0,6 điểm):\u003cbr\u003e   - Lựa chọn sai nghề l\u0026#224;m c\u0026#225; nh\u0026#226;n ch\u0026#225;n nản, kh\u0026#244;ng ph\u0026#225;t huy được năng lực, dễ ch\u0026#225;n nghề/bỏ nghề, tốn thời gian v\u0026#224; chi ph\u0026#237; đ\u0026#224;o tạo lại.\u003cbr\u003e   - Đối với x\u0026#227; hội: G\u0026#226;y t\u0026#236;nh trạng thừa thầy thiếu thợ, l\u0026#227;ng ph\u0026#237; ng\u0026#226;n s\u0026#225;ch đ\u0026#224;o tạo của Nh\u0026#224; nước, l\u0026#224;m giảm năng suất chung v\u0026#224; tạo \u0026#225;p lực thất nghiệp.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 2 (Mức Vận dụng - 3,0 điểm - Dạng b\u0026#224;i trọng t\u0026#226;m thi HSG)\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003ePh\u0026#226;n t\u0026#237;ch c\u0026#225;c đặc điểm chung về đối tượng lao động, m\u0026#244;i trường l\u0026#224;m việc v\u0026#224; sản phẩm lao động của ng\u0026#224;nh nghề trong lĩnh vực Kỹ thuật, C\u0026#244;ng nghệ. Từ đ\u0026#243;, h\u0026#227;y l\u0026#224;m r\u0026#245; những y\u0026#234;u cầu bắt buộc về phẩm chất kỷ luật v\u0026#224; an to\u0026#224;n lao động đối với người thợ cơ kh\u0026#237;/kỹ sư điện.\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eHƯỚNG DẪN CHẤM V\u0026#192; Đ\u0026#193;P \u0026#193;N CHUẨN:\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e1. Đặc điểm chung của ng\u0026#224;nh nghề Kỹ thuật, C\u0026#244;ng nghệ (1,5 điểm - mỗi \u0026#253; 0,5đ):\u003cbr\u003e   - Đối tượng lao động: Bao gồm vật liệu (kim loại, phi kim), năng lượng (điện, cơ), m\u0026#225;y m\u0026#243;c, thiết bị, phần mềm, quy tr\u0026#236;nh c\u0026#244;ng nghệ v\u0026#224; dữ liệu kỹ thuật.\u003cbr\u003e   - M\u0026#244;i trường l\u0026#224;m việc: Đa dạng (xưởng chế tạo, c\u0026#244;ng trường, ph\u0026#242;ng m\u0026#225;y, ph\u0026#242;ng thiết kế); thường xuy\u0026#234;n l\u0026#224;m việc với m\u0026#225;y m\u0026#243;c vận tốc cao, \u0026#225;p lực lớn, điện \u0026#225;p nguy hiểm, tiếng ồn hoặc h\u0026#243;a chất.\u003cbr\u003e   - Sản phẩm lao động: C\u0026#244;ng tr\u0026#236;nh, m\u0026#225;y m\u0026#243;c, chi tiết cơ kh\u0026#237;, mạch điện, phần mềm; đ\u0026#242;i hỏi độ ch\u0026#237;nh x\u0026#225;c tuyệt đối v\u0026#224; tu\u0026#226;n thủ c\u0026#225;c ti\u0026#234;u chuẩn TCVN/ISO.\u003cbr\u003e\u003cbr\u003e2. Y\u0026#234;u cầu bắt buộc về Phẩm chất Kỷ luật \u0026amp; An to\u0026#224;n Lao động (1,5 điểm):\u003cbr\u003e   - Y\u0026#234;u cầu nghi\u0026#234;m ngặt do m\u0026#244;i trường nguy cơ cao: Chỉ một sai s\u0026#243;t nhỏ trong thao t\u0026#225;c hoặc bỏ qua quy tr\u0026#236;nh an to\u0026#224;n c\u0026#243; thể dẫn đến tai nạn lao động nghi\u0026#234;m trọng (cuốn kẹt cơ kh\u0026#237;, giật điện, ch\u0026#225;y nổ).\u003cbr\u003e   - Bắt buộc tu\u0026#226;n thủ quy tr\u0026#236;nh c\u0026#244;ng nghệ: Kh\u0026#244;ng tự \u0026#253; thay đổi th\u0026#244;ng số kỹ thuật, kh\u0026#244;ng bỏ bước kiểm tra an to\u0026#224;n trước khi khởi động m\u0026#225;y.\u003cbr\u003e   - Trang bị bảo hộ lao động đầy đủ: Quần \u0026#225;o gọn g\u0026#224;ng, k\u0026#237;nh bảo hộ, găng tay c\u0026#225;ch điện/chống cắt, gi\u0026#224;y an to\u0026#224;n.\u003cbr\u003e   - Tinh thần tr\u0026#225;ch nhiệm với sản phẩm v\u0026#224; cộng đồng: Bảo đảm chất lượng chi tiết m\u0026#225;y/mạch điện để kh\u0026#244;ng g\u0026#226;y sự cố d\u0026#226;y chuyền khi đưa v\u0026#224;o sử dụng.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 3 (Mức Vận dụng cao - 3,0 điểm - Chuyển đổi số \u0026amp; CMCN 4.0)\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eCuộc C\u0026#225;ch mạng C\u0026#244;ng nghiệp 4.0 v\u0026#224; qu\u0026#225; tr\u0026#236;nh chuyển đổi số đang l\u0026#224;m thay đổi mạnh mẽ nền sản xuất. H\u0026#227;y so s\u0026#225;nh sự kh\u0026#225;c biệt về y\u0026#234;u cầu năng lực đối với người lao động kỹ thuật giữa nền sản xuất truyền thống v\u0026#224; nền sản xuất th\u0026#244;ng minh hiện đại. Theo em, học sinh THCS cần chuẩn bị những năng lực cốt l\u0026#245;i n\u0026#224;o ngay từ b\u0026#226;y giờ?\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eHƯỚNG DẪN CHẤM V\u0026#192; Đ\u0026#193;P \u0026#193;N CHUẨN:\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e1. So s\u0026#225;nh y\u0026#234;u cầu năng lực giữa Sản xuất Truyền thống v\u0026#224; Sản xuất Th\u0026#244;ng minh (1,8 điểm):\u003cbr\u003e   • Nền sản xuất truyền thống:\u003cbr\u003e     - Chủ yếu dựa v\u0026#224;o kỹ năng thao t\u0026#225;c tay ch\u0026#226;n, kinh nghiệm t\u0026#237;ch lũy c\u0026#225; nh\u0026#226;n.\u003cbr\u003e     - Vận dụng m\u0026#225;y m\u0026#243;c cơ kh\u0026#237; đơn lẻ, điều khiển thủ c\u0026#244;ng.\u003cbr\u003e     - \u0026#205;t y\u0026#234;u cầu về CNTT, l\u0026#224;m việc độc lập hoặc theo d\u0026#226;y chuyền đơn giản.\u003cbr\u003e   • Nền sản xuất th\u0026#244;ng minh 4.0 (Tự động h\u0026#243;a, AI, IoT, Big Data):\u003cbr\u003e     - Y\u0026#234;u cầu năng lực vận h\u0026#224;nh, lập tr\u0026#236;nh v\u0026#224; gi\u0026#225;m s\u0026#225;t hệ thống tự động (m\u0026#225;y CNC, robot c\u0026#244;ng nghiệp).\u003cbr\u003e     - Khả năng đọc ph\u0026#226;n t\u0026#237;ch dữ liệu số, xử l\u0026#253; sự cố hệ thống điều khiển th\u0026#244;ng minh.\u003cbr\u003e     - Kỹ năng giao tiếp số, l\u0026#224;m việc nh\u0026#243;m li\u0026#234;n ng\u0026#224;nh v\u0026#224; tư duy đổi mới s\u0026#225;ng tạo li\u0026#234;n tục.\u003cbr\u003e     - Khả năng tự học v\u0026#224; th\u0026#237;ch ứng nhanh với sự thay đổi chu kỳ c\u0026#244;ng nghệ ngắn.\u003cbr\u003e\u003cbr\u003e2. Chuẩn bị năng lực cốt l\u0026#245;i cho học sinh THCS (1,2 điểm):\u003cbr\u003e   - Năng lực C\u0026#244;ng nghệ \u0026amp; Tin học: Nắm chắc kiến thức c\u0026#244;ng nghệ phổ th\u0026#244;ng, l\u0026#224;m chủ c\u0026#225;c c\u0026#244;ng cụ phần mềm cơ bản, tư duy lập tr\u0026#236;nh/STEM.\u003cbr\u003e   - Năng lực Ngoại ngữ (Tiếng Anh): Để đọc t\u0026#224;i liệu kỹ thuật, hướng dẫn sử dụng thiết bị v\u0026#224; giao tiếp quốc tế.\u003cbr\u003e   - Kỹ năng mềm: Tư duy phản biện, kỹ năng giải quyết vấn đề kỹ thuật, l\u0026#224;m việc nh\u0026#243;m.\u003cbr\u003e   - Th\u0026#225;i độ tự học v\u0026#224; định hướng nghề nghiệp sớm: Chủ động t\u0026#236;m hiểu th\u0026#244;ng tin thị trường lao động, tự đ\u0026#225;nh gi\u0026#225; bản th\u0026#226;n để chọn tuyến đường học tập ph\u0026#249; hợp.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 4 (B\u0026#224;i tập T\u0026#236;nh huống Thực tiễn - 2,0 điểm)\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eT\u0026#236;nh huống: Bạn Nam (học sinh lớp 9) rất th\u0026#237;ch th\u0026#225;o lắp c\u0026#225;c thiết bị điện tử trong nh\u0026#224;, th\u0026#237;ch t\u0026#236;m hiểu sơ đồ mạch điện v\u0026#224; tự l\u0026#224;m c\u0026#225;c m\u0026#244; h\u0026#236;nh xe điều khiển từ xa. Tuy nhi\u0026#234;n, Nam lại ngại giao tiếp chốn đ\u0026#244;ng người v\u0026#224; kh\u0026#244;ng th\u0026#237;ch c\u0026#225;c c\u0026#244;ng việc viết l\u0026#225;ch. Bố mẹ Nam định hướng cho Nam thi v\u0026#224;o ng\u0026#224;nh Quản trị Kinh doanh. Em h\u0026#227;y dựa v\u0026#224;o l\u0026#253; thuyết ph\u0026#226;n t\u0026#237;ch phẩm chất, năng lực nghề nghiệp để đưa ra lời khuy\u0026#234;n ph\u0026#249; hợp cho Nam v\u0026#224; gia đ\u0026#236;nh.\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eHƯỚNG DẪN CHẤM V\u0026#192; Đ\u0026#193;P \u0026#193;N CHUẨN:\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e1. Ph\u0026#226;n t\u0026#237;ch đặc điểm c\u0026#225; nh\u0026#226;n của Nam (0,8 điểm):\u003cbr\u003e   - Điểm mạnh/Sở th\u0026#237;ch: Nam c\u0026#243; hứng th\u0026#250; tự nhi\u0026#234;n v\u0026#224; tư duy thực h\u0026#224;nh tốt với đồ kỹ thuật, điện tử, m\u0026#244; h\u0026#236;nh điều khiển (ph\u0026#249; hợp với nh\u0026#243;m t\u0026#237;nh c\u0026#225;ch Kỹ thuật/Thiết kế điện - điện tử - tự động h\u0026#243;a).\u003cbr\u003e   - Hạn chế: Hướng nội, ngại giao tiếp chốn đ\u0026#244;ng người, kh\u0026#244;ng th\u0026#237;ch c\u0026#244;ng việc h\u0026#224;nh ch\u0026#237;nh/viết l\u0026#225;ch.\u003cbr\u003e\u003cbr\u003e2. Đ\u0026#225;nh gi\u0026#225; t\u0026#237;nh ph\u0026#249; hợp với định hướng Quản trị Kinh doanh (0,4 điểm):\u003cbr\u003e   - Ng\u0026#224;nh Quản trị Kinh doanh đ\u0026#242;i hỏi cao về kỹ năng giao tiếp, đ\u0026#224;m ph\u0026#225;n, hướng ngoại v\u0026#224; xử l\u0026#253; văn bản/hợp đồng. Ng\u0026#224;nh n\u0026#224;y kh\u0026#244;ng ph\u0026#249; hợp với sở th\u0026#237;ch v\u0026#224; t\u0026#237;nh c\u0026#225;ch hiện tại của Nam, dễ dẫn đến ch\u0026#225;n nản nếu gượng \u0026#233;p.\u003cbr\u003e\u003cbr\u003e3. Lời khuy\u0026#234;n định hướng nghề nghiệp khoa học (0,8 điểm):\u003cbr\u003e   - Khuy\u0026#234;n Nam n\u0026#234;n trao đổi thẳng thắn với gia đ\u0026#236;nh về nguyện vọng v\u0026#224; sở th\u0026#237;ch thực tế của bản th\u0026#226;n.\u003cbr\u003e   - Đề xuất c\u0026#225;c ng\u0026#224;nh nghề ph\u0026#249; hợp với năng lực Nam: Kỹ thuật Điện - Điện tử, C\u0026#244;ng nghệ Tự động h\u0026#243;a, Kỹ thuật M\u0026#225;y t\u0026#237;nh hoặc Cơ điện tử.\u003cbr\u003e   - Nhắc nhở Nam: D\u0026#249; chọn ng\u0026#224;nh kỹ thuật, Nam vẫn cần r\u0026#232;n luyện th\u0026#234;m kỹ năng giao tiếp nh\u0026#243;m cơ bản v\u0026#224; ngoại ngữ để đ\u0026#225;p ứng y\u0026#234;u cầu c\u0026#244;ng việc hiện đại.\u003c/p\u003e","8":"\u003ch2\u003eCHUYÊN ĐỀ 8: GIÁO DỤC KỸ THUẬT, CÔNG NGHỆ TRONG HỆ THỐNG GIÁO DỤC QUỐC DÂN\u003c/h2\u003e\u003cp\u003e\u003cstrong\u003ePHẦN I: MỤC TI\u0026#202;U B\u0026#192;I HỌC V\u0026#192; CHUẨN NĂNG LỰC HSG\u003c/strong\u003e\u003c/p\u003e\u003cp\u003eTheo định hướng thi HSG THCS m\u0026#244;n C\u0026#244;ng nghệ cấp tỉnh (C\u0026#244;ng văn 730/SGDĐT-GDPT Vĩnh Long) v\u0026#224; SGK/SGV C\u0026#244;ng nghệ 9 - Định hướng nghề nghiệp, Chuy\u0026#234;n đề 8 trang bị cho học sinh c\u0026#225;c kiến thức v\u0026#224; năng lực cốt l\u0026#245;i sau:\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eVề kiến thức: \u003c/strong\u003eNắm vững cấu tr\u0026#250;c Khung cơ cấu Hệ thống Gi\u0026#225;o dục Quốc d\u0026#226;n Việt Nam (Luật Gi\u0026#225;o dục 2019); ph\u0026#226;n biệt r\u0026#245; 4 cấp học v\u0026#224; tr\u0026#236;nh độ đ\u0026#224;o tạo (Mầm non, Phổ th\u0026#244;ng, Gi\u0026#225;o dục nghề nghiệp, Gi\u0026#225;o dục đại học); hiểu r\u0026#245; c\u0026#225;c mốc ph\u0026#226;n luồng v\u0026#224; cơ hội gi\u0026#225;o dục kỹ thuật - c\u0026#244;ng nghệ.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eVề kỹ năng ph\u0026#226;n t\u0026#237;ch sơ đồ \u0026amp; lập luận: \u003c/strong\u003eĐọc v\u0026#224; ph\u0026#226;n t\u0026#237;ch th\u0026#224;nh thạo Sơ đồ Luồng gi\u0026#225;o dục trong Hệ thống GDQD; so s\u0026#225;nh được c\u0026#225;c tuyến đường ph\u0026#225;t triển sau THCS (v\u0026#224;o THPT, Trung cấp/GDNN, M\u0026#244; h\u0026#236;nh 9+ vừa học văn h\u0026#243;a vừa học nghề); đ\u0026#225;nh gi\u0026#225; cơ hội học tập c\u0026#225;c ng\u0026#224;nh nghề kỹ thuật.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eVề năng lực giải quyết t\u0026#236;nh huống (Vận dụng cao): \u003c/strong\u003eC\u0026#243; khả năng phản biện tư duy lệch lạc về \u0026#39;bằng cấp\u0026#39;, giải quyết c\u0026#225;c b\u0026#224;i tập t\u0026#236;nh huống tư vấn ph\u0026#226;n luồng hướng nghiệp cho học sinh THCS dựa tr\u0026#234;n năng lực, ho\u0026#224;n cảnh gia đ\u0026#236;nh v\u0026#224; nhu cầu nh\u0026#226;n lực x\u0026#227; hội.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003ePHẦN II: HỆ THỐNG L\u0026#221; THUYẾT CHUY\u0026#202;N S\u0026#194;U L\u0026#221; LUẬN V\u0026#192; PH\u0026#194;N LUỒNG\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e1. Khung Cơ cấu Hệ thống Gi\u0026#225;o dục Quốc d\u0026#226;n Việt Nam (Luật Gi\u0026#225;o dục 2019)\u003c/strong\u003e\u003c/p\u003e\u003cp\u003eHệ thống Gi\u0026#225;o dục Quốc d\u0026#226;n Việt Nam l\u0026#224; một hệ thống mở, linh hoạt, li\u0026#234;n th\u0026#244;ng, bảo đảm quyền học tập suốt đời của mọi người d\u0026#226;n, được chia th\u0026#224;nh c\u0026#225;c bậc học v\u0026#224; tr\u0026#236;nh độ đ\u0026#224;o tạo ch\u0026#237;nh:\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eBậc học / Cấp học\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#225;c cấp độ / Tr\u0026#236;nh độ đ\u0026#224;o tạo\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eĐặc điểm \u0026amp; Vai tr\u0026#242; Gi\u0026#225;o dục Kỹ thuật - C\u0026#244;ng nghệ\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eGi\u0026#225;o dục Mầm non \u0026amp; Phổ th\u0026#244;ng\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e• Mầm non (Nh\u0026#224; trẻ, Mẫu gi\u0026#225;o)\u003cbr\u003e• Tiểu học (Lớp 1-5)\u003cbr\u003e• THCS (Lớp 6-9)\u003cbr\u003e• THPT (Lớp 10-12)\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e• H\u0026#236;nh th\u0026#224;nh tri thức c\u0026#244;ng nghệ phổ th\u0026#244;ng, tư duy thiết kế, trải nghiệm STEM.\u003cbr\u003e• Cấp THCS l\u0026#224; giai đoạn Gi\u0026#225;o dục cơ bản \u0026amp; PH\u0026#194;N LUỒNG HƯỚNG NGHIỆP cốt l\u0026#245;i.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eGi\u0026#225;o dục Nghề nghiệp (GDNN)\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e• Sơ cấp\u003cbr\u003e• Trung cấp\u003cbr\u003e• Cao đẳng\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e• Đ\u0026#224;o tạo nh\u0026#226;n lực trực tiếp cho sản xuất, kinh doanh, dịch vụ kỹ thuật.\u003cbr\u003e• Đ\u0026#224;o tạo thực h\u0026#224;nh, kỹ năng nghề nghiệp thực tế; đ\u0026#225;p ứng thị trường lao động.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eGi\u0026#225;o dục Đại học\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e• Đại học (Cử nh\u0026#226;n, Kỹ sư)\u003cbr\u003e• Thạc sĩ\u003cbr\u003e• Tiến sĩ\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e• Đ\u0026#224;o tạo nh\u0026#226;n lực tr\u0026#236;nh độ cao, nghi\u0026#234;n cứu ph\u0026#225;t triển c\u0026#244;ng nghệ mới, thiết kế hệ thống, quản l\u0026#253; kỹ thuật cao cấp.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eGi\u0026#225;o dục Thường xuy\u0026#234;n\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e• X\u0026#243;a m\u0026#249; chữ, Bổ t\u0026#250;c VH\u003cbr\u003e• Đ\u0026#224;o tạo bồi dưỡng ngắn hạn\u003cbr\u003e• Học từ xa, li\u0026#234;n th\u0026#244;ng\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e• Tạo cơ hội học tập suốt đời, cập nhật kiến thức kỹ thuật mới cho người lao động, chuyển đổi nghề nghiệp linh hoạt.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003cp\u003e\u003cstrong\u003e2. Cơ chế Ph\u0026#226;n luồng Học sinh sau THCS v\u0026#224; c\u0026#225;c Tuyến đường Ph\u0026#225;t triển\u003c/strong\u003e\u003c/p\u003e\u003cp\u003ePh\u0026#226;n luồng trong gi\u0026#225;o dục l\u0026#224; biện ph\u0026#225;p tổ chức hoạt động gi\u0026#225;o dục tr\u0026#234;n cơ sở thực hiện hướng nghiệp, tạo điều kiện để học sinh tốt nghiệp THCS tiếp tục học tập ở cấp học, tr\u0026#236;nh độ cao hơn hoặc học nghề ph\u0026#249; hợp với năng lực, sở trường, ho\u0026#224;n cảnh c\u0026#225; nh\u0026#226;n v\u0026#224; nhu cầu x\u0026#227; hội.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eSơ đồ Luồng Gi\u0026#225;o dục \u0026amp; C\u0026#225;c Hướng đi sau Tốt nghiệp THCS:\u003c/strong\u003e\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eM\u0026#212; H\u0026#204;NH PH\u0026#194;N LUỒNG HỌC SINH SAU THCS\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e\u003cem\u003eSƠ ĐỒ TỔNG QU\u0026#193;T C\u0026#193;C TUYẾN ĐƯỜNG SAU THCS:\u003c/em\u003e\u003cem\u003e\u003cbr\u003e                     ┌──► 1. HỌC THPT (Phổ th\u0026#244;ng) ──► Kỳ thi tốt nghiệp THPT ──► Đại học / Cao đẳng\u003c/em\u003e\u003cem\u003e\u003cbr\u003e                     │\u003c/em\u003e\u003cem\u003e\u003cbr\u003eTỐT NGHIỆP THCS ─────┼──► 2. HỌC TRUNG CẤP / GDNN (M\u0026#244; h\u0026#236;nh 9+) ──► Bằng Trung cấp + Chứng nhận VH ──► Cao đẳng / Đại học li\u0026#234;n th\u0026#244;ng\u003c/em\u003e\u003cem\u003e\u003cbr\u003e(Hết Lớp 9)          │\u003c/em\u003e\u003cem\u003e\u003cbr\u003e                     ├──► 3. HỌC TẠI TRUNG T\u0026#194;M GDNN - GDTX ──► Bổ t\u0026#250;c VH THPT / Học nghề ──► Đi l\u0026#224;m / Học tiếp\u003c/em\u003e\u003cem\u003e\u003cbr\u003e                     │\u003c/em\u003e\u003cem\u003e\u003cbr\u003e                     └──► 4. THAM GIA THỊ TRƯỜNG LAO ĐỘNG (Lao động sơ cấp, học nghề truyền thống)\u003c/em\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003cp\u003e\u003cstrong\u003eSo s\u0026#225;nh Chi tiết c\u0026#225;c Tuyến đường Lựa chọn sau THCS:\u003c/strong\u003e\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eTuyến đường\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eĐặc điểm chương tr\u0026#236;nh\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eƯu điểm \u0026amp; Cơ hội\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eĐối tượng ph\u0026#249; hợp\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eTuyến 1: Học THPT (Trọng t\u0026#226;m học thuật)\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eHọc 100% chương tr\u0026#236;nh văn h\u0026#243;a phổ th\u0026#244;ng n\u0026#226;ng cao (Chương tr\u0026#236;nh GDPT 2018 định hướng nghề nghiệp).\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e• Nền tảng văn h\u0026#243;a vững chắc.\u003cbr\u003e• Lựa chọn đa dạng c\u0026#225;c ng\u0026#224;nh đại học nghi\u0026#234;n cứu/kỹ thuật cao.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eHọc sinh c\u0026#243; năng lực học tập kh\u0026#225;/giỏi, học lực văn h\u0026#243;a tốt, mong muốn theo con đường nghi\u0026#234;n cứu/đại học chuy\u0026#234;n s\u0026#226;u.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eTuyến 2: Học Trung cấp / GDNN (M\u0026#244; h\u0026#236;nh 9+)\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eVừa học nghề b\u0026#224;i bản (đạt bằng Trung cấp) vừa học c\u0026#225;c m\u0026#244;n văn h\u0026#243;a THPT cốt l\u0026#245;i (3-4 m\u0026#244;n).\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e• Tiết kiệm thời gian (18-19 tuổi c\u0026#243; bằng nghề).\u003cbr\u003e• Miễn học ph\u0026#237; học nghề sau THCS.\u003cbr\u003e• Dễ c\u0026#243; việc l\u0026#224;m ngay, li\u0026#234;n th\u0026#244;ng Cao đẳng/Đại học.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eHọc sinh c\u0026#243; sở th\u0026#237;ch thực h\u0026#224;nh kỹ thuật, mong muốn đi l\u0026#224;m sớm, gia đ\u0026#236;nh c\u0026#243; điều kiện kinh tế trung b\u0026#236;nh/kh\u0026#243; khăn, lực học văn h\u0026#243;a trung b\u0026#236;nh.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eTuyến 3: Trung t\u0026#226;m GDNN - GDTX\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eHọc chương tr\u0026#236;nh GDTX cấp THPT kết hợp học chứng chỉ nghề.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e• \u0026#193;p lực học tập văn h\u0026#243;a vừa phải.\u003cbr\u003e• Linh hoạt thời gian, chi ph\u0026#237; thấp.\u003cbr\u003e• Vẫn tham gia dự thi Tốt nghiệp THPT.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eHọc sinh cần m\u0026#244;i trường học tập linh hoạt, muốn vừa ho\u0026#224;n th\u0026#224;nh chương tr\u0026#236;nh trung học vừa t\u0026#237;ch lũy kỹ năng lao động.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003cp\u003e\u003cstrong\u003e3. \u0026#221; nghĩa chiến lược của việc Ph\u0026#226;n luồng đối với C\u0026#225; nh\u0026#226;n v\u0026#224; X\u0026#227; hội\u003c/strong\u003e\u003c/p\u003e\u003cp\u003eC\u0026#244;ng văn 730 v\u0026#224; Đề thi HSG Vĩnh Long nhấn mạnh b\u0026#224;i tập l\u0026#253; luận y\u0026#234;u cầu học sinh chứng minh t\u0026#237;nh đ\u0026#250;ng đắn của ch\u0026#237;nh s\u0026#225;ch ph\u0026#226;n luồng:\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eĐối với c\u0026#225; nh\u0026#226;n người học: \u003c/strong\u003eTr\u0026#225;nh l\u0026#227;ng ph\u0026#237; thời gian, tiền bạc v\u0026#224; sức lực khi theo đuổi con đường học tập kh\u0026#244;ng ph\u0026#249; hợp với năng lực; gi\u0026#250;p ph\u0026#225;t huy tối đa sở trường thực h\u0026#224;nh; nhanh ch\u0026#243;ng đạt sự độc lập t\u0026#224;i ch\u0026#237;nh v\u0026#224; tự tin trong cuộc sống.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eĐối với gia đ\u0026#236;nh: \u003c/strong\u003eGiảm g\u0026#225;nh nặng t\u0026#224;i ch\u0026#237;nh nu\u0026#244;i con ăn học k\u0026#233;o d\u0026#224;i; tạo nguồn thu nhập sớm cho gia đ\u0026#236;nh; giảm \u0026#225;p lực t\u0026#226;m l\u0026#253; kỳ vọng kh\u0026#244;ng thực tế.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eĐối với x\u0026#227; hội \u0026amp; Nền kinh tế: \u003c/strong\u003eKhắc phục t\u0026#236;nh trạng lệch pha \u0026#39;thừa thầy thiếu thợ\u0026#39; trong thị trường lao động; c\u0026#226;n bằng cơ cấu nguồn nh\u0026#226;n lực (kỹ sư - kỹ thuật vi\u0026#234;n - thợ l\u0026#224;nh nghề); n\u0026#226;ng cao năng suất lao động quốc gia.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003ePHẦN III: NG\u0026#194;N H\u0026#192;NG C\u0026#194;U HỎI V\u0026#192; B\u0026#192;I TẬP PH\u0026#194;N H\u0026#211;A (K\u0026#200;M Đ\u0026#193;P \u0026#193;N CHUẨN)\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e1. Ma trận đề thi HSG Chuy\u0026#234;n đề 8\u003c/strong\u003e\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eMức độ nhận thức\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eDạng c\u0026#226;u hỏi\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eTrọng t\u0026#226;m kiến thức kiểm tra\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eThang điểm chuẩn\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eNhận biết (20%)\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eTr\u0026#236;nh b\u0026#224;y / Liệt k\u0026#234;\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eCấu tr\u0026#250;c Khung cơ cấu Hệ thống GDQD Việt Nam theo Luật Gi\u0026#225;o dục 2019.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e0,5 - 0,75 điểm\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eTh\u0026#244;ng hiểu (30%)\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003ePh\u0026#226;n t\u0026#237;ch / So s\u0026#225;nh\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eBản chất ph\u0026#226;n luồng sau THCS; so s\u0026#225;nh tuyến đường THPT vs Trung cấp (M\u0026#244; h\u0026#236;nh 9+).\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e0,75 - 1,0 điểm\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eVận dụng (30%)\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eSơ đồ h\u0026#243;a / Biện luận\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eVẽ sơ đồ luồng gi\u0026#225;o dục; giải th\u0026#237;ch \u0026#253; nghĩa kinh tế - x\u0026#227; hội của ph\u0026#226;n luồng.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e0,75 - 1,0 điểm\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003eVận dụng cao (20%)\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eGiải quyết t\u0026#236;nh huống\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eTư vấn chọn đường học tập cho học sinh sau THCS; phản biện t\u0026#226;m l\u0026#253; \u0026#39;thượng t\u0026#244;n bằng cấp\u0026#39;.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e0,5 - 0,75 điểm\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003cp\u003e\u003cstrong\u003e2. C\u0026#226;u hỏi \u0026amp; Đ\u0026#225;p \u0026#225;n chi tiết chuẩn biểu điểm Sở GDĐT\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 1 (3.0 điểm - Dạng L\u0026#253; luận \u0026amp; Ph\u0026#226;n t\u0026#237;ch Sơ đồ GDQD):\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003ea) H\u0026#227;y vẽ sơ đồ v\u0026#224; tr\u0026#236;nh b\u0026#224;y c\u0026#225;c bậc học, tr\u0026#236;nh độ đ\u0026#224;o tạo trong Khung cơ cấu Hệ thống Gi\u0026#225;o dục Quốc d\u0026#226;n Việt Nam hiện nay.\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003eb) Cấp học THCS đ\u0026#243;ng vai tr\u0026#242; g\u0026#236; trong hệ thống gi\u0026#225;o dục quốc d\u0026#226;n? Tại sao n\u0026#243;i ph\u0026#226;n luồng sau THCS l\u0026#224; một bước ngoặt quan trọng đối với học sinh?\u003c/strong\u003e\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eĐ\u0026#193;P \u0026#193;N C\u0026#194;U 1 (3.0 ĐIỂM)\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e\u003cem\u003eHƯỚNG DẪN CHẤM V\u0026#192; BẢNG ĐIỂM CHI TIẾT C\u0026#194;U 1:\u003c/em\u003e\u003cem\u003e\u003cbr\u003e\u003c/em\u003e\u003cem\u003e\u003cbr\u003ea) Khung cơ cấu Hệ thống GDQD (1.5 điểm):\u003c/em\u003e\u003cem\u003e\u003cbr\u003e• Vẽ/Tr\u0026#236;nh b\u0026#224;y đ\u0026#250;ng 4 bậc học ch\u0026#237;nh (0.25đ/bậc = 1.0đ):\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   1. Gi\u0026#225;o dục Mầm non: Mẫu gi\u0026#225;o, Nh\u0026#224; trẻ.\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   2. Gi\u0026#225;o dục Phổ th\u0026#244;ng: Tiểu học (5 năm), THCS (4 năm), THPT (3 năm).\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   3. Gi\u0026#225;o dục Nghề nghiệp: Sơ cấp, Trung cấp, Cao đẳng.\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   4. Gi\u0026#225;o dục Đại học: Đại học (Cử nh\u0026#226;n/Kỹ sư), Thạc sĩ, Tiến sĩ.\u003c/em\u003e\u003cem\u003e\u003cbr\u003e• N\u0026#234;u được t\u0026#237;nh đặc th\u0026#249; của Gi\u0026#225;o dục Thường xuy\u0026#234;n (li\u0026#234;n th\u0026#244;ng, học suốt đời) (0.5đ).\u003c/em\u003e\u003cem\u003e\u003cbr\u003e\u003c/em\u003e\u003cem\u003e\u003cbr\u003eb) Vai tr\u0026#242; của THCS v\u0026#224; \u0026#221; nghĩa Ph\u0026#226;n luồng (1.5 điểm):\u003c/em\u003e\u003cem\u003e\u003cbr\u003e• Vai tr\u0026#242; THCS (0.5đ): Cấp học thuộc giai đoạn Gi\u0026#225;o dục Cơ bản. Cung cấp tri thức phổ th\u0026#244;ng to\u0026#224;n diện, đồng thời thực hiện gi\u0026#225;o dục hướng nghiệp để chuẩn bị ph\u0026#226;n luồng sau lớp 9.\u003c/em\u003e\u003cem\u003e\u003cbr\u003e• L\u0026#237; do ph\u0026#226;n luồng sau THCS l\u0026#224; bước ngoặt (1.0đ):\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   + Học sinh kết th\u0026#250;c giai đoạn gi\u0026#225;o dục bắt buộc to\u0026#224;n diện, bắt đầu c\u0026#243; sự ph\u0026#226;n h\u0026#243;a r\u0026#245; rệt về năng lực văn h\u0026#243;a v\u0026#224; thi\u0026#234;n hướng (l\u0026#253; thuyết vs thực h\u0026#224;nh).\u003c/em\u003e\u003cem\u003e\u003cbr\u003e\u003c/em\u003e\u003cem\u003e   + Lần đầu ti\u0026#234;n học sinh v\u0026#224; gia đ\u0026#236;nh phải đưa ra quyết định lựa chọn tuyến đường học tập kh\u0026#225;c nhau (THPT vs Học nghề M\u0026#244; h\u0026#236;nh 9+ vs GDTX).\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   + Quyết định n\u0026#224;y ảnh hưởng trực tiếp đến thời gian gia nhập thị trường lao động, chi ph\u0026#237; đ\u0026#224;o tạo v\u0026#224; sự nghiệp tương lai.\u003c/em\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 2 (3.0 điểm - Dạng So s\u0026#225;nh Tuyến đường \u0026amp; Ph\u0026#226;n t\u0026#237;ch M\u0026#244; h\u0026#236;nh 9+):\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eHiện nay, b\u0026#234;n cạnh con đường truyền thống học l\u0026#234;n THPT, ch\u0026#237;nh s\u0026#225;ch gi\u0026#225;o dục đang khuyến kh\u0026#237;ch m\u0026#244; h\u0026#236;nh \u0026#39;Ph\u0026#226;n luồng 9+\u0026#39; (học sinh tốt nghiệp THCS v\u0026#224;o học thẳng Trung cấp nghề kết hợp học văn h\u0026#243;a THPT).\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003ea) H\u0026#227;y so s\u0026#225;nh ưu điểm v\u0026#224; hạn chế giữa tuyến đường (1) Tiếp tục học THPT v\u0026#224; tuyến đường (2) Học Trung cấp nghề theo M\u0026#244; h\u0026#236;nh 9+.\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003eb) Theo em, những học sinh c\u0026#243; đặc điểm như thế n\u0026#224;o th\u0026#236; n\u0026#234;n lựa chọn M\u0026#244; h\u0026#236;nh 9+?\u003c/strong\u003e\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eĐ\u0026#193;P \u0026#193;N C\u0026#194;U 2 (3.0 ĐIỂM)\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e\u003cem\u003eHƯỚNG DẪN CHẤM V\u0026#192; BẢNG ĐIỂM CHI TIẾT C\u0026#194;U 2:\u003c/em\u003e\u003cem\u003e\u003cbr\u003e\u003c/em\u003e\u003cem\u003e\u003cbr\u003ea) So s\u0026#225;nh hai tuyến đường (2.0 điểm):\u003c/em\u003e\u003cem\u003e\u003cbr\u003e• Tuyến 1: Tiếp tục học THPT (1.0đ):\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   + Ưu điểm: Nền tảng học thuật vững chắc; cơ hội thi v\u0026#224;o tất cả c\u0026#225;c trường Đại học top đầu; t\u0026#226;m l\u0026#253; x\u0026#227; hội quen thuộc (0.5đ).\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   + Hạn chế: \u0026#193;p lực thi cử cao; thời gian đ\u0026#224;o tạo k\u0026#233;o d\u0026#224;i (3 năm THPT + 4 năm Đại học); chi ph\u0026#237; nu\u0026#244;i ăn học lớn; nguy cơ thất nghiệp nếu chọn sai ng\u0026#224;nh đại học (0.5đ).\u003c/em\u003e\u003cem\u003e\u003cbr\u003e• Tuyến 2: Học Trung cấp M\u0026#244; h\u0026#236;nh 9+ (1.0đ):\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   + Ưu điểm: Đa lợi \u0026#237;ch - Tiết kiệm thời gian (18 tuổi c\u0026#243; bằng Nghề + chứng nhận VH THPT); được miễn 100% học ph\u0026#237; học nghề sau THCS; sớm c\u0026#243; việc l\u0026#224;m v\u0026#224; thu nhập; vẫn được li\u0026#234;n th\u0026#244;ng Cao đẳng/Đại học khi đủ điều kiện (0.5đ).\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   + Hạn chế: Khối lượng học tập k\u0026#233;p (vừa học nghề vừa học văn h\u0026#243;a); tư tưởng định kiến x\u0026#227; hội về \u0026#39;đi học nghề\u0026#39; vẫn c\u0026#242;n tồn tại ở một số nơi (0.5đ).\u003c/em\u003e\u003cem\u003e\u003cbr\u003e\u003c/em\u003e\u003cem\u003e\u003cbr\u003eb) Đối tượng học sinh ph\u0026#249; hợp với M\u0026#244; h\u0026#236;nh 9+ (1.0 điểm):\u003c/em\u003e\u003cem\u003e\u003cbr\u003e• Học sinh c\u0026#243; học lực văn h\u0026#243;a ở mức Trung b\u0026#236;nh - Kh\u0026#225;, nhưng nổi trội về kỹ năng vận động/thực h\u0026#224;nh (0.25đ).\u003c/em\u003e\u003cem\u003e\u003cbr\u003e• Học sinh x\u0026#225;c định r\u0026#245; sở th\u0026#237;ch nghề nghiệp kỹ thuật cụ thể (sửa chữa \u0026#244; t\u0026#244;, điện tử, nấu ăn, thiết kế đồ họa...) (0.25đ).\u003c/em\u003e\u003cem\u003e\u003cbr\u003e• Học sinh c\u0026#243; ho\u0026#224;n cảnh gia đ\u0026#236;nh kinh tế kh\u0026#243; khăn, muốn sớm ra trường đi l\u0026#224;m phụ gi\u0026#250;p gia đ\u0026#236;nh (0.25đ).\u003c/em\u003e\u003cem\u003e\u003cbr\u003e• Học sinh muốn tự chủ t\u0026#224;i ch\u0026#237;nh sớm v\u0026#224; c\u0026#243; định hướng ph\u0026#225;t triển tay nghề th\u0026#224;nh thợ giỏi (0.25đ).\u003c/em\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 3 (2.0 điểm - Dạng T\u0026#236;nh huống Thực tiễn \u0026amp; Phản biện Tư duy Bằng cấp):\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eT\u0026#236;nh huống: Nam l\u0026#224; học sinh lớp 9 c\u0026#243; lực học văn h\u0026#243;a trung b\u0026#236;nh, nhưng em rất kh\u0026#233;o tay, th\u0026#237;ch th\u0026#225;o lắp thiết bị điện tử v\u0026#224; mơ ước trở th\u0026#224;nh thợ kỹ thuật điện lạnh giỏi. Bố mẹ Nam nhất quyết bắt em phải thi v\u0026#224;o trường THPT c\u0026#244;ng lập top đầu của tỉnh, với quan điểm: \u0026#39;Phải v\u0026#224;o được THPT rồi học Đại học th\u0026#236; mới c\u0026#243; tương lai, đi học nghề sau lớp 9 l\u0026#224; thất bại, xấu hổ với họ h\u0026#224;ng\u0026#39;.\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003ea) Dựa v\u0026#224;o kiến thức về Hệ thống Gi\u0026#225;o dục Quốc d\u0026#226;n v\u0026#224; ph\u0026#226;n luồng, em h\u0026#227;y nhận x\u0026#233;t về quan điểm của bố mẹ Nam.\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003eb) Nếu l\u0026#224; Nam, em sẽ đ\u0026#243;ng g\u0026#243;p \u0026#253; kiến với bố mẹ như thế n\u0026#224;o để thuyết phục bố mẹ ủng hộ nguyện vọng học tập của m\u0026#236;nh?\u003c/strong\u003e\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eĐ\u0026#193;P \u0026#193;N C\u0026#194;U 3 (2.0 ĐIỂM)\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e\u003cem\u003eHƯỚNG DẪN CHẤM V\u0026#192; BẢNG ĐIỂM CHI TIẾT C\u0026#194;U 3:\u003c/em\u003e\u003cem\u003e\u003cbr\u003e\u003c/em\u003e\u003cem\u003e\u003cbr\u003ea) Ph\u0026#226;n t\u0026#237;ch quan điểm của bố mẹ Nam (1.0 điểm):\u003c/em\u003e\u003cem\u003e\u003cbr\u003e• Quan điểm của bố mẹ Nam l\u0026#224; sai lầm v\u0026#224; mang nặng tư tưởng \u0026#39;thượng t\u0026#244;n bằng cấp\u0026#39;, lệch lạc so với thực tế thị trường lao động hiện đại (0.5đ).\u003c/em\u003e\u003cem\u003e\u003cbr\u003e• L\u0026#237; do ph\u0026#226;n t\u0026#237;ch (0.5đ):\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   + \u0026#193;p đặt nguyện vọng vượt qu\u0026#225; sức học văn h\u0026#243;a của Nam (lực học trung b\u0026#236;nh kh\u0026#243; theo nổi THPT top đầu) dễ dẫn đến căng thẳng t\u0026#226;m l\u0026#253;, ch\u0026#225;n học.\u003c/em\u003e\u003cem\u003e\u003cbr\u003e   + Chưa thấy được gi\u0026#225; trị của Gi\u0026#225;o dục Nghề nghiệp: Học nghề kh\u0026#244;ng phải l\u0026#224; \u0026#39;thất bại\u0026#39; m\u0026#224; l\u0026#224; tuyến đường đ\u0026#224;o tạo nh\u0026#226;n lực thực h\u0026#224;nh được Nh\u0026#224; nước khuyến kh\u0026#237;ch; x\u0026#227; hội hiện nay rất cần thợ kỹ thuật giỏi hơn l\u0026#224; cử nh\u0026#226;n/kỹ sư thiếu kỹ năng thực tế.\u003c/em\u003e\u003cem\u003e\u003cbr\u003e\u003c/em\u003e\u003cem\u003e\u003cbr\u003eb) Giải ph\u0026#225;p đối thoại \u0026amp; thuyết phục của Nam (1.0 điểm):\u003c/em\u003e\u003cem\u003e\u003cbr\u003e• B\u0026#224;y tỏ sự t\u0026#244;n trọng mong muốn của bố mẹ, đồng thời ph\u0026#226;n t\u0026#237;ch r\u0026#245; năng lực thực tế của bản th\u0026#226;n (thực tế lực học v\u0026#224; đam m\u0026#234; kỹ thuật) (0.25đ).\u003c/em\u003e\u003cem\u003e\u003cbr\u003e• Giới thiệu cho bố mẹ biết về M\u0026#244; h\u0026#236;nh Ph\u0026#226;n luồng 9+ (học Trung cấp nghề Điện lạnh vừa được miễn học ph\u0026#237;, vừa học văn h\u0026#243;a THPT, ra trường 18 tuổi c\u0026#243; việc l\u0026#224;m ngay) (0.25đ).\u003c/em\u003e\u003cem\u003e\u003cbr\u003e• Khẳng định con đường li\u0026#234;n th\u0026#244;ng: Học Trung cấp kh\u0026#244;ng kh\u0026#233;p lại cơ hội học cao hơn, Nam ho\u0026#224;n to\u0026#224;n c\u0026#243; thể li\u0026#234;n th\u0026#244;ng l\u0026#234;n Cao đẳng/Đại học Kỹ thuật sau khi c\u0026#243; bằng Trung cấp v\u0026#224; thu nhập ổn định (0.25đ).\u003c/em\u003e\u003cem\u003e\u003cbr\u003e• Lập kế hoạch học tập cụ thể, cam kết nỗ lực r\u0026#232;n luyện để chứng minh quyết t\u0026#226;m với bố mẹ (0.25đ).\u003c/em\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e","9":"\u003ch2\u003eCHUYÊN ĐỀ 9: THỊ TRƯỜNG LAO ĐỘNG KỸ THUẬT, CÔNG NGHỆ TẠI VIỆT NAM\u003c/h2\u003e\u003ch3\u003eI. KHUNG LÝ THUYẾT VÀ BẢN CHẤT KHOA HỌC CHUYÊN SÂU\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003e1. Kh\u0026#225;i niệm Cốt l\u0026#245;i v\u0026#224; Cơ chế Hoạt động của Thị trường Lao động\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eKh\u0026#225;i niệm chung: \u003c/strong\u003eThị trường lao động l\u0026#224; nơi diễn ra c\u0026#225;c hoạt động mua b\u0026#225;n, trao đổi sức lao động giữa người lao động (b\u0026#234;n cung) v\u0026#224; người sử dụng lao động (b\u0026#234;n cầu) th\u0026#244;ng qua thỏa thuận về tiền lương v\u0026#224; c\u0026#225;c điều kiện l\u0026#224;m việc.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eCung lao động kỹ thuật, c\u0026#244;ng nghệ (Labor Supply): \u003c/strong\u003eTập hợp to\u0026#224;n bộ những người trong độ tuổi lao động c\u0026#243; khả năng lao động, đang c\u0026#243; việc l\u0026#224;m hoặc đang t\u0026#236;m kiếm việc l\u0026#224;m trong lĩnh vực kỹ thuật, c\u0026#244;ng nghệ. Cung lao động chịu ảnh hưởng bởi quy m\u0026#244; d\u0026#226;n số, cơ cấu tuổi, chất lượng hệ thống gi\u0026#225;o dục - đ\u0026#224;o tạo v\u0026#224; ch\u0026#237;nh s\u0026#225;ch ph\u0026#226;n luồng.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eCầu lao động kỹ thuật, c\u0026#244;ng nghệ (Labor Demand): \u003c/strong\u003eTổng nhu cầu tuyển dụng người lao động c\u0026#243; tr\u0026#236;nh độ chuy\u0026#234;n m\u0026#244;n kỹ thuật, c\u0026#244;ng nghệ của c\u0026#225;c cơ quan, doanh nghiệp, nh\u0026#224; m\u0026#225;y, tập đo\u0026#224;n trong v\u0026#224; ngo\u0026#224;i nước. Cầu lao động phụ thuộc trực tiếp v\u0026#224;o tốc độ ph\u0026#225;t triển kinh tế, mức độ ứng dụng c\u0026#244;ng nghệ v\u0026#224; định hướng c\u0026#244;ng nghiệp h\u0026#243;a - hiện đại h\u0026#243;a.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eGi\u0026#225; cả lao động (Labor Price/Wage): \u003c/strong\u003eMức tiền lương, tiền c\u0026#244;ng v\u0026#224; c\u0026#225;c khoản phụ cấp/ph\u0026#250;c lợi m\u0026#224; người sử dụng lao động trả cho người lao động. Gi\u0026#225; cả lao động được x\u0026#225;c định bởi sự tương quan Cung - Cầu, gi\u0026#225; trị sức lao động, tr\u0026#236;nh độ chuy\u0026#234;n m\u0026#244;n, năng suất lao động v\u0026#224; t\u0026#237;nh chất phức tạp của c\u0026#244;ng việc.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e2. Thực trạng v\u0026#224; C\u0026#225;c Vấn đề Cốt l\u0026#245;i của Thị trường Lao động Kỹ thuật tại Việt Nam\u003c/strong\u003e\u003c/p\u003e\u003cp\u003eĐể đạt điểm tối đa trong c\u0026#225;c c\u0026#226;u hỏi tự luận mở (như C\u0026#226;u 6 Đề thi HSG nguồn), học sinh cần nắm vững 4 vấn đề cốt l\u0026#245;i sau đ\u0026#226;y của thị trường lao động kỹ thuật Việt Nam hiện nay:\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eVấn đề 1: Tỉ lệ lao động qua đ\u0026#224;o tạo tăng nhưng chất lượng chưa đồng đều. \u003c/strong\u003eTỉ lệ lao động qua đ\u0026#224;o tạo c\u0026#243; bằng cấp, chứng chỉ tại Việt Nam đang gia tăng nhanh ch\u0026#243;ng (đạt tr\u0026#234;n 27 - 28%), tuy nhi\u0026#234;n tỉ lệ lao động chưa qua đ\u0026#224;o tạo ch\u0026#237;nh quy vẫn c\u0026#242;n chiếm tỉ trọng lớn (tr\u0026#234;n 70%). Điều n\u0026#224;y tạo ra sức \u0026#233;p lớn về năng suất lao động to\u0026#224;n quốc.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eVấn đề 2: Mất c\u0026#226;n đối Cung - Cầu (Lệch pha tr\u0026#236;nh độ). \u003c/strong\u003eThị trường xảy ra t\u0026#236;nh trạng \u0026#39;Vừa thừa - Vừa thiếu\u0026#39;: Thừa lao động phổ th\u0026#244;ng, thừa cử nh\u0026#226;n/kỹ sư đ\u0026#224;o tạo l\u0026#253; thuyết su\u0026#244;ng thiếu kỹ năng thực h\u0026#224;nh; nhưng lại thiếu nghi\u0026#234;m trọng kỹ sư chất lượng cao, chuy\u0026#234;n gia c\u0026#244;ng nghệ mũi nhọn (tr\u0026#237; tuệ nh\u0026#226;n tạo, b\u0026#225;n dẫn, tự động h\u0026#243;a, c\u0026#244;ng nghệ sinh học).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eVấn đề 3: Sự ph\u0026#226;n bố lao động kh\u0026#244;ng đồng đều giữa c\u0026#225;c v\u0026#249;ng miền. \u003c/strong\u003eLực lượng lao động kỹ thuật tập trung mật độ cao tại c\u0026#225;c đ\u0026#244; thị lớn (H\u0026#224; Nội, TP.HCM, Đ\u0026#224; Nẵng) v\u0026#224; c\u0026#225;c v\u0026#249;ng kinh tế trọng điểm (Đ\u0026#244;ng Nam Bộ, Đồng bằng s\u0026#244;ng Hồng). C\u0026#225;c v\u0026#249;ng n\u0026#244;ng th\u0026#244;n, miền n\u0026#250;i, Đồng bằng s\u0026#244;ng Cửu Long gặp kh\u0026#243; khăn trong việc thu h\u0026#250;t v\u0026#224; giữ ch\u0026#226;n nh\u0026#226;n lực kỹ thuật chất lượng cao.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eVấn đề 4: T\u0026#225;c động mạnh mẽ của CMCN 4.0 v\u0026#224; Chuyển đổi số. \u003c/strong\u003eC\u0026#225;ch mạng C\u0026#244;ng nghiệp 4.0 v\u0026#224; qu\u0026#225; tr\u0026#236;nh chuyển đổi số đ\u0026#242;i hỏi người lao động kh\u0026#244;ng chỉ c\u0026#243; kiến thức chuy\u0026#234;n m\u0026#244;n cứng m\u0026#224; bắt buộc phải sở hữu Kỹ năng số (Digital Skills), Kỹ năng mềm (L\u0026#224;m việc nh\u0026#243;m, Giải quyết vấn đề, Tư duy phản biện), Năng lực ngoại ngữ v\u0026#224; Khả năng học tập suốt đời (Lifelong Learning).\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eĐỊNH HƯỚNG PH\u0026#194;N H\u0026#211;A HSG CỦA SỞ GDĐT VĨNH LONG:\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e\u003cem\u003eKhi l\u0026#224;m b\u0026#224;i thi HSG, học sinh kh\u0026#244;ng được chỉ học thuộc l\u0026#242;ng kh\u0026#225;i niệm su\u0026#244;ng. Y\u0026#234;u cầu cao nhất của c\u0026#226;u hỏi tự luận C\u0026#244;ng nghệ 9 l\u0026#224; học sinh phải thể hiện được TƯ DUY PHẢN BIỆN KINH TẾ - X\u0026#195; HỘI: Giải th\u0026#237;ch được nguy\u0026#234;n nh\u0026#226;n gốc rễ của t\u0026#236;nh trạng \u0026#39;Thừa thầy - Thiếu thợ\u0026#39; v\u0026#224; đề xuất giải ph\u0026#225;p từ g\u0026#243;c độ ph\u0026#226;n luồng gi\u0026#225;o dục THCS.\u003c/em\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003cp\u003e\u003cstrong\u003e3. \u0026#221; nghĩa của Th\u0026#244;ng tin Thị trường Lao động đối với Học sinh THCS\u003c/strong\u003e\u003c/p\u003e\u003cp\u003eNắm bắt th\u0026#244;ng tin thị trường lao động l\u0026#224; bước bắt buộc trong Quy tr\u0026#236;nh lựa chọn nghề nghiệp khoa học, gi\u0026#250;p học sinh THCS:\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e1. Định hướng học tập thực tế: \u003c/strong\u003eTr\u0026#225;nh t\u0026#226;m l\u0026#253; \u0026#39;chọn nghề theo cảm t\u0026#237;nh\u0026#39;, \u0026#39;chọn nghề theo xu hướng đ\u0026#225;m đ\u0026#244;ng\u0026#39; hoặc chọn nghề chỉ dựa v\u0026#224;o danh tiếng ảo m\u0026#224; kh\u0026#244;ng biết nhu cầu thực tế của x\u0026#227; hội.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e2. Chủ động đ\u0026#243;n đầu xu hướng: \u003c/strong\u003eNhận biết được những ng\u0026#224;nh nghề n\u0026#224;o đang c\u0026#243; xu hướng ph\u0026#225;t triển (ng\u0026#224;nh đ\u0026#243;n đầu), ng\u0026#224;nh n\u0026#224;o đang bị thu hẹp hoặc thay thế bởi AI/Robot để chủ động chuẩn bị năng lực tương ứng.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e3. Hạn chế rủi ro thất nghiệp: \u003c/strong\u003eĐ\u0026#225;nh gi\u0026#225; đ\u0026#250;ng khả năng xin việc v\u0026#224; ph\u0026#225;t triển sự nghiệp sau khi tốt nghiệp c\u0026#225;c cấp học (THPT, Trung cấp, Cao đẳng, Đại học).\u003c/p\u003e\u003ch3\u003eII. PHÂN TÍCH DẠNG CÂU HỎI VÀ MẪU TRẢ LỜI CHUẨN ĐỀ THI HSG\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003ePh\u0026#226;n t\u0026#237;ch chi tiết C\u0026#226;u 6 (3,0 điểm) - Đề thi HSG Nguồn tỉnh Vĩnh Long\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eĐề b\u0026#224;i mẫu: \u003c/strong\u003ePh\u0026#226;n t\u0026#237;ch c\u0026#225;c vấn đề cốt l\u0026#245;i của thị trường lao động kỹ thuật, c\u0026#244;ng nghệ tại Việt Nam hiện nay. Tại sao học sinh THCS cần phải cập nhật th\u0026#244;ng tin thị trường lao động trước khi quyết định chọn đường học tập sau tốt nghiệp?\u003c/p\u003e\u003cp\u003eDưới đ\u0026#226;y l\u0026#224; Bảng cấu tr\u0026#250;c c\u0026#226;u trả lời đạt điểm tối đa (3,0/3,0 điểm) theo biểu điểm chấm chi tiết của Sở GDĐT:\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003e\u0026#221; nội dung\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eNội dung ph\u0026#226;n t\u0026#237;ch đạt chuẩn HSG\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eĐiểm chuẩn\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e1. Kh\u0026#225;i niệm \u0026amp; Vai tr\u0026#242; (0,5đ)\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eN\u0026#234;u ch\u0026#237;nh x\u0026#225;c kh\u0026#225;i niệm thị trường lao động kỹ thuật, c\u0026#244;ng nghệ. Khẳng định đ\u0026#226;y l\u0026#224; cầu nối giữa hệ thống gi\u0026#225;o dục - đ\u0026#224;o tạo với nền kinh tế quốc d\u0026#226;n.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e0,50 điểm\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e2. Ph\u0026#226;n t\u0026#237;ch 4 Vấn đề cốt l\u0026#245;i (1,5đ)\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e- Tỉ lệ lao động qua đ\u0026#224;o tạo tăng nhưng chất lượng chưa đồng đều (0,375đ).\u003cbr\u003e- T\u0026#236;nh trạng lệch pha Cung - Cầu \u0026#39;vừa thừa - vừa thiếu\u0026#39; (0,375đ).\u003cbr\u003e- Sự ph\u0026#226;n bố nh\u0026#226;n lực kh\u0026#244;ng đồng đều giữa đ\u0026#244; thị - n\u0026#244;ng th\u0026#244;n/v\u0026#249;ng miền (0,375đ).\u003cbr\u003e- T\u0026#225;c động của CMCN 4.0, tự động h\u0026#243;a \u0026amp; chuyển đổi số đ\u0026#242;i hỏi kỹ năng mới (0,375đ).\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e1,50 điểm\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e3. \u0026#221; nghĩa đối với HS THCS (0,75đ)\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e- Gi\u0026#250;p chọn nghề/chọn tuyến đường học tập kh\u0026#225;ch quan, b\u0026#225;m s\u0026#225;t nhu cầu x\u0026#227; hội (0,25đ).\u003cbr\u003e- Tr\u0026#225;nh thất nghiệp, l\u0026#227;ng ph\u0026#237; thời gian v\u0026#224; tiền bạc gia đ\u0026#236;nh (0,25đ).\u003cbr\u003e- Chủ động r\u0026#232;n luyện kỹ năng mềm, kỹ năng số đ\u0026#243;n đầu xu hướng (0,25đ).\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e0,75 điểm\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e4. Li\u0026#234;n hệ bản th\u0026#226;n \u0026amp; Kết luận (0,25đ)\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eR\u0026#250;t ra b\u0026#224;i học h\u0026#224;nh động bản th\u0026#226;n: T\u0026#237;ch cực t\u0026#236;m kiếm th\u0026#244;ng tin qua c\u0026#225;c k\u0026#234;nh ch\u0026#237;nh thống, tự đ\u0026#225;nh gi\u0026#225; năng lực bản th\u0026#226;n để quyết định ph\u0026#226;n luồng sau lớp 9.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e0,25 điểm\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003ch3\u003eIII. NGÂN HÀNG BÀI TẬP ÔN THI HSG (4 MỨC ĐỘ)\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003eMức độ 1: Nhận biết - Th\u0026#244;ng hiểu (2 C\u0026#226;u)\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 1 (2,0 điểm): \u003c/strong\u003eThị trường lao động kỹ thuật, c\u0026#244;ng nghệ bao gồm những yếu tố cấu th\u0026#224;nh cơ bản n\u0026#224;o? Ph\u0026#226;n biệt giữa Cung lao động v\u0026#224; Cầu lao động trong lĩnh vực n\u0026#224;y.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 2 (2,0 điểm): \u003c/strong\u003eTr\u0026#236;nh b\u0026#224;y c\u0026#225;c k\u0026#234;nh th\u0026#244;ng tin ch\u0026#237;nh thống m\u0026#224; học sinh THCS c\u0026#243; thể tiếp cận để t\u0026#236;m hiểu về thị trường lao động kỹ thuật, c\u0026#244;ng nghệ tại địa phương v\u0026#224; tr\u0026#234;n to\u0026#224;n quốc.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eMức độ 2: Vận dụng (2 C\u0026#226;u)\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 3 (3,0 điểm): \u003c/strong\u003eGiải th\u0026#237;ch nguy\u0026#234;n nh\u0026#226;n tại sao tr\u0026#234;n thị trường lao động Việt Nam hiện nay lại tồn tại song song hai hiện tượng: H\u0026#224;ng ngh\u0026#236;n cử nh\u0026#226;n/kỹ sư tốt nghiệp đại học kh\u0026#244;ng t\u0026#236;m được việc l\u0026#224;m, trong khi c\u0026#225;c doanh nghiệp c\u0026#244;ng nghệ lại chật vật kh\u0026#244;ng tuyển đủ nh\u0026#226;n sự?\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 4 (3,0 điểm): \u003c/strong\u003eCuộc C\u0026#225;ch mạng C\u0026#244;ng nghiệp 4.0 v\u0026#224; xu hướng chuyển đổi số đang đặt ra những y\u0026#234;u cầu mới n\u0026#224;o về phẩm chất v\u0026#224; năng lực đối với người lao động trong lĩnh vực kỹ thuật, c\u0026#244;ng nghệ?\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eMức độ 3: Vận dụng cao - Lập luận Ph\u0026#226;n h\u0026#243;a (2 C\u0026#226;u)\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 5 (3,5 điểm): \u003c/strong\u003eC\u0026#243; \u0026#253; kiến cho rằng: \u0026#39;Trong thời đại tự động h\u0026#243;a v\u0026#224; Tr\u0026#237; tuệ nh\u0026#226;n tạo (AI) ph\u0026#225;t triển mạnh mẽ, hầu hết c\u0026#225;c nghề nghiệp kỹ thuật truyền thống sẽ bị thay thế, do đ\u0026#243; học sinh kh\u0026#244;ng n\u0026#234;n theo học c\u0026#225;c ng\u0026#224;nh kỹ thuật cơ bản nữa.\u0026#39; Em h\u0026#227;y d\u0026#249;ng kiến thức về thị trường lao động để b\u0026#236;nh luận v\u0026#224; phản biện \u0026#253; kiến tr\u0026#234;n.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 6 (3,5 điểm): \u003c/strong\u003ePh\u0026#226;n t\u0026#237;ch mối quan hệ t\u0026#225;c động qua lại giữa C\u0026#244;ng t\u0026#225;c ph\u0026#226;n luồng gi\u0026#225;o dục học sinh sau THCS v\u0026#224; sự ph\u0026#225;t triển ổn định của Thị trường lao động kỹ thuật tại địa phương (tỉnh Vĩnh Long v\u0026#224; Đồng bằng s\u0026#244;ng Cửu Long).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eMức độ 4: B\u0026#224;i tập T\u0026#236;nh huống Thực tiễn \u0026amp; Ph\u0026#226;n t\u0026#237;ch Dữ liệu Thị trường (1 B\u0026#224;i to\u0026#225;n lớn)\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 7 (3,0 điểm - B\u0026#224;i tập t\u0026#236;nh huống): \u003c/strong\u003eTrong buổi thảo luận hướng nghiệp lớp 9, hai bạn Nam v\u0026#224; An tranh luận về việc chọn đường học tập:\u003cbr\u003e- Bạn Nam n\u0026#243;i: \u0026#39;Tớ thấy tr\u0026#234;n mạng b\u0026#225;o c\u0026#225;o ng\u0026#224;nh C\u0026#244;ng nghệ th\u0026#244;ng tin v\u0026#224; Lập tr\u0026#236;nh vi\u0026#234;n đang c\u0026#243; mức lương rất cao (h\u0026#224;ng chục triệu/th\u0026#225;ng). Tớ quyết định sẽ đăng k\u0026#253; thi v\u0026#224;o ng\u0026#224;nh n\u0026#224;y bất kể tớ học m\u0026#244;n To\u0026#225;n v\u0026#224; C\u0026#244;ng nghệ rất trung b\u0026#236;nh.\u0026#39;\u003cbr\u003e- Bạn An đ\u0026#225;p: \u0026#39;Nhưng tớ đọc th\u0026#244;ng tin thị trường lao động mới nhất thấy ng\u0026#224;nh đ\u0026#243; đang c\u0026#243; sự sa thải h\u0026#224;ng loạt v\u0026#224; cạnh tranh khốc liệt do sự xuất hiện của AI tạo sinh (Generative AI). Nếu năng lực tớ kh\u0026#244;ng xuất sắc th\u0026#236; theo đuổi chưa chắc đ\u0026#227; c\u0026#243; việc l\u0026#224;m.\u0026#39;\u003cbr\u003e\u003cbr\u003eY\u0026#234;u cầu:\u003cbr\u003ea) Em h\u0026#227;y nhận x\u0026#233;t về quan điểm của Nam v\u0026#224; An dựa tr\u0026#234;n nguy\u0026#234;n tắc ph\u0026#226;n t\u0026#237;ch thị trường lao động v\u0026#224; M\u0026#244; h\u0026#236;nh C\u0026#226;y nghề nghiệp.\u003cbr\u003eb) Nếu l\u0026#224; bạn th\u0026#226;n của Nam, em sẽ đưa ra lời khuy\u0026#234;n như thế n\u0026#224;o để gi\u0026#250;p Nam đ\u0026#225;nh gi\u0026#225; lại lựa chọn của m\u0026#236;nh một c\u0026#225;ch khoa học?\u003c/p\u003e\u003ch3\u003eIV. ĐÁP ÁN VÀ HƯỚNG DẪN CHẤM CHI TIẾT (BIỂU ĐIỂM CHẤM 0,25Đ SỞ GDĐT VĨNH LONG)\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003eĐ\u0026#225;p \u0026#225;n C\u0026#226;u 1 (2,0 điểm)\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003ea) Kh\u0026#225;i niệm chung (0,5đ): \u003c/strong\u003eN\u0026#234;u đ\u0026#250;ng kh\u0026#225;i niệm thị trường lao động kỹ thuật, c\u0026#244;ng nghệ (0,5đ).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eb) Ph\u0026#226;n biệt Cung - Cầu (1,5đ): \u003c/strong\u003eCung lao động: L\u0026#224; lực lượng người lao động c\u0026#243; tr\u0026#236;nh độ chuy\u0026#234;n m\u0026#244;n kỹ thuật đang cung ứng hoặc sẵn s\u0026#224;ng cung ứng sức lao động cho thị trường (0,75đ).\u003cbr\u003eCầu lao động: L\u0026#224; nhu cầu sử dụng lao động kỹ thuật của c\u0026#225;c cơ quan, doanh nghiệp trong nền kinh tế (0,75đ).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eĐ\u0026#225;p \u0026#225;n C\u0026#226;u 3 (3,0 điểm)\u003c/strong\u003e\u003c/p\u003e\u003cp\u003eHọc sinh cần lập luận l\u0026#224;m nổi bật 3 nguy\u0026#234;n nh\u0026#226;n cốt l\u0026#245;i (Mỗi \u0026#253; đ\u0026#250;ng 1,0đ):\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e1. Lệch pha về chất lượng đ\u0026#224;o tạo: \u003c/strong\u003eDo hệ thống đ\u0026#224;o tạo ở một số cơ sở c\u0026#242;n nặng về l\u0026#253; thuyết, thiếu thời lượng thực h\u0026#224;nh xưởng v\u0026#224; c\u0026#244;ng nghệ hiện đại, dẫn đến sinh vi\u0026#234;n ra trường thiếu kỹ năng thực tế doanh nghiệp cần.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e2. Mất c\u0026#226;n đối cơ cấu ng\u0026#224;nh nghề: \u003c/strong\u003eT\u0026#226;m l\u0026#253; chuộng bằng cấp đại học khiến học sinh ồ ạt đăng k\u0026#253; v\u0026#224;o c\u0026#225;c ng\u0026#224;nh kinh tế, quản trị... tạo ra sự dư thừa cử nh\u0026#226;n, trong khi thiếu hụt trầm trọng thợ kỹ thuật l\u0026#224;nh nghề (Hệ trung cấp/cao đẳng nghề).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e3. Thiếu kết nối Cung - Cầu: \u003c/strong\u003eThiếu sự kết nối chặt chẽ giữa Cơ sở đ\u0026#224;o tạo v\u0026#224; Doanh nghiệp sử dụng lao động, dẫn đến th\u0026#244;ng tin thị trường kh\u0026#244;ng được cập nhật kịp thời v\u0026#224;o chương tr\u0026#236;nh giảng dạy.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eĐ\u0026#225;p \u0026#225;n C\u0026#226;u 5 (3,5 điểm - Phản biện HSG)\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003ea) Quan điểm phản biện (0,5đ): \u003c/strong\u003eKhẳng định \u0026#253; kiến tr\u0026#234;n l\u0026#224; KH\u0026#212;NG HO\u0026#192;N TO\u0026#192;N Đ\u0026#218;NG / Mang t\u0026#237;nh phiến diện (0,5đ).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eb) Ph\u0026#226;n t\u0026#237;ch vai tr\u0026#242; c\u0026#244;ng nghệ (1,5đ): \u003c/strong\u003eTự động h\u0026#243;a v\u0026#224; AI chỉ thay thế c\u0026#225;c c\u0026#244;ng việc mang t\u0026#237;nh lặp đi lặp lại, thủ c\u0026#244;ng đơn giản. Đối với c\u0026#225;c ng\u0026#224;nh kỹ thuật cốt l\u0026#245;i (Cơ kh\u0026#237;, Điện - Điện tử, Trồng trọt c\u0026#244;ng nghệ cao), AI v\u0026#224; Robot chỉ l\u0026#224; c\u0026#244;ng cụ hỗ trợ tăng năng suất, kh\u0026#244;ng thể thay thế ho\u0026#224;n to\u0026#224;n con người trong kh\u0026#226;u tư duy s\u0026#225;ng tạo, vận h\u0026#224;nh v\u0026#224; bảo tr\u0026#236; hệ thống phức tạp (1,5đ).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003ec) Xu hướng chuyển dịch (1,0đ): \u003c/strong\u003eC\u0026#225;c ng\u0026#224;nh kỹ thuật cơ bản đang biến đổi sang dạng \u0026#39;Kỹ thuật th\u0026#244;ng minh\u0026#39; (Smart Engineering). Người lao động nắm chắc kỹ thuật cơ bản kết hợp kỹ năng số sẽ c\u0026#243; cơ hội việc l\u0026#224;m v\u0026#244; c\u0026#249;ng rộng mở (1,0đ).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003ed) B\u0026#224;i học h\u0026#224;nh động (0,5đ): \u003c/strong\u003eHọc sinh kh\u0026#244;ng n\u0026#234;n tẩy chay ng\u0026#224;nh kỹ thuật m\u0026#224; cần thay đổi phương ph\u0026#225;p học tập: Học đi đ\u0026#244;i với h\u0026#224;nh, chủ động trang bị kỹ năng số v\u0026#224; ngoại ngữ (0,5đ).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eĐ\u0026#225;p \u0026#225;n C\u0026#226;u 7 (3,0 điểm - B\u0026#224;i tập T\u0026#236;nh huống)\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003ea) Nhận x\u0026#233;t quan điểm Nam v\u0026#224; An (1,5đ): \u003c/strong\u003eBạn Nam mới chỉ nh\u0026#236;n v\u0026#224;o \u0026#39;Phần Quả\u0026#39; (mức lương cao) m\u0026#224; bỏ qua \u0026#39;Phần Rễ\u0026#39; (học lực To\u0026#225;n/C\u0026#244;ng nghệ trung b\u0026#236;nh) v\u0026#224; t\u0026#237;nh cạnh tranh của thị trường. Việc chọn nghề n\u0026#224;y chứa đựng rủi ro cao (1,0đ).\u003cbr\u003eBạn An đ\u0026#227; biết cập nhật th\u0026#244;ng tin thị trường lao động v\u0026#224; c\u0026#243; g\u0026#243;c nh\u0026#236;n đa chiều, tỉnh t\u0026#225;o trước sự biến động của c\u0026#244;ng nghệ (0,5đ).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eb) Lời khuy\u0026#234;n cho Nam (1,5đ): \u003c/strong\u003e- Khuy\u0026#234;n Nam cần soi chiếu lại M\u0026#244; h\u0026#236;nh C\u0026#226;y nghề nghiệp: Muốn c\u0026#243; \u0026#39;Phần Quả\u0026#39; tốt (lương cao), \u0026#39;Phần Rễ\u0026#39; (sở th\u0026#237;ch, năng lực học tập To\u0026#225;n/C\u0026#244;ng nghệ) phải đủ vững chắc (0,75đ).\u003cbr\u003e- Hướng dẫn Nam thực hiện Quy tr\u0026#236;nh chọn nghề 3 bước khoa học: Tự đ\u0026#225;nh gi\u0026#225; năng lực bản th\u0026#226;n -\u0026gt; T\u0026#236;m hiểu kỹ nhu cầu thị trường -\u0026gt; Chọn tuyến đường học tập ph\u0026#249; hợp (Trung cấp/Cao đẳng/THPT) (0,75đ).\u003c/p\u003e","10":"\u003ch2\u003eCHUYÊN ĐỀ 10: LÝ THUYẾT HƯỚNG NGHIỆP \u0026 QUY TRÌNH LỰA CHỌN NGHỀ NGHIỆP\u003c/h2\u003e\u003ch2\u003ePHẦN I: HỆ THỐNG LÝ THUYẾT HƯỚNG NGHIỆP CỐT LÕI \u0026 CHUYÊN SÂU\u003c/h2\u003e\u003cp\u003eĐịnh hướng nghề nghiệp l\u0026#224; một mạch kiến thức cốt l\u0026#245;i trong Chương tr\u0026#236;nh GDPT 2018 M\u0026#244;n C\u0026#244;ng nghệ lớp 9. Việc nắm vững c\u0026#225;c m\u0026#244; h\u0026#236;nh l\u0026#253; thuyết hướng nghiệp khoa học gi\u0026#250;p học sinh c\u0026#243; căn cứ đ\u0026#225;nh gi\u0026#225; bản th\u0026#226;n, đối chiếu với y\u0026#234;u cầu thị trường lao động v\u0026#224; đưa ra quyết định chọn nghề đ\u0026#250;ng đắn.\u003c/p\u003e\u003ch3\u003e1. Lý thuyết Mật mã Holland (John Holland)\u003c/h3\u003e\u003cp\u003eL\u0026#253; thuyết Mật m\u0026#227; Holland do nh\u0026#224; t\u0026#226;m l\u0026#253; học John Lewis Holland (1919 – 2008) ph\u0026#225;t triển tr\u0026#234;n luận điểm cơ bản: \u003cem\u003eThi\u0026#234;n hướng nghề nghiệp ch\u0026#237;nh l\u0026#224; biểu hiện của t\u0026#237;nh c\u0026#225;ch. Nếu một người chọn được nghề nghiệp ph\u0026#249; hợp với kiểu t\u0026#237;nh c\u0026#225;ch của m\u0026#236;nh th\u0026#236; sẽ dễ th\u0026#237;ch ứng, l\u0026#224;m việc hiệu quả v\u0026#224; đạt được th\u0026#224;nh c\u0026#244;ng, h\u0026#224;i l\u0026#242;ng với c\u0026#244;ng việc.\u003c/em\u003e\u003c/p\u003e\u003cp\u003eHolland ph\u0026#226;n loại t\u0026#237;nh c\u0026#225;ch con người v\u0026#224; m\u0026#244;i trường nghề nghiệp tương ứng th\u0026#224;nh \u003cstrong\u003e6 nh\u0026#243;m t\u0026#237;nh c\u0026#225;ch đặc trưng (M\u0026#244; h\u0026#236;nh RIASEC):\u003c/strong\u003e\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eNh\u0026#243;m t\u0026#237;nh c\u0026#225;ch (M\u0026#227;)\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eĐặc điểm t\u0026#237;nh c\u0026#225;ch nổi bật\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eM\u0026#244;i trường / Ng\u0026#224;nh nghề ph\u0026#249; hợp\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eKỹ thuật (Realistic - R)\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eC\u0026#243; t\u0026#237;nh tự lập; suy nghĩ thực tế; th\u0026#237;ch nghi nhanh ch\u0026#243;ng. Thao t\u0026#225;c, vận động kh\u0026#233;o l\u0026#233;o; hứng th\u0026#250; vận h\u0026#224;nh, điều khiển m\u0026#225;y m\u0026#243;c, thiết bị.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eThợ cơ kh\u0026#237;, Kỹ sư cơ kh\u0026#237;, Thợ điện, Kỹ thuật vi\u0026#234;n \u0026#244; t\u0026#244;, Lắp r\u0026#225;p thiết bị, N\u0026#244;ng nghiệp kỹ thuật cao.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eNghi\u0026#234;n cứu (Investigative - I)\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eTh\u0026#237;ch t\u0026#236;m hiểu, kh\u0026#225;m ph\u0026#225; nhiều vấn đề mới; c\u0026#243; khả năng ph\u0026#226;n t\u0026#237;ch vấn đề, tư duy mạch lạc; th\u0026#237;ch điều tra, ph\u0026#226;n loại, kh\u0026#225;i qu\u0026#225;t vấn đề.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eNh\u0026#224; khoa học dữ liệu, Kỹ sư phần mềm, Chuy\u0026#234;n gia R\u0026amp;D, B\u0026#225;c sĩ, Chuy\u0026#234;n gia ph\u0026#226;n t\u0026#237;ch hệ thống.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eNghệ thuật (Artistic - A)\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eDễ x\u0026#250;c động, c\u0026#243; \u0026#243;c tưởng tượng phong ph\u0026#250;, th\u0026#237;ch tự do; th\u0026#237;ch chụp h\u0026#236;nh, vẽ tranh, chơi nhạc cụ; th\u0026#237;ch c\u0026#244;ng việc mang t\u0026#237;nh s\u0026#225;ng tạo.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eNh\u0026#224; thiết kế nội thất/đồ họa, Kiến tr\u0026#250;c sinh th\u0026#225;i, Bi\u0026#234;n kịch, Đạo diễn, S\u0026#225;ng tạo nội dung digital.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eX\u0026#227; hội (Social - S)\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eTh\u0026#237;ch gi\u0026#250;p đỡ người kh\u0026#225;c, th\u0026#237;ch gặp gỡ l\u0026#224;m việc với con người; c\u0026#243; khả năng lắng nghe; th\u0026#237;ch hoạt động v\u0026#236; mục ti\u0026#234;u cộng đồng.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eGi\u0026#225;o vi\u0026#234;n, B\u0026#225;c sĩ t\u0026#226;m l\u0026#253;, Chuy\u0026#234;n vi\u0026#234;n tư vấn hướng nghiệp, Nh\u0026#226;n vi\u0026#234;n c\u0026#244;ng t\u0026#225;c x\u0026#227; hội, Y sĩ.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eQuản l\u0026#253; (Enterprising - E)\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eC\u0026#243; t\u0026#237;nh phi\u0026#234;u lưu, mạo hiểm, quyết đo\u0026#225;n, năng động; c\u0026#243; khả năng thuyết phục; th\u0026#237;ch cạnh tranh, muốn người kh\u0026#225;c nể phục.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eQuản l\u0026#253; dự \u0026#225;n kỹ thuật, Gi\u0026#225;m đốc điều h\u0026#224;nh (CEO), Chuy\u0026#234;n vi\u0026#234;n kinh doanh c\u0026#244;ng nghệ, Khởi nghiệp (Startup).\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eNghiệp vụ (Conventional - C)\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eC\u0026#243; đầu \u0026#243;c sắp xếp tổ chức, cẩn thận, đ\u0026#225;ng tin cậy; th\u0026#237;ch c\u0026#244;ng việc lưu trữ, cập nhật th\u0026#244;ng tin, l\u0026#224;m việc với dữ liệu, con số.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eKế to\u0026#225;n vi\u0026#234;n, Quản trị cơ sở dữ liệu, Chuy\u0026#234;n vi\u0026#234;n lưu trữ hồ sơ kỹ thuật, Kiểm to\u0026#225;n vi\u0026#234;n, Thủ kho.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003ch3\u003e2. Mô hình Lý thuyết Cây Nghề Nghiệp\u003c/h3\u003e\u003cp\u003eM\u0026#244; h\u0026#236;nh C\u0026#226;y nghề nghiệp l\u0026#224; một trong những c\u0026#244;ng cụ trực quan nhất gi\u0026#250;p học sinh h\u0026#236;nh dung mối quan hệ hữu cơ giữa c\u0026#225;c yếu tố nội tại của bản th\u0026#226;n v\u0026#224; kết quả nghề nghiệp tương lai.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eM\u0026#244; h\u0026#236;nh cấu tr\u0026#250;c gồm 2 bộ phận ch\u0026#237;nh:\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003ePhần Rễ c\u0026#226;y (Yếu tố nền tảng b\u0026#234;n trong): \u003c/strong\u003eThế hiện c\u0026#225;c yếu tố nội tại của c\u0026#225; nh\u0026#226;n gồm: \u003cstrong\u003eSở th\u0026#237;ch, Năng lực (Khả năng), C\u0026#225; t\u0026#237;nh, v\u0026#224; Gi\u0026#225; trị nghề nghiệp. \u003c/strong\u003eĐ\u0026#226;y l\u0026#224; phần ch\u0026#236;m dưới đất, cần được chăm s\u0026#243;c, nu\u0026#244;i dưỡng li\u0026#234;n tục qua qu\u0026#225; tr\u0026#236;nh học tập v\u0026#224; r\u0026#232;n luyện.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003ePhần Quả c\u0026#226;y (Kết quả / Mong muốn b\u0026#234;n ngo\u0026#224;i): \u003c/strong\u003eThể hiện những th\u0026#224;nh quả v\u0026#224; gi\u0026#225; trị nhận được từ nghề nghiệp gồm: \u003cstrong\u003eCơ hội việc l\u0026#224;m, M\u0026#244;i trường l\u0026#224;m việc tốt, Lương cao (Thu nhập ổn định), C\u0026#244;ng việc ổn định, v\u0026#224; Được nhiều người t\u0026#244;n trọng. \u003c/strong\u003eĐ\u0026#226;y l\u0026#224; phần nổi tr\u0026#234;n c\u0026#224;nh m\u0026#224; mỗi người đều hướng tới.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003e Quy tắc cốt l\u0026#245;i của C\u0026#226;y nghề nghiệp: \u003c/strong\u003e\u003cem\u003eMuốn c\u0026#226;y ra \u0026#39;quả ngọt\u0026#39; (thu nhập cao, vị tr\u0026#237; tốt) th\u0026#236; phải tập trung nu\u0026#244;i dưỡng v\u0026#224; chọn nghề dựa tr\u0026#234;n \u0026#39;gốc rễ\u0026#39; (sở th\u0026#237;ch, năng lực, c\u0026#225; t\u0026#237;nh). Nếu chọn nghề chỉ chạy theo phần quả (thấy lương cao, thời thượng) m\u0026#224; kh\u0026#244;ng ph\u0026#249; hợp với phần rễ, c\u0026#226;y nghề nghiệp sẽ dễ bị \u0026#39;s\u0026#226;u bệnh\u0026#39;, g\u0026#227;y đổ hoặc kh\u0026#244;ng thể ph\u0026#225;t triển bền vững.\u003c/em\u003e\u003c/p\u003e\u003ch3\u003e3. Quy trình Lựa chọn Nghề nghiệp Khoa học (3 Bước)\u003c/h3\u003e\u003cp\u003eĐể tr\u0026#225;nh những sai lầm cảm t\u0026#237;nh, học sinh cần thực hiện quy tr\u0026#236;nh chọn nghề gồm 3 bước logic sau:\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eBước quy tr\u0026#236;nh\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eNội dung thực hiện cốt l\u0026#245;i\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#225;c c\u0026#244;ng việc \u0026amp; Y\u0026#234;u cầu cụ thể\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eBước 1: Đ\u0026#225;nh gi\u0026#225; bản th\u0026#226;n\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eThấu hiểu c\u0026#225;c yếu tố nội tại \u0026#39;Gốc Rễ\u0026#39; của c\u0026#225; nh\u0026#226;n.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e• X\u0026#225;c định sở th\u0026#237;ch, đam m\u0026#234; nghề nghiệp.\u003cbr\u003e• Đ\u0026#225;nh gi\u0026#225; năng lực học tập, kỹ năng nổi trội.\u003cbr\u003e• Nhận diện kiểu t\u0026#237;nh c\u0026#225;ch (qua trắc nghiệm Holland).\u003cbr\u003e• X\u0026#225;c định bối cảnh v\u0026#224; điều kiện kinh tế gia đ\u0026#236;nh.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eBước 2: T\u0026#236;m hiểu thị trường lao động\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eNghi\u0026#234;n cứu th\u0026#244;ng tin v\u0026#224; y\u0026#234;u cầu của c\u0026#225;c ng\u0026#224;nh nghề.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e• Tra cứu th\u0026#244;ng tin nhiệm vụ, m\u0026#244;i trường l\u0026#224;m việc.\u003cbr\u003e• X\u0026#225;c định y\u0026#234;u cầu về năng lực, phẩm chất, bằng cấp.\u003cbr\u003e• Khảo s\u0026#225;t nhu cầu tuyển dụng, mức lương v\u0026#224; cơ hội ph\u0026#225;t triển trong 3–5 năm tới.\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eBước 3: Ra quyết định chọn nghề\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eSo s\u0026#225;nh, đối chiếu v\u0026#224; chốt phương \u0026#225;n tối ưu.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e• Lập bảng đối chiếu sự tr\u0026#249;ng khớp giữa Bước 1 v\u0026#224; Bước 2.\u003cbr\u003e• Xếp thứ tự ưu ti\u0026#234;n c\u0026#225;c ng\u0026#224;nh nghề ph\u0026#249; hợp nhất.\u003cbr\u003e• Chọn hướng đi học tập sau THPT (Đại học, Cao đẳng, Trung cấp).\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003ch3\u003e4. Các Yếu tố Ảnh hưởng đến Quyết định Chọn nghề\u003c/h3\u003e\u003cp\u003eQuyết định lựa chọn nghề nghiệp chịu sự t\u0026#225;c động tổng h\u0026#242;a của hai nh\u0026#243;m yếu tố:\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eNh\u0026#243;m yếu tố chủ quan (Nội tại c\u0026#225; nh\u0026#226;n): \u003c/strong\u003eSở th\u0026#237;ch (tạo động lực), Năng lực (quyết định khả năng ho\u0026#224;n th\u0026#224;nh c\u0026#244;ng việc), v\u0026#224; C\u0026#225; t\u0026#237;nh (quyết định xu hướng m\u0026#244;i trường l\u0026#224;m việc ph\u0026#249; hợp).\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eNh\u0026#243;m yếu tố kh\u0026#225;ch quan (M\u0026#244;i trường b\u0026#234;n ngo\u0026#224;i): \u003c/strong\u003eGia đ\u0026#236;nh (điều kiện kinh tế, mong muốn của cha mẹ), Nh\u0026#224; trường (hoạt động hướng nghiệp, thầy c\u0026#244;), X\u0026#227; hội (nhu cầu thị trường lao động, tr\u0026#224;o lưu nghề nghiệp), v\u0026#224; Nh\u0026#243;m bạn b\u0026#232; (nguồn th\u0026#244;ng tin tham khảo, tuy nhi\u0026#234;n cần tỉnh t\u0026#225;o tr\u0026#225;nh chạy theo đ\u0026#225;m đ\u0026#244;ng).\u003c/p\u003e\u003ch2\u003ePHẦN II: TRỌNG TÂM PHÂN HÓA ĐỀ THI HSG CÔNG NGHỆ VĨNH LONG (3,0 ĐIỂM)\u003c/h2\u003e\u003cp\u003e\u003cem\u003eTr\u0026#237;ch dẫn C\u0026#226;u 5 trong Đề thi Ch\u0026#237;nh thức HSG M\u0026#244;n C\u0026#244;ng nghệ THCS cấp tỉnh Vĩnh Long (Thời gian 150 ph\u0026#250;t, Thang điểm 20):\u003c/em\u003e\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003e ĐỀ THI CH\u0026#205;NH THỨC - C\u0026#194;U 5 (3,0 ĐIỂM):\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003ea) Minh họa l\u0026#253; thuyết \u0026#39;C\u0026#226;y nghề nghiệp\u0026#39; của Phoenix Ho (2011). Căn cứ v\u0026#224;o c\u0026#225;c th\u0026#244;ng tin trong m\u0026#244; h\u0026#236;nh l\u0026#253; thuyết \u0026#39;C\u0026#226;y nghề nghiệp\u0026#39;, em h\u0026#227;y tr\u0026#236;nh b\u0026#224;y c\u0026#225;c nội dung cụ thể của c\u0026#225;c yếu tố ở phần rễ v\u0026#224; phần quả. (1,5 điểm)\u003cbr\u003eb) Theo l\u0026#253; thuyết mật m\u0026#227; Holland (John Holland, 1985), h\u0026#227;y vẽ v\u0026#224; ph\u0026#226;n t\u0026#237;ch m\u0026#244; h\u0026#236;nh 6 nh\u0026#243;m t\u0026#237;nh c\u0026#225;ch về lựa chọn nghề nghiệp. (1,5 điểm)\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003ch3\u003eHướng Dẫn Chấm \u0026 Bảng Đáp ÁN Điểm Chuẩn Của Sở GDĐT Vĩnh Long\u003c/h3\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003e\u0026#221;\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eNội dung đ\u0026#225;p \u0026#225;n chi tiết đạt chuẩn biểu điểm\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eĐiểm\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003ea\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eTr\u0026#236;nh b\u0026#224;y đ\u0026#250;ng kh\u0026#225;i niệm C\u0026#226;y nghề nghiệp gồm 2 phần cốt l\u0026#245;i: Phần Rễ v\u0026#224; Phần Quả.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e0,25đ\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003ea\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003ePhần Rễ: Thể hiện c\u0026#225;c yếu tố b\u0026#234;n trong bản th\u0026#226;n gồm: Sở th\u0026#237;ch, Khả năng (Năng lực), C\u0026#225; t\u0026#237;nh, Gi\u0026#225; trị nghề nghiệp.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e0,50đ\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003ea\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003ePhần Quả: Thể hiện c\u0026#225;c kết quả/mong muốn từ nghề nghiệp gồm: Cơ hội việc l\u0026#224;m, M\u0026#244;i trường l\u0026#224;m việc tốt, Lương cao, C\u0026#244;ng việc ổn định, Được nhiều người t\u0026#244;n trọng.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e0,50đ\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003ea\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eN\u0026#234;u được nguy\u0026#234;n l\u0026#253;: Chọn nghề ph\u0026#249; hợp với \u0026#39;gốc rễ\u0026#39; th\u0026#236; c\u0026#226;y nghề nghiệp mới ph\u0026#225;t triển bền vững v\u0026#224; cho ra \u0026#39;quả ngọt\u0026#39;.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e0,25đ\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eb\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eVẽ đ\u0026#250;ng Sơ đồ 6 nh\u0026#243;m t\u0026#237;nh c\u0026#225;ch Holland (H\u0026#236;nh lục gi\u0026#225;c / V\u0026#242;ng tr\u0026#242;n 6 nh\u0026#243;m: Kỹ thuật - Nghi\u0026#234;n cứu - Nghệ thuật - X\u0026#227; hội - Quản l\u0026#253; - Nghiệp vụ).\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e0,50đ\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eb\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003ePh\u0026#226;n t\u0026#237;ch Nh\u0026#243;m Kỹ thuật (R) \u0026amp; Nh\u0026#243;m Nghi\u0026#234;n cứu (I): Đặc điểm t\u0026#237;nh c\u0026#225;ch v\u0026#224; m\u0026#244;i trường l\u0026#224;m việc th\u0026#237;ch hợp.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e0,25đ\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eb\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003ePh\u0026#226;n t\u0026#237;ch Nh\u0026#243;m Nghệ thuật (A) \u0026amp; Nh\u0026#243;m X\u0026#227; hội (S): Đặc điểm t\u0026#237;nh c\u0026#225;ch v\u0026#224; m\u0026#244;i trường l\u0026#224;m việc th\u0026#237;ch hợp.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e0,25đ\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eb\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003ePh\u0026#226;n t\u0026#237;ch Nh\u0026#243;m Quản l\u0026#253; (E) \u0026amp; Nh\u0026#243;m Nghiệp vụ (C): Đặc điểm t\u0026#237;nh c\u0026#225;ch v\u0026#224; m\u0026#244;i trường l\u0026#224;m việc th\u0026#237;ch hợp.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e0,25đ\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eb\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eN\u0026#234;u được \u0026#253; nghĩa l\u0026#253; thuyết: Gi\u0026#250;p học sinh tự đối chiếu t\u0026#237;nh c\u0026#225;ch bản th\u0026#226;n với m\u0026#244;i trường nghề nghiệp tương ứng.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e0,25đ\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eTổng\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eTỔNG ĐIỂM C\u0026#194;U 5 (TỰ LUẬN HƯỚNG NGHIỆP)\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003e3,00đ\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e\u003ch2\u003ePHẦN III: NGÂN HÀNG BÀI TẬP PHÂN HÓA 4 MỨC ĐỘ \u0026 ĐÁP ÁN CHI TIẾT\u003c/h2\u003e\u003ch3\u003eMức độ 1: Nhận biết \u0026 Thông hiểu (Cơ bản)\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 1: \u003c/strong\u003eTr\u0026#236;nh b\u0026#224;y \u0026#253; nghĩa của việc lựa chọn đ\u0026#250;ng đắn nghề nghiệp đối với c\u0026#225; nh\u0026#226;n, gia đ\u0026#236;nh v\u0026#224; x\u0026#227; hội. N\u0026#234;u hậu quả khi học sinh chọn sai nghề nghiệp.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eĐ\u0026#225;p \u0026#225;n gợi \u0026#253;:\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e• Đối với c\u0026#225; nh\u0026#226;n: Chọn đ\u0026#250;ng nghề tạo động lực học tập, gi\u0026#250;p ph\u0026#225;t huy tối đa năng lực, phẩm chất, c\u0026#243; thu nhập ổn định v\u0026#224; mang lại niềm vui, hạnh ph\u0026#250;c trong c\u0026#244;ng việc.\u003cbr\u003e• Đối với gia đ\u0026#236;nh: Gi\u0026#250;p c\u0026#225; nh\u0026#226;n sớm tự lập, tạo nguồn thu nhập g\u0026#225;nh v\u0026#225;c kinh tế gia đ\u0026#236;nh v\u0026#224; chủ động x\u0026#226;y dựng kế hoạch tương lai.\u003cbr\u003e• Đối với x\u0026#227; hội: Tr\u0026#225;nh l\u0026#227;ng ph\u0026#237; nguồn lực đ\u0026#224;o tạo, giảm tỉ lệ thất nghiệp, ph\u0026#226;n bổ lực lượng lao động đồng đều, th\u0026#250;c đẩy kinh tế ph\u0026#225;t triển.\u003cbr\u003e• Hậu quả chọn sai nghề: Dễ ch\u0026#225;n nản, căng thẳng, kh\u0026#244;ng ph\u0026#225;t huy được năng lực, l\u0026#224;m việc k\u0026#233;m hiệu quả, nguy cơ bỏ nghề, l\u0026#227;ng ph\u0026#237; thời gian v\u0026#224; tiền bạc đ\u0026#224;o tạo lại.\u003c/p\u003e\u003ch3\u003eMức độ 2: Vận dụng (Phân tích \u0026 So sánh)\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 2: \u003c/strong\u003ePh\u0026#226;n t\u0026#237;ch điểm kh\u0026#225;c biệt cơ bản giữa Nh\u0026#243;m t\u0026#237;nh c\u0026#225;ch Kỹ thuật (R) v\u0026#224; Nh\u0026#243;m t\u0026#237;nh c\u0026#225;ch Nghi\u0026#234;n cứu (I) trong L\u0026#253; thuyết Holland. Cho v\u0026#237; dụ ng\u0026#224;nh nghề minh họa cho từng nh\u0026#243;m.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eĐ\u0026#225;p \u0026#225;n gợi \u0026#253;:\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e• Nh\u0026#243;m Kỹ thuật (R): \u003c/strong\u003eTh\u0026#237;ch l\u0026#224;m việc trực tiếp với đồ vật, m\u0026#225;y m\u0026#243;c, c\u0026#244;ng cụ, vận động ch\u0026#226;n tay, giải quyết vấn đề thực tế. M\u0026#244;i trường l\u0026#224;m việc thường l\u0026#224; xưởng sản xuất, c\u0026#244;ng trường, ph\u0026#242;ng m\u0026#225;y. (V\u0026#237; dụ: Thợ cơ kh\u0026#237;, Kỹ sư lắp r\u0026#225;p, Thợ điện).\u003cbr\u003e\u003cstrong\u003e• Nh\u0026#243;m Nghi\u0026#234;n cứu (I): \u003c/strong\u003eTh\u0026#237;ch l\u0026#224;m việc với tri thức, dữ liệu, kh\u0026#225;m ph\u0026#225; quy luật, tư duy trừu tượng, ph\u0026#226;n t\u0026#237;ch l\u0026#253; thuyết v\u0026#224; giải quyết vấn đề phức tạp. M\u0026#244;i trường l\u0026#224;m việc thường l\u0026#224; ph\u0026#242;ng th\u0026#237; nghiệm, trung t\u0026#226;m R\u0026amp;D, viện nghi\u0026#234;n cứu. (V\u0026#237; dụ: Nh\u0026#224; khoa học dữ liệu, Chuy\u0026#234;n gia vi sinh, Kỹ sư thiết kế thuật to\u0026#225;n AI).\u003c/p\u003e\u003ch3\u003eMức độ 3: Vận dụng cao (Lập luận \u0026 Giải quyết xung đột)\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 3: \u003c/strong\u003eBạn Nam l\u0026#224; học sinh lớp 9 c\u0026#243; sở th\u0026#237;ch đặc biệt với hội họa v\u0026#224; thiết kế đồ họa (Nh\u0026#243;m Nghệ thuật A). Tuy nhi\u0026#234;n, bố mẹ Nam bắt buộc Nam phải theo học ng\u0026#224;nh Kế to\u0026#225;n - Kiểm to\u0026#225;n (Nh\u0026#243;m Nghiệp vụ C) v\u0026#236; cho rằng ng\u0026#224;nh n\u0026#224;y c\u0026#244;ng việc ổn định v\u0026#224; dễ xin việc. Vận dụng L\u0026#253; thuyết C\u0026#226;y nghề nghiệp v\u0026#224; Holland, em h\u0026#227;y tư vấn cho Nam phương \u0026#225;n giải quyết b\u0026#224;i to\u0026#225;n hướng nghiệp n\u0026#224;y.\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eĐ\u0026#225;p \u0026#225;n gợi \u0026#253;:\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e1. Ph\u0026#226;n t\u0026#237;ch nguy\u0026#234;n nh\u0026#226;n xung đột:\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e• Bố mẹ Nam chọn nghề chỉ dựa v\u0026#224;o \u0026#39;Phần Quả\u0026#39; (ổn định, dễ xin việc) m\u0026#224; \u0026#225;p đặt l\u0026#234;n Nam.\u003cbr\u003e• Nam c\u0026#243; thi\u0026#234;n hướng t\u0026#237;nh c\u0026#225;ch thuộc Nh\u0026#243;m A (Nghệ thuật) - th\u0026#237;ch tự do, s\u0026#225;ng tạo, trong khi Kế to\u0026#225;n thuộc Nh\u0026#243;m C (Nghiệp vụ) - đ\u0026#242;i hỏi sự khu\u0026#244;n mẫu, cẩn thận với con số. Hai nh\u0026#243;m n\u0026#224;y nằm đối diện nhau tr\u0026#234;n sơ đồ Holland, t\u0026#237;nh chất c\u0026#244;ng việc xung đột mạnh.\u003cbr\u003e\u003cstrong\u003e2. Đề xuất quy tr\u0026#236;nh giải quyết 4 bước cho Nam:\u003c/strong\u003e\u003cstrong\u003e\u003cbr\u003e\u003c/strong\u003e• Bước 1 (Tự đ\u0026#225;nh gi\u0026#225;): Nam l\u0026#224;m trắc nghiệm Holland v\u0026#224; lập Bảng tự đ\u0026#225;nh gi\u0026#225; năng lực/sở th\u0026#237;ch thiết kế đồ họa để c\u0026#243; minh chứng khoa học.\u003cbr\u003e• Bước 2 (T\u0026#236;m hiểu thị trường): Tra cứu th\u0026#244;ng tin thị trường lao động về ng\u0026#224;nh Thiết kế đồ họa/UI-UX trong thời đại 4.0 (nhu cầu tuyển dụng cao, mức lương hấp dẫn, m\u0026#244;i trường năng động) để chứng minh ng\u0026#224;nh n\u0026#224;y cũng cho \u0026#39;quả ngọt\u0026#39; tốt.\u003cbr\u003e• Bước 3 (Thuyết phục gia đ\u0026#236;nh): Nam d\u0026#249;ng M\u0026#244; h\u0026#236;nh C\u0026#226;y nghề nghiệp giải th\u0026#237;ch cho bố mẹ hiểu rằng: Nếu \u0026#233;p Nam học Kế to\u0026#225;n (tr\u0026#225;i gốc rễ), Nam sẽ bị căng thẳng, l\u0026#224;m việc k\u0026#233;m v\u0026#224; c\u0026#226;y nghề nghiệp kh\u0026#243; cho quả tốt. Ngược lại, Thiết kế đồ họa đ\u0026#250;ng đam m\u0026#234; sẽ gi\u0026#250;p Nam th\u0026#224;nh c\u0026#244;ng.\u003cbr\u003e• Bước 4 (Phương \u0026#225;n kết hợp): Nam c\u0026#243; thể đề xuất học ng\u0026#224;nh Thiết kế c\u0026#244;ng nghiệp/Đồ họa truyền th\u0026#244;ng số tại c\u0026#225;c trường uy t\u0026#237;n, cam kết đạt kết quả học tập tốt.\u003c/p\u003e\u003ch3\u003eMức độ 4: Tình huống Thực tiễn \u0026 Dự án Tự Đánh giá Bản thân\u003c/h3\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#226;u 4 (Dự \u0026#225;n Tự chọn nghề): \u003c/strong\u003eLập Bảng Tự đ\u0026#225;nh gi\u0026#225; Mức độ Ph\u0026#249; hợp của Bản th\u0026#226;n đối với một Nghề nghiệp trong Lĩnh vực Kỹ thuật, C\u0026#244;ng nghệ (v\u0026#237; dụ: Nghề Lập tr\u0026#236;nh vi\u0026#234;n hoặc Kỹ sư Cơ kh\u0026#237;) theo mẫu chuẩn SGK C\u0026#244;ng nghệ 9.\u003c/p\u003e\u003cdiv class=\"tbl-wrap\"\u003e\u003ctable\u003e\u003ctr\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eYếu tố đ\u0026#225;nh gi\u0026#225;\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eĐặc điểm của bản th\u0026#226;n học sinh\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eY\u0026#234;u cầu của Nghề Lập tr\u0026#236;nh vi\u0026#234;n\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003cth\u003e\u003cp\u003e\u003cstrong\u003eMức độ ph\u0026#249; hợp\u003c/strong\u003e\u003c/p\u003e\u003c/th\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eNăng lực chuy\u0026#234;n m\u0026#244;n\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eHọc tốt To\u0026#225;n, Tin học; c\u0026#243; tư duy logic, th\u0026#237;ch giải c\u0026#225;c b\u0026#224;i to\u0026#225;n tư duy.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eHiểu biết ng\u0026#244;n ngữ lập tr\u0026#236;nh, tư duy thuật to\u0026#225;n, học ngoại ngữ tốt.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eTr\u0026#249;ng khớp (1đ)\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eSở th\u0026#237;ch c\u0026#225; nh\u0026#226;n\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eTh\u0026#237;ch kh\u0026#225;m ph\u0026#225; m\u0026#225;y t\u0026#237;nh, viết phần mềm, tạo ứng dụng di động.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eTh\u0026#237;ch l\u0026#224;m việc với c\u0026#244;ng nghệ, m\u0026#225;y t\u0026#237;nh, giải quyết lỗi logic phần mềm.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eTr\u0026#249;ng khớp (1đ)\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eC\u0026#225; t\u0026#237;nh (Holland)\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eNh\u0026#243;m I (Nghi\u0026#234;n cứu) \u0026amp; C (Nghiệp vụ): ki\u0026#234;n tr\u0026#236;, tập trung cao, cẩn thận.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eCần t\u0026#237;nh ki\u0026#234;n tr\u0026#236;, chịu được \u0026#225;p lực cao, khả năng l\u0026#224;m việc độc lập/nh\u0026#243;m.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eTr\u0026#249;ng khớp (1đ)\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eBối cảnh gia đ\u0026#236;nh\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eGia đ\u0026#236;nh ủng hộ, c\u0026#243; m\u0026#225;y t\u0026#237;nh kết nối internet hỗ trợ học tập.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eĐảm bảo chi ph\u0026#237; học Đại học/Cao đẳng ng\u0026#224;nh CNTT trong 3-4 năm.\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003eTr\u0026#249;ng khớp (1đ)\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003ctr\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eĐ\u0026#193;NH GI\u0026#193; CHUNG\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eTổng điểm ph\u0026#249; hợp: 4/4 Yếu tố cốt l\u0026#245;i\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eKẾT LUẬN: RẤT PH\u0026#217; HỢP VỚI NGHỀ LẬP TR\u0026#204;NH VI\u0026#202;N\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003ctd\u003e\u003cp\u003e\u003cstrong\u003eHO\u0026#192;N HẢO\u003c/strong\u003e\u003c/p\u003e\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\u003c/div\u003e"};